# A call-local grant held by the fixed-pair consumer, outside the request.
# Identity checks exclude an equivalent or copied request and another provider.
_V6_FIXED_PAIR_CALL: ContextVar[tuple[Any, Any] | None] = ContextVar(
    "_v6_fixed_pair_call", default=None
)


@contextmanager
def _v6_fixed_pair_request(provider: Any, request: Any):
    """Grant one fixed-pair execution its lightweight packet path."""

    token = _V6_FIXED_PAIR_CALL.set((provider, request))
    try:
        yield
    finally:
        _V6_FIXED_PAIR_CALL.reset(token)

