# Call-local host work. The provider, solver, runtime and data plane are never
# copied or entered concurrently. Image producers remain the existing ones.
_HOST_PREPLANNING_WINDOW: ContextVar[tuple[Any, Any, Any, list[Any]] | None] = ContextVar(
    "_host_preplanning_window", default=None
)


def _host_preplanning_before_read(provider: Any, ready: Any = None) -> None:
    grant = _HOST_PREPLANNING_WINDOW.get()
    if grant is not None and grant[0] is provider:
        if threading.current_thread() is not threading.main_thread():
            raise RuntimeError("host pre-planning must run on the main thread")
        # Prior decision records are flushed only after this look is enqueued.
        grant[2]()
        grant[1](ready)


def source_manifest_seal(tree: str | os.PathLike[str]) -> str:
    """Check the original source tree and return its manifest-byte seal."""

    root = Path(tree)
    manifest = root / "SOURCE_MANIFEST.sha256"
    payload = manifest.read_bytes()
    expected: dict[str, str] = {}
    for line in payload.decode("utf-8").splitlines():
        digest, separator, name = line.partition("  ./")
        path = Path(name)
        if (
            not separator or len(digest) != 64
            or any(char not in "0123456789abcdef" for char in digest)
            or not name or path.is_absolute() or ".." in path.parts
            or name in expected
        ):
            raise ValueError("source tree manifest has an invalid entry")
        expected[name] = digest
    actual = {
        path.relative_to(root).as_posix()
        for path in root.rglob("*")
        if path.is_file() and path != manifest
    }
    if actual != expected.keys():
        raise ValueError("source tree file set differs from its manifest")
    for name, digest in expected.items():
        path = root / name
        if path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise ValueError(f"source tree file differs from its manifest: {name}")
    return hashlib.sha256(payload).hexdigest()

