CALIBRATION_FOLDING_ENV = "IRG_CALIBRATION_FOLDING"


def calibration_folding_enabled() -> bool:
    """Physical calibration/oracle co-acquisition, pinned per provider."""

    value = os.environ.get(CALIBRATION_FOLDING_ENV, "0").strip()
    if value not in {"0", "1"}:
        raise ValueError(f"{CALIBRATION_FOLDING_ENV} must be '0' or '1'")
    return value == "1"


def class_balanced_calibration_weights(labels, target_class_id, class_count=None, *,
                                       population_class_counts=None, stratum_weights=None,
                                       weighting=None):
    """Row mass for the selected binary loss, correcting stratified draws.

    With ``per_image`` a population class count gives each sampled class row
    mass ``N_class / (N * n_class)``. A pooled binary draw instead uses its
    population stratum shares. A full population needs neither argument.
    Balanced loss assigns half the mass to the target class and equal shares
    of the other half to represented off-target classes, with equal row mass
    within each class. ``class_count`` is retained for existing callers.
    """
    mode = loss_weighting() if weighting is None else str(weighting)
    if mode not in {"balanced", "per_image"}:
        raise ValueError("loss weighting must be balanced or per_image")
    values = torch.as_tensor(labels).reshape(-1).to(dtype=torch.int64)
    on = values == int(target_class_id)
    on_count = on.sum().clamp_min(1).to(torch.float64)
    off_count = (~on).sum().clamp_min(1).to(torch.float64)
    if mode == "balanced":
        unique, inverse, drawn = torch.unique(values, sorted=True, return_inverse=True, return_counts=True)
        off_class_count = (unique != int(target_class_id)).sum().clamp_min(1).to(torch.float64)
        per_row_count = drawn.index_select(0, inverse).to(torch.float64)
        return torch.where(on, 0.5 / on_count, 0.5 / off_class_count / per_row_count)
    if population_class_counts is not None:
        counts = (dict(population_class_counts) if isinstance(population_class_counts, Mapping)
                  else dict(enumerate(population_class_counts)))
        counts = {int(key): float(value) for key, value in counts.items()}
        total = sum(counts.values())
        if total <= 0 or any(not math.isfinite(v) or v < 0 for v in counts.values()):
            raise ValueError("population class counts must be finite and nonnegative with positive total")
        unique, inverse, drawn = torch.unique(values, sorted=True, return_inverse=True, return_counts=True)
        represented = tuple(int(value) for value in unique.detach().cpu().tolist())
        if any(value > 0 and key not in set(represented) for key, value in counts.items()):
            raise ValueError("class-stratified calibration lacks a population class")
        if any(key not in counts or counts[key] <= 0 for key in represented):
            raise ValueError("sample class is absent from the population")
        population = torch.as_tensor([counts[key] for key in represented], device=values.device, dtype=torch.float64)
        if bool((population == drawn).all()):
            return torch.full_like(values, 1.0 / max(1, values.numel()), dtype=torch.float64)
        per_class = population / drawn.to(torch.float64) / total
        return per_class.index_select(0, inverse)
    if stratum_weights is not None:
        positive = float(stratum_weights["on_target"])
        negative = float(stratum_weights["off_target"])
        if (not math.isfinite(positive + negative) or min(positive, negative) <= 0
                or not math.isclose(positive + negative, 1.0, abs_tol=1e-10)):
            raise ValueError("population stratum shares must be positive and sum to one")
        if not bool(on.any()) or not bool((~on).any()):
            raise ValueError("stratified calibration requires both binary strata")
        return torch.where(on, positive / on_count, negative / off_count)
    return torch.full_like(values, 1.0 / max(1, values.numel()), dtype=torch.float64)


def _provider_loss_weighting(provider):
    return getattr(provider, "loss_weighting", loss_weighting())


@contextmanager
def _substituted_reporting_context(provider):
    """Give scalar reporting its own weights without changing walk state.

    The shallow view shares readout caches and execution accounting. Only
    the reporting estimand and its solver options belong to the view.
    """
    from copy import copy

    view = copy(provider)
    view.loss_weighting = "per_image"
    view._substituted_per_image_reporting = True
    pi = _terminal_training_prevalence(provider)
    view._stratum_weights = {"on_target": pi, "off_target": 1.0 - pi}
    view.calibration_options = dict(provider.calibration_options)
    view.calibration_options["binary_loss_weighting"] = "design_weighted"
    view.calibration_options["iters"] = max(320, int(view.calibration_options.get("iters", 0)))
    local = {"loss_weighting", "_stratum_weights", "calibration_options",
             "_substituted_per_image_reporting"}
    try:
        yield view
    finally:
        # Preserve newly initialized caches and actual execution counters.
        # The terminal reporting calls are synchronous and do not run walks.
        for name, value in vars(view).items():
            if name not in local and getattr(provider, name, None) is not value:
                setattr(provider, name, value)


def _calibration_algorithm_id(provider):
    """Name the fitted penalty, retaining the registered solver contract."""
    if provider.calibration_options.get("calibration_penalty") == "firth":
        return "firth_positive_affine_v1"
    return str(provider.calibration_options["optimization_contract"])


def _evaluation_loss_weights(provider, populations, weights, population_stratum_weights=None):
    """Use declared population shares for a sampled evaluation panel.

    Without a separate population measure, the provided rows define the
    evaluation population and each of those images receives equal mass.
    """
    if _provider_loss_weighting(provider) == "per_image":
        if population_stratum_weights is not None:
            return {str(key): float(value) for key, value in population_stratum_weights.items()}
        total = sum(len(rows) for rows in populations.values())
        if total:
            return {key: len(rows) / total for key, rows in populations.items()}
    return weights


def _terminal_training_prevalence(provider):
    """The full training population prior, never the sampled fit-row share."""
    if _provider_loss_weighting(provider) == "per_image":
        return float(provider._stratum_weights["on_target"])
    # Legacy disjoint roles partition the population; IID roles name the
    # same population. The union counts each training image once in both.
    counts = {key: len(set(provider._calibration_orders[key]).union(
        provider._oracle_orders[key])) for key in ("on_target", "off_target")}
    return counts["on_target"] / sum(counts.values())


def _substituted_target_wins_top_1(target_score, dense_rows, target):
    """Argmax with lowest-index ties, without copying the competitor matrix."""
    selected = torch.ones_like(target_score, dtype=torch.bool)
    if target > 0:
        selected &= target_score > dense_rows[:, :target].max(dim=1).values
    if target + 1 < int(dense_rows.shape[1]):
        selected &= target_score >= dense_rows[:, target + 1:].max(dim=1).values
    return selected


def _per_image_terminal_metrics(provider, populations, bce_means, accuracy_means, stratum_weights=None):
    if _provider_loss_weighting(provider) != "per_image":
        return {}
    total = sum(len(rows) for rows in populations.values())
    weights = ({key: len(rows) / total for key, rows in populations.items()}
               if stratum_weights is None else dict(stratum_weights))
    off_total = sum(value for key, value in weights.items() if key != "on_target")
    specificity = sum(weights[key] * accuracy_means[key] for key in populations
                      if key != "on_target") / off_total
    sensitivity = float(accuracy_means["on_target"])
    return {"loss_weighting": "per_image",
            "per_image_binary_bce": float(sum(weights[key] * bce_means[key] for key in populations)),
            "per_image_binary_accuracy": float(sum(weights[key] * accuracy_means[key] for key in populations)),
            "corrected_binary_accuracy": sensitivity + specificity - 1.0,
            "sensitivity": sensitivity, "specificity": float(specificity)}


def class_balanced_auc(raw_scores, class_ids, target_class_id):
    """Mean target-versus-class rank AUC, with half credit for equal scores."""
    scores = np.asarray(raw_scores, dtype=np.float64).reshape(-1)
    classes = np.asarray(class_ids, dtype=np.int64).reshape(-1)
    if scores.shape != classes.shape or not np.isfinite(scores).all():
        raise ValueError("AUC requires aligned finite raw logits and class IDs")
    target = int(target_class_id)
    positive = np.sort(scores[classes == target])
    off = np.unique(classes[classes != target])
    if positive.size == 0 or off.size == 0:
        raise ValueError("AUC requires target and off-target observations")
    per_class = {}
    for class_id in off:
        negative = scores[classes == class_id]
        below = np.searchsorted(positive, negative, side="left")
        above = np.searchsorted(positive, negative, side="right")
        per_class[str(int(class_id))] = float(np.mean(
            (positive.size - above + 0.5 * (above - below)) / positive.size))
    return {"class_balanced_auc": float(np.mean(tuple(per_class.values()))),
            "off_target_class_auc": per_class,
            "auc_off_target_class_count": int(off.size),
            "auc_score": "raw_target_logit"}


def _search_fit_statistics_backend(device: Any) -> str:
    """Keep the search reducer independent of the reference-audit policy."""

    return "triton" if device.type == "cuda" else "torch"


def fused_calibration_oracle_batch_rows(profile: Any, *, paired: bool = False) -> int:
    """The role-bound union shape shared by execution and prewarming."""

    return max(
        int(profile.calibration_batch_rows),
        int(profile.v1_candidate_oracle_batch_rows),
        (
            int(profile.calibration_batch_rows) + int(profile.v0_paired_oracle_batch_rows)
            if paired else 0
        ),
    )



