_POPULATION_SOLVER_WARMED_DEVICES: set[int] = set()
_POPULATION_SOLVER_WARM_LOCK = threading.Lock()


def _warm_population_solver_once(device: Any) -> None:
    """Initialize the worker's solver before candidate-fit allocator pressure."""

    if torch is None or torch.device(device).type != "cuda":
        return
    index = torch.device(device).index
    if index is None:
        index = int(torch.cuda.current_device())
    with _POPULATION_SOLVER_WARM_LOCK:
        if index in _POPULATION_SOLVER_WARMED_DEVICES:
            return
        torch.linalg.pinv(
            torch.eye(2, dtype=torch.float64, device=torch.device("cuda", index)),
            hermitian=True,
        )
        # A failed initialization remains retryable by the next item.
        _POPULATION_SOLVER_WARMED_DEVICES.add(index)


# ---------------------------------------------------------------------------
# IRG_COMPILE_COVERAGE (default OFF): torch.compile (default mode) over the
# remaining eager hot-loop tensor callables.  With the env unset the factory
# returns the ORIGINAL callable object unchanged, so the OFF state is
# provably inert.  Compilation only
# fuses/reorders floating-point elementwise work — the accepted algorithmic
# equivalence class — and never touches float64 registered accumulators or
# certificate math, which stay on their eager (or numpy) paths.
# ---------------------------------------------------------------------------

_COMPILE_COVERAGE_CACHE: dict[str, Any] = {}
# Receipt record of paths requested by this item, including cached callables.
# The persistent driver clears it at the item boundary, keeping the cache.
_COMPILE_COVERAGE_PATHS: dict[str, str] = {}
_TERMINAL_COMPILE_ENV = "IRG_TERMINAL_COMPILE"
_LOCAL_TRUTHY_TOKENS = frozenset({"1", "true", "yes", "on"})
_LOCAL_FALSY_TOKENS = frozenset({"0", "false", "no", "off"})

# Hot paths examined and DELIBERATELY left eager, with the reason.  Recorded
# in the receipt beside the compiled set so the canary sees the whole survey.
_COMPILE_COVERAGE_DECLINED: dict[str, str] = {
    "_dense_logsumexp_exclusion": (
        "in-place buffer-reuse arithmetic pinned bitwise by "
        "test_dense_exclusion_buffer_reuse_is_bitwise; inductor refusing or "
        "re-fusing the in-place chain would silently void that documented "
        "contract, and the path runs only on step-category lanes"
    ),
    "_device_running_moment": (
        "two-op float64 reduction ending in host .item() syncs (graph "
        "break); nothing to fuse"
    ),
    "_fit_fixed_offset_affine_l2": (
        "registered float64 Newton solver with data-dependent host-side "
        "convergence tests; registered-quantity precision must stay verbatim"
    ),
    "_fit_terminal_category_calibrations": (
        "chunked float64 Newton solves (registered algorithm) with python "
        "chunk orchestration; per-chunk shapes vary with the category axis"
    ),
    "step_category_matrix_lanes (_reduce_family/_calibrated_rows/...)": (
        "python dict/string bookkeeping around small per-decision tensors "
        "(~one call per walk decision); negligible device time, graph-broken"
    ),
    "terminal_category_matrix_buffer_writes_and_host_reductions": (
        "in-place row-buffer writes are alias-sensitive, followed by device-to-"
        "host numpy transfer and Python segment means; compilation is limited "
        "to the pure per-category tensor bodies"
    ),
    "tracker_decision_update/hierarchical_shrinkage_device": (
        "float64 row windows and indexed sufficient-statistic sums on the device"
    ),
}


def _terminal_compile_requested(
    environ: Mapping[str, str] | None = None,
) -> bool:
    """Return the terminal micro-fusion gate (DEFAULT ON;
    decision-safety audited alongside fp32 rows — byte-identical
    mask and price vs fp64 references; explicit =0 opts out)."""

    values = os.environ if environ is None else environ
    return (
        str(values.get(_TERMINAL_COMPILE_ENV, "1")).strip().lower()
        in _LOCAL_TRUTHY_TOKENS
    )


def _compile_coverage_callable(
    name: str,
    fn: Any,
    *,
    requested: bool | None = None,
) -> tuple[Any, bool]:
    """Return ``(callable, is_compiled)`` for one named coverage path.

    Gate OFF -> the exact original function object (inert).  Gate ON but no
    CUDA/torch.compile -> the original function with the refusal reason
    recorded (import-safe on CPU-only machines).  Gate ON with CUDA -> a
    cached default-mode dynamic ``torch.compile`` wrapper.
    """

    if requested is None:
        requested = _perf_gates.compile_coverage_requested()
    if not requested:
        _COMPILE_COVERAGE_PATHS[name] = "eager:gate_off"
        return fn, False
    cached = _COMPILE_COVERAGE_CACHE.get(name)
    if cached is not None:
        _COMPILE_COVERAGE_PATHS[name] = "compiled:default_mode_dynamic"
        return cached, True
    if torch is None or not hasattr(torch, "compile"):
        _COMPILE_COVERAGE_PATHS[name] = "eager:torch_compile_unavailable"
        return fn, False
    if not torch.cuda.is_available():
        _COMPILE_COVERAGE_PATHS[name] = "eager:no_cuda_device"
        return fn, False
    compiled = torch.compile(fn, dynamic=True)
    _COMPILE_COVERAGE_CACHE[name] = compiled
    _COMPILE_COVERAGE_PATHS[name] = "compiled:default_mode_dynamic"
    return compiled, True


def _terminal_compile_coverage_callable(
    name: str,
    fn: Any,
) -> tuple[Any, bool]:
    """Apply terminal-only policy while reusing the generic CUDA factory."""

    return _compile_coverage_callable(
        name,
        fn,
        requested=_terminal_compile_requested(),
    )


def compile_coverage_receipt() -> dict[str, Any]:
    """Receipt block proving which coverage paths engaged (or why not)."""

    standard_requested = bool(_perf_gates.compile_coverage_requested())
    terminal_requested = bool(_terminal_compile_requested())
    return {
        "schema": "irg_compile_coverage_v1",
        "requested": standard_requested or terminal_requested,
        "standard_requested": standard_requested,
        "terminal_requested": terminal_requested,
        "paths": dict(sorted(_COMPILE_COVERAGE_PATHS.items())),
        "declined_eager_paths": dict(
            sorted(_COMPILE_COVERAGE_DECLINED.items())
        ),
    }


def resolved_maximum_fused_lanes(
    requested: int,
    environ: Mapping[str, str] | None = None,
) -> tuple[int, str]:
    """IRG_SINGLE_PAIR_WALK (DEFAULT ON): pin fused chunk width to one pair.

    Single-pair mode resolves the fused lane ceiling to 2 — one launch per
    walk step carrying exactly (parent, next mask) — so with forward prefix
    reuse the shared sub-fork prefix runs once and only the two suffixes
    vmap from the boundary activations.  The explicit legacy opt-out
    (``IRG_SINGLE_PAIR_WALK=0``) keeps the caller's requested width (the
    historical chunked-8 physical path) for comparison canaries and
    reproduction.  Physical fusion width never changes which draws are made
    or what is computed per lane, so this is execution policy under the
    algorithmic-equivalence bar; the resolved and requested widths are both
    receipted.
    """

    mode = _perf_gates.walk_execution_mode(environ)
    if mode == "single_pair":
        return 2, mode
    return int(requested), mode


def _single_fit_bce_rows(
    values_column: Any,
    labels: Any,
    scale: Any,
    center: Any,
    offset: Any,
    clip_value: float | None,
    target_class_id: int,
    fixed_offsets: Any = None,
) -> Any:
    """Elementwise calibrated binary BCE rows (single frozen affine fit).

    Exactly the registered arithmetic of
    ``_binary_bce_device_rows``: affine calibration, optional symmetric clip,
    softplus BCE under the 1/2-on 1/2-off binary labels.  Factored to module
    scope so IRG_COMPILE_COVERAGE can hand it to ``torch.compile``; scalar
    fit parameters arrive as 0-dim tensors on the compiled path so a new fit
    never forces a recompile.
    """

    logits = scale * (values_column - center) + offset
    if fixed_offsets is not None:
        logits = logits + fixed_offsets
    if clip_value is not None:
        logits = torch.clamp(logits, min=-clip_value, max=clip_value)
    binary = labels == int(target_class_id)
    return torch.where(
        binary,
        torch.nn.functional.softplus(-logits),
        torch.nn.functional.softplus(logits),
    )


def _crossfit_bce_rows(
    values_column: Any,
    labels: Any,
    scales: Any,
    centers: Any,
    offsets: Any,
    fold_index: Any,
    clip_value: float | None,
    target_class_id: int,
    fixed_offsets: Any = None,
) -> Any:
    """Elementwise fold-owned calibrated BCE rows (cross-fitted affines).

    Exactly the registered arithmetic of
    ``_binary_bce_device_rows_crossfit``.
    """

    logits = (
        scales[fold_index] * (values_column - centers[fold_index])
        + offsets[fold_index]
    )
    if fixed_offsets is not None:
        logits = logits + fixed_offsets
    if clip_value is not None:
        logits = torch.clamp(logits, min=-clip_value, max=clip_value)
    binary = labels == int(target_class_id)
    return torch.where(
        binary,
        torch.nn.functional.softplus(-logits),
        torch.nn.functional.softplus(logits),
    )


def _raw_sha256(value: object) -> str:
    return content_hash(value)


def _ordered_context_ids_hash(context_ids: Sequence[str]) -> str:
    """Hash an exact ordered terminal-census context axis."""

    return content_hash(
        {
            "schema": "terminal_category_ordered_context_ids_v1",
            "ordered_context_ids": tuple(str(value) for value in context_ids),
        }
    )


# Live (width x contexts) planes inside _dense_logsumexp_exclusion, COUNTED
# from its source rather than estimated, at the worst point of the function
# (need_maximum=False, which is what _dense_exclusion_rows requests).
#
# The reduction from 7 to 4 is pure buffer reuse: every intermediate below is
# now formed IN PLACE in the buffer that produced it, so the arithmetic and its
# order are unchanged.  ``a - b`` becomes ``(-b) + a`` and ``m + log(r)``
# becomes ``log(r) + m``; IEEE-754 negation is exact and addition is
# bitwise-commutative, so both rewrites are bit-identical, not merely
# equivalent to rounding.  ``test_dense_exclusion_buffer_reuse_is_bitwise``
# pins that against a literal transcription of the pre-reuse implementation.
#
#   float64: values, one live temporary (the second-maximum ``remainder``,
#            freed before ``shifted_terms`` is allocated; ``shifted_terms``
#            then becomes remaining_sum and exclusion_lse in place)
#            -> 3 planes at the peak
#   float32: the caller's transposed-contiguous input and the returned chunk
#            -> 2 planes, i.e. 1 float64-equivalent
# Total 4 float64-equivalents = 32 bytes per (width x context) element.
#
# The budget is unchanged, so the derived context chunk grows by 7/4 = 1.75x;
# chunking only partitions a reduction whose contexts never interact, so this
# changes how many columns are held at once and nothing that is produced.
DENSE_EXCLUSION_BYTES_PER_ELEMENT = 4 * 8
DENSE_EXCLUSION_BUDGET_ENV = "IRG_DENSE_EXCLUSION_BUDGET_BYTES"
DENSE_EXCLUSION_CHUNK_OVERRIDE_ENV = "IRG_DENSE_EXCLUSION_CONTEXT_CHUNK"
# The DECLARED quantity is a peak-working-set budget, not a chunk count. 1 GiB
# is ~0.3% of the 360 GiB per-GPU cap, so the offset field cannot be what
# exhausts it at any readout width.
DEFAULT_DENSE_EXCLUSION_BUDGET_BYTES = 1 << 30


def _positive_int_env(name: str) -> int | None:
    raw = os.environ.get(name, "").strip()
    if not raw:
        return None
    try:
        value = int(raw)
    except ValueError as error:
        raise ValueError(f"{name} must be a positive integer") from error
    if value <= 0:
        raise ValueError(f"{name} must be a positive integer")
    return value


def _dense_exclusion_context_chunk(width: int) -> int:
    """Derive the context chunk from a declared peak-memory budget.

    The registered quantity is the BUDGET; the chunk is a consequence:

        chunk = floor(budget_bytes / (bytes_per_element * width))

    This is deliberately not a hand-picked constant. A chunk count is only
    meaningful relative to a readout width, so a fixed number silently changes
    its memory meaning when the width changes -- which it does the moment a
    reference system other than the 1000-logit dense readout is bound (an NSD
    voxel panel has its own width). Deriving from a budget keeps peak memory
    invariant across reference systems instead of keeping an arbitrary count
    invariant.

    It also makes semantics-neutrality structural rather than asserted: this
    value only partitions a reduction whose contexts never interact, so no
    setting can change a produced value, only how many are held at once.

    IRG_DENSE_EXCLUSION_CONTEXT_CHUNK still pins an exact chunk when a run
    needs to reproduce a specific partitioning.
    """

    override = _positive_int_env(DENSE_EXCLUSION_CHUNK_OVERRIDE_ENV)
    if override is not None:
        return override
    budget = (
        _positive_int_env(DENSE_EXCLUSION_BUDGET_ENV)
        or DEFAULT_DENSE_EXCLUSION_BUDGET_BYTES
    )
    budget = process_device_memory_budget_bytes(budget)
    per_context = DENSE_EXCLUSION_BYTES_PER_ELEMENT * max(1, int(width))
    return max(1, int(budget // per_context))


def _dense_logsumexp_exclusion(
    dense_logits: Any, *, need_maximum: bool = True
) -> tuple[Any, Any]:
    """Return stable per-category exclusion logsumexp and exclusion maxima.

    The dangerous argmax exclusion is recomputed against a fresh shift over
    the remaining categories.  In particular, this never evaluates
    ``log(exp(logsumexp(z)) - exp(z_l))``, whose subtraction catastrophically
    cancels when ``z_l`` dominates its column.
    """

    if torch is None:
        raise RuntimeError("dense exclusion logsumexp requires PyTorch")
    return_numpy = isinstance(dense_logits, np.ndarray)
    values = torch.as_tensor(dense_logits, dtype=torch.float64)
    if values.ndim != 2 or int(values.shape[0]) < 2:
        raise ValueError(
            "dense exclusion logsumexp requires [width, contexts] with width >= 2"
        )
    DEVICE_FAULTS.note(
        ~torch.isfinite(values).all(),
        lambda: ValueError("dense exclusion logits must be finite"),
    )

    width, context_count = (int(values.shape[0]), int(values.shape[1]))
    del width
    maximum, argmax = values.max(dim=0)
    # ``expand_as(...).clone()`` materializes a full [width, contexts] tensor
    # whose columns are constant. Callers that only need the LSE (the step
    # category accumulator discards this return) can skip it -- with float64
    # temporaries at ~56 KB per context, two fewer full-size allocations is a
    # material saving on wide panels.
    exclusion_maximum = (
        maximum.unsqueeze(0).expand_as(values).clone()
        if need_maximum
        else None
    )

    columns = torch.arange(context_count, device=values.device)
    # The dangerous-argmax branch is resolved FIRST and its buffer released
    # before the main branch allocates, so the two never coexist.  ``remainder``
    # is consumed in place: subtract the shift, exponentiate, reduce.
    remainder = values.clone()
    remainder[argmax, columns] = -torch.inf
    second_maximum = remainder.max(dim=0).values
    second_sum = remainder.sub_(second_maximum.unsqueeze(0)).exp_().sum(dim=0)
    second_lse = second_maximum + torch.log(second_sum)
    del remainder

    shifted_terms = values.sub(maximum.unsqueeze(0)).exp_()
    shifted_sum = shifted_terms.sum(dim=0)
    # shifted_terms -> remaining_sum -> exclusion_lse, all in the one buffer.
    remaining_sum = shifted_terms.neg_().add_(shifted_sum.unsqueeze(0))
    exclusion_lse = remaining_sum.log_().add_(maximum.unsqueeze(0))
    exclusion_lse[argmax, columns] = second_lse
    if exclusion_maximum is not None:
        exclusion_maximum[argmax, columns] = second_maximum

    nonfinite = ~torch.isfinite(exclusion_lse).all()
    if exclusion_maximum is not None:
        nonfinite |= ~torch.isfinite(exclusion_maximum).all()
    DEVICE_FAULTS.note(
        nonfinite,
        lambda: ValueError("dense exclusion logsumexp produced nonfinite values"),
    )
    if return_numpy:
        DEVICE_FAULTS.settle(block=True)
        return (
            exclusion_lse.cpu().numpy(),
            None
            if exclusion_maximum is None
            else exclusion_maximum.cpu().numpy(),
        )
    return exclusion_lse, exclusion_maximum


@dataclass(slots=True)
class _DenseExclusionStreamingPlan:
    """Bounded exact dense-exclusion source over the category axis.

    A complete ImageNet exclusion matrix has ``width * contexts`` float64
    elements (roughly 10 GiB for the registered training census).  The
    substituted calibration only consumes one small category chunk at a
    time.  This plan keeps the original float32 dense logits plus O(context)
    sufficient statistics and reconstructs an exact float64 exclusion chunk
    on demand.

    The non-argmax branch is safe because removing a nonmaximum coordinate
    leaves the maximum's unit shifted term in the sum.  The dangerous argmax
    branch uses an independently reduced second logsumexp, matching
    ``_dense_logsumexp_exclusion`` without subtractive cancellation.
    """

    dense_logits_by_category: Any
    maximum: Any
    shifted_sum: Any
    argmax: Any
    second_logsumexp: Any

    @classmethod
    def build(cls, dense_logits_by_category: Any) -> _DenseExclusionStreamingPlan:
        if torch is None:
            raise RuntimeError("dense exclusion streaming requires PyTorch")
        values = torch.as_tensor(dense_logits_by_category)
        if values.ndim != 2 or int(values.shape[0]) < 2:
            raise ValueError(
                "dense exclusion streaming requires [width, contexts]"
            )
        if not bool(torch.isfinite(values).all().item()):
            raise ValueError("dense exclusion streaming logits must be finite")
        width, context_count = int(values.shape[0]), int(values.shape[1])
        maximum = torch.empty(
            context_count, device=values.device, dtype=torch.float64
        )
        shifted_sum = torch.empty_like(maximum)
        second_logsumexp = torch.empty_like(maximum)
        argmax = torch.empty(
            context_count, device=values.device, dtype=torch.int64
        )
        context_chunk = _dense_exclusion_context_chunk(width)
        for start in range(0, context_count, context_chunk):
            stop = min(context_count, start + context_chunk)
            block = values[:, start:stop].to(dtype=torch.float64, copy=True)
            block_maximum, block_argmax = block.max(dim=0)
            columns = torch.arange(
                stop - start, device=values.device, dtype=torch.int64
            )
            remainder = block.clone()
            remainder[block_argmax, columns] = -torch.inf
            second_maximum = remainder.max(dim=0).values
            second_sum = (
                remainder.sub_(second_maximum.unsqueeze(0)).exp_().sum(dim=0)
            )
            second_logsumexp[start:stop] = second_maximum + torch.log(
                second_sum
            )
            shifted_sum[start:stop] = (
                block.sub_(block_maximum.unsqueeze(0)).exp_().sum(dim=0)
            )
            maximum[start:stop] = block_maximum
            argmax[start:stop] = block_argmax
        if not bool(torch.isfinite(second_logsumexp).all().item()):
            raise ValueError(
                "dense exclusion streaming second logsumexp is nonfinite"
            )
        return cls(
            dense_logits_by_category=values,
            maximum=maximum,
            shifted_sum=shifted_sum,
            argmax=argmax,
            second_logsumexp=second_logsumexp,
        )

    @property
    def shape(self) -> tuple[int, int]:
        return tuple(int(value) for value in self.dense_logits_by_category.shape)

    def select(self, columns: Any) -> Any:
        selected_columns = torch.as_tensor(
            columns,
            device=self.dense_logits_by_category.device,
            dtype=torch.int64,
        ).reshape(-1)
        if int(selected_columns.numel()) <= 0 or bool(
            (selected_columns < 0).any().item()
            or (selected_columns >= self.shape[0]).any().item()
        ):
            raise ValueError("dense exclusion category chunk is invalid")
        selected = self.dense_logits_by_category.index_select(
            0, selected_columns
        ).to(torch.float64)
        remaining = self.shifted_sum.unsqueeze(0) - torch.exp(
            selected - self.maximum.unsqueeze(0)
        )
        exclusion = torch.log(remaining).add_(self.maximum.unsqueeze(0))
        dangerous = selected_columns.unsqueeze(1) == self.argmax.unsqueeze(0)
        exclusion = torch.where(
            dangerous,
            self.second_logsumexp.unsqueeze(0),
            exclusion,
        )
        if not bool(torch.isfinite(exclusion).all().item()):
            raise ValueError("dense exclusion streamed chunk is nonfinite")
        return exclusion


def _fixed_offset_affine_l2_statistics(
    values: Any,
    targets: Any,
    fixed_offsets: Any,
    *,
    scale: Any,
    offset: Any,
    identity_anchor_strength: Any,
    row_validity: Any | None = None,
) -> Mapping[str, Any]:
    """Evaluate the fixed-offset, class-balanced L2 affine objective."""

    if torch is None:
        raise RuntimeError("fixed-offset affine statistics require PyTorch")
    x = torch.as_tensor(values, dtype=torch.float64).reshape(-1)
    y = torch.as_tensor(targets, device=x.device, dtype=torch.float64).reshape(-1)
    fixed = torch.as_tensor(
        fixed_offsets, device=x.device, dtype=torch.float64
    ).reshape(-1)
    if tuple(y.shape) != tuple(x.shape) or tuple(fixed.shape) != tuple(x.shape):
        raise ValueError("fixed-offset affine sample axes are misaligned")
    if not bool(torch.isfinite(x).all().item()) or not bool(
        torch.isfinite(fixed).all().item()
    ):
        raise ValueError("fixed-offset affine inputs must be finite")

    scales = torch.as_tensor(scale, device=x.device, dtype=torch.float64).reshape(-1)
    intercepts = torch.as_tensor(
        offset, device=x.device, dtype=torch.float64
    ).reshape(-1)
    strengths = torch.as_tensor(
        identity_anchor_strength, device=x.device, dtype=torch.float64
    ).reshape(-1)
    lane_count = max(
        int(scales.numel()), int(intercepts.numel()), int(strengths.numel())
    )
    for name, tensor in (
        ("scale", scales),
        ("offset", intercepts),
        ("identity anchor", strengths),
    ):
        if int(tensor.numel()) not in {1, lane_count}:
            raise ValueError(f"fixed-offset affine {name} lane axis is misaligned")
    scales = scales.expand(lane_count)
    intercepts = intercepts.expand(lane_count)
    strengths = strengths.expand(lane_count)
    if bool((strengths <= 0.0).any().item()) or not bool(
        torch.isfinite(strengths).all().item()
    ):
        raise ValueError("fixed-offset affine anchors must be positive and finite")

    if row_validity is None:
        validity = torch.ones(
            (lane_count, int(x.numel())), device=x.device, dtype=torch.float64
        )
    else:
        validity = torch.as_tensor(
            row_validity, device=x.device, dtype=torch.float64
        )
        if validity.ndim == 1:
            validity = validity.reshape(1, -1)
        if tuple(validity.shape) == (1, int(x.numel())) and lane_count > 1:
            validity = validity.expand(lane_count, -1)
        if tuple(validity.shape) != (lane_count, int(x.numel())):
            raise ValueError("fixed-offset affine row validity is misaligned")
        if not bool(((validity == 0.0) | (validity == 1.0)).all().item()):
            raise ValueError("fixed-offset affine row validity must be binary")

    row_count = validity.sum(dim=1)
    positives = (validity * y.unsqueeze(0)).sum(dim=1)
    negatives = row_count - positives
    if bool(
        ((row_count <= 0.0) | (positives <= 0.0) | (negatives <= 0.0))
        .any()
        .item()
    ):
        raise ValueError("fixed-offset affine rows require both binary classes")
    weights = torch.where(
        y.unsqueeze(0) > 0.5,
        (negatives / positives).unsqueeze(1),
        torch.ones(
            (lane_count, int(x.numel())),
            device=x.device,
            dtype=torch.float64,
        ),
    ) * validity
    centered = x  # input_center is fixed by contract at exactly 0.0.
    logits = (
        scales.unsqueeze(1) * centered.unsqueeze(0)
        + intercepts.unsqueeze(1)
        + fixed.unsqueeze(0)
    )
    probabilities = torch.sigmoid(logits)
    residual = weights * (probabilities - y.unsqueeze(0))
    curvature = weights * probabilities * (1.0 - probabilities)
    objective = (
        weights
        * (torch.nn.functional.softplus(logits) - y.unsqueeze(0) * logits)
    ).sum(dim=1) / row_count + strengths * (
        (scales - 1.0).square() + intercepts.square()
    )
    gradient_scale = (
        (residual * centered.unsqueeze(0)).sum(dim=1) / row_count
        + 2.0 * strengths * (scales - 1.0)
    )
    gradient_offset = (
        residual.sum(dim=1) / row_count
        + 2.0 * strengths * intercepts
    )
    hessian_scale = (
        (curvature * centered.square().unsqueeze(0)).sum(dim=1) / row_count
        + 2.0 * strengths
    )
    hessian_cross = (
        (curvature * centered.unsqueeze(0)).sum(dim=1) / row_count
    )
    hessian_offset = curvature.sum(dim=1) / row_count + 2.0 * strengths
    return {
        "objective": objective,
        "gradient_scale": gradient_scale,
        "gradient_offset": gradient_offset,
        "hessian_scale": hessian_scale,
        "hessian_cross": hessian_cross,
        "hessian_offset": hessian_offset,
    }


# The fixed-offset (substituted-functional) Newton solvers'
# convergence test.  ``raw_gradient_v1`` (default) is the test on the raw
# gradient pair, bitwise unchanged.  ``projected_kkt_active_set_v1`` tests
# the projected gradient of the bound-constrained problem (scale >= minimum):
# at the bound the scale residual is ``max(0, -df/ds)``, and a lane whose
# scale sits at the bound with ``df/ds >= 0`` is in the active set, so its
# Newton step fixes the scale and takes the reduced offset step
# ``-df/db / d2f/db2``.  This is the convention the ordinary backend already
# uses (``backends/calibration_backend.py``); interior lanes follow exactly
# the raw-gradient iterates.  Opt-in only; the default is the raw test.
FIXED_OFFSET_AFFINE_CONVERGENCE_ENV = "IRG_FIXED_OFFSET_AFFINE_CONVERGENCE"
FIXED_OFFSET_AFFINE_CONVERGENCE_RAW = "raw_gradient_v1"
FIXED_OFFSET_AFFINE_CONVERGENCE_PROJECTED = "projected_kkt_active_set_v1"
FIXED_OFFSET_AFFINE_CONVERGENCE_TESTS = frozenset(
    {FIXED_OFFSET_AFFINE_CONVERGENCE_RAW, FIXED_OFFSET_AFFINE_CONVERGENCE_PROJECTED}
)


def fixed_offset_affine_convergence_setting(
    environ: Mapping[str, str] | None = None,
) -> str:
    """Resolve ``IRG_FIXED_OFFSET_AFFINE_CONVERGENCE`` (default raw)."""

    source = os.environ if environ is None else environ
    raw = source.get(FIXED_OFFSET_AFFINE_CONVERGENCE_ENV)
    if raw is None or not str(raw).strip():
        return FIXED_OFFSET_AFFINE_CONVERGENCE_RAW
    value = str(raw).strip().lower()
    if value not in FIXED_OFFSET_AFFINE_CONVERGENCE_TESTS:
        raise ValueError(
            f"{FIXED_OFFSET_AFFINE_CONVERGENCE_ENV} must be one of "
            f"{sorted(FIXED_OFFSET_AFFINE_CONVERGENCE_TESTS)!r}, got {raw!r}"
        )
    return value


def _fixed_offset_affine_residual(
    gradient_scale: Any,
    gradient_offset: Any,
    scales: Any,
    *,
    minimum_scale: float,
    projected: bool,
) -> Any:
    """Raw or projected (bound-constrained KKT) stationarity residual."""

    if not projected:
        return torch.maximum(gradient_scale.abs(), gradient_offset.abs())
    at_bound = scales <= float(minimum_scale)
    scale_residual = torch.where(
        at_bound,
        torch.clamp(-gradient_scale, min=0.0),
        gradient_scale.abs(),
    )
    return torch.maximum(scale_residual, gradient_offset.abs())


def _fixed_offset_affine_projected_step(
    delta_scale: Any,
    delta_offset: Any,
    *,
    scales: Any,
    gradient_scale: Any,
    gradient_offset: Any,
    hessian_offset: Any,
    minimum_scale: float,
) -> tuple[Any, Any]:
    """Active-set Newton step: bound-active lanes take the reduced step."""

    bound_active = (scales <= float(minimum_scale)) & (gradient_scale >= 0.0)
    return (
        torch.where(bound_active, torch.zeros_like(delta_scale), delta_scale),
        torch.where(bound_active, -gradient_offset / hessian_offset, delta_offset),
    )


def _require_convergence_test(convergence_test: str) -> bool:
    if str(convergence_test) not in FIXED_OFFSET_AFFINE_CONVERGENCE_TESTS:
        raise ValueError(
            "fixed-offset affine convergence test must be one of "
            f"{sorted(FIXED_OFFSET_AFFINE_CONVERGENCE_TESTS)!r}"
        )
    return str(convergence_test) == FIXED_OFFSET_AFFINE_CONVERGENCE_PROJECTED


def _fit_fixed_offset_affine_l2(
    values: Any,
    targets: Any,
    fixed_offsets: Any,
    *,
    identity_anchor_strength: Any,
    row_validity: Any | None = None,
    minimum_scale: float = 1e-8,
    max_iterations: int = CANONICAL_CALIBRATION_MAX_ITERATIONS,
    kkt_tolerance: float = CANONICAL_CALIBRATION_KKT_TOLERANCE,
    hessian_ridge: float = CANONICAL_CALIBRATION_HESSIAN_RIDGE,
    objective_tolerance: float = CANONICAL_CALIBRATION_OBJECTIVE_TOLERANCE,
    convergence_test: str = FIXED_OFFSET_AFFINE_CONVERGENCE_RAW,
) -> Mapping[str, Any]:
    """Newton-fit positive affines with a fixed per-sample GLM offset.

    This deliberately uses the standard ridge
    ``lambda * ((scale - 1)^2 + offset^2)``.  It does not reproduce the
    sealed backend's bespoke Bernoulli-predictive-KL regularization geometry;
    only its candidate-grid, crossfit-selection, and identity-fallback shape
    are shared by the offset-aware terminal enrichment.
    """

    if torch is None:
        raise RuntimeError("fixed-offset affine fitting requires PyTorch")
    if int(max_iterations) <= 0:
        raise ValueError("fixed-offset affine max_iterations must be positive")
    if (
        not math.isfinite(float(minimum_scale))
        or float(minimum_scale) <= 0.0
        or not math.isfinite(float(kkt_tolerance))
        or float(kkt_tolerance) <= 0.0
        or not math.isfinite(float(hessian_ridge))
        or float(hessian_ridge) < 0.0
        or not math.isfinite(float(objective_tolerance))
        or float(objective_tolerance) < 0.0
    ):
        raise ValueError("fixed-offset affine solver options are invalid")
    projected = _require_convergence_test(convergence_test)

    strengths = torch.as_tensor(
        identity_anchor_strength,
        device=torch.as_tensor(values).device,
        dtype=torch.float64,
    ).reshape(-1)
    lane_count = int(strengths.numel())
    if row_validity is not None:
        validity = torch.as_tensor(row_validity, device=strengths.device)
        if validity.ndim == 2:
            lane_count = max(lane_count, int(validity.shape[0]))
    strengths = strengths.expand(lane_count)
    scales = torch.ones(lane_count, device=strengths.device, dtype=torch.float64)
    intercepts = torch.zeros_like(scales)
    iterations = torch.zeros(lane_count, device=strengths.device, dtype=torch.int64)

    for _ in range(int(max_iterations)):
        statistics = _fixed_offset_affine_l2_statistics(
            values,
            targets,
            fixed_offsets,
            scale=scales,
            offset=intercepts,
            identity_anchor_strength=strengths,
            row_validity=row_validity,
        )
        gradient_scale = statistics["gradient_scale"]
        gradient_offset = statistics["gradient_offset"]
        if projected:
            residual = _fixed_offset_affine_residual(
                gradient_scale,
                gradient_offset,
                scales,
                minimum_scale=float(minimum_scale),
                projected=True,
            )
        else:
            residual = torch.maximum(gradient_scale.abs(), gradient_offset.abs())
        active = residual > float(kkt_tolerance)
        if not bool(active.any().item()):
            break
        hessian_scale = statistics["hessian_scale"] + float(hessian_ridge)
        hessian_offset = statistics["hessian_offset"] + float(hessian_ridge)
        hessian_cross = statistics["hessian_cross"]
        determinant = hessian_scale * hessian_offset - hessian_cross.square()
        if bool((determinant <= 0.0).any().item()) or not bool(
            torch.isfinite(determinant).all().item()
        ):
            raise ValueError("fixed-offset affine Hessian is not positive definite")
        delta_scale = (
            -gradient_scale * hessian_offset
            + gradient_offset * hessian_cross
        ) / determinant
        delta_offset = (
            gradient_scale * hessian_cross
            - hessian_scale * gradient_offset
        ) / determinant
        if projected:
            delta_scale, delta_offset = _fixed_offset_affine_projected_step(
                delta_scale,
                delta_offset,
                scales=scales,
                gradient_scale=gradient_scale,
                gradient_offset=gradient_offset,
                hessian_offset=hessian_offset,
                minimum_scale=float(minimum_scale),
            )
        scales = torch.where(
            active,
            torch.clamp(scales + delta_scale, min=float(minimum_scale)),
            scales,
        )
        intercepts = torch.where(active, intercepts + delta_offset, intercepts)
        iterations = iterations + active.to(torch.int64)
        if not bool(torch.isfinite(scales).all().item()) or not bool(
            torch.isfinite(intercepts).all().item()
        ):
            raise ValueError("fixed-offset affine Newton step became nonfinite")

    final = _fixed_offset_affine_l2_statistics(
        values,
        targets,
        fixed_offsets,
        scale=scales,
        offset=intercepts,
        identity_anchor_strength=strengths,
        row_validity=row_validity,
    )
    if projected:
        final_residual = _fixed_offset_affine_residual(
            final["gradient_scale"],
            final["gradient_offset"],
            scales,
            minimum_scale=float(minimum_scale),
            projected=True,
        )
    else:
        final_residual = torch.maximum(
            final["gradient_scale"].abs(), final["gradient_offset"].abs()
        )
    result = {
        "scale": scales,
        "offset": intercepts,
        "objective": final["objective"],
        "gradient_residual": final_residual,
        "converged": final_residual <= float(kkt_tolerance),
        "iterations": iterations,
        "objective_tolerance": float(objective_tolerance),
    }
    if projected:
        result["convergence_test"] = FIXED_OFFSET_AFFINE_CONVERGENCE_PROJECTED
    return result


def _fixed_offset_affine_l2_matrix_statistics_streamed(
    values: Any,
    targets: Any,
    fixed_offsets: Any,
    *,
    scale: Any,
    offset: Any,
    identity_anchor_strength: Any,
    row_validity: Any | None = None,
    row_chunk: int = 8192,
    validate_inputs: bool = True,
) -> Mapping[str, Any]:
    """Batched fixed-offset statistics without a category x lane x row slab.

    Categories are independent GLMs but share the same row/fold axis.  A
    scalar solver called once per category would repeat the same fold
    traversal 1,000 times.  This implementation keeps
    the exact category and candidate axes explicit while streaming the row
    dimension, so its largest temporary is ``category_chunk x lanes x
    row_chunk`` rather than ``category_chunk x lanes x all_training_rows``.
    """

    if torch is None:
        raise RuntimeError("batched fixed-offset statistics require PyTorch")
    x = torch.as_tensor(values, dtype=torch.float64)
    if x.ndim == 1:
        x = x.reshape(1, -1)
    y = torch.as_tensor(targets, device=x.device, dtype=torch.float64)
    fixed = torch.as_tensor(fixed_offsets, device=x.device, dtype=torch.float64)
    if y.ndim == 1:
        y = y.reshape(1, -1)
    if fixed.ndim == 1:
        fixed = fixed.reshape(1, -1)
    if x.ndim != 2 or y.shape != x.shape or fixed.shape != x.shape:
        raise ValueError("batched fixed-offset sample axes are misaligned")
    category_count, row_count_total = (int(x.shape[0]), int(x.shape[1]))
    chunk_rows = int(row_chunk)
    if chunk_rows <= 0:
        raise ValueError("batched fixed-offset row chunk must be positive")

    scales = torch.as_tensor(scale, device=x.device, dtype=torch.float64)
    intercepts = torch.as_tensor(offset, device=x.device, dtype=torch.float64)
    strengths = torch.as_tensor(
        identity_anchor_strength, device=x.device, dtype=torch.float64
    )
    for name, tensor in (
        ("scale", scales),
        ("offset", intercepts),
        ("identity anchor", strengths),
    ):
        if tensor.ndim == 0:
            tensor = tensor.reshape(1, 1)
        elif tensor.ndim == 1:
            tensor = tensor.reshape(1, -1)
        if tensor.ndim != 2 or int(tensor.shape[0]) not in {1, category_count}:
            raise ValueError(f"batched fixed-offset {name} axis is misaligned")
        if name == "scale":
            scales = tensor
        elif name == "offset":
            intercepts = tensor
        else:
            strengths = tensor
    lane_count = max(
        int(scales.shape[1]),
        int(intercepts.shape[1]),
        int(strengths.shape[1]),
    )

    def _expand_parameter(tensor: Any, *, name: str) -> Any:
        if int(tensor.shape[1]) not in {1, lane_count}:
            raise ValueError(f"batched fixed-offset {name} lane is misaligned")
        return tensor.expand(category_count, lane_count)

    scales = _expand_parameter(scales, name="scale")
    intercepts = _expand_parameter(intercepts, name="offset")
    strengths = _expand_parameter(strengths, name="identity anchor")

    if row_validity is None:
        validity = torch.ones(
            (1, row_count_total), device=x.device, dtype=torch.float64
        )
    else:
        validity = torch.as_tensor(
            row_validity, device=x.device, dtype=torch.float64
        )
        if validity.ndim == 1:
            validity = validity.reshape(1, -1)
    if tuple(validity.shape) not in {
        (1, row_count_total),
        (lane_count, row_count_total),
    }:
        raise ValueError("batched fixed-offset row validity is misaligned")
    validity = validity.expand(lane_count, row_count_total)

    lane_rows = validity.sum(dim=1)
    positives = y @ validity.t()
    negatives = lane_rows.unsqueeze(0) - positives
    if validate_inputs:
        # The four static validity predicates cross together. The solver
        # checks them once, before its first Newton step.
        valid_inputs, valid_anchors, valid_rows, class_support = torch.stack(
            (
                torch.isfinite(x).all() & torch.isfinite(fixed).all(),
                (strengths > 0.0).all() & torch.isfinite(strengths).all(),
                ((validity == 0.0) | (validity == 1.0)).all(),
                (
                    (lane_rows > 0.0).unsqueeze(0)
                    & (positives > 0.0)
                    & (negatives > 0.0)
                ).all(),
            )
        ).to(device="cpu").tolist()
        if not valid_inputs:
            raise ValueError("batched fixed-offset inputs must be finite")
        if not valid_anchors:
            raise ValueError("batched fixed-offset anchors must be positive and finite")
        if not valid_rows:
            raise ValueError("batched fixed-offset row validity must be binary")
        if not class_support:
            raise ValueError("batched fixed-offset rows require both binary classes")
    positive_weights = negatives / positives

    zeros = torch.zeros(
        (category_count, lane_count), device=x.device, dtype=torch.float64
    )
    objective = zeros.clone()
    gradient_scale = zeros.clone()
    gradient_offset = zeros.clone()
    hessian_scale = zeros.clone()
    hessian_cross = zeros.clone()
    hessian_offset = zeros.clone()
    for start in range(0, row_count_total, chunk_rows):
        stop = min(start + chunk_rows, row_count_total)
        x_part = x[:, start:stop]
        y_part = y[:, start:stop]
        fixed_part = fixed[:, start:stop]
        valid_part = validity[:, start:stop]
        logits = (
            scales.unsqueeze(2) * x_part.unsqueeze(1)
            + intercepts.unsqueeze(2)
            + fixed_part.unsqueeze(1)
        )
        weights = torch.where(
            y_part.unsqueeze(1) > 0.5,
            positive_weights.unsqueeze(2),
            torch.ones_like(logits),
        ) * valid_part.unsqueeze(0)
        probabilities = torch.sigmoid(logits)
        residual = weights * (probabilities - y_part.unsqueeze(1))
        curvature = weights * probabilities * (1.0 - probabilities)
        objective += (
            weights
            * (
                torch.nn.functional.softplus(logits)
                - y_part.unsqueeze(1) * logits
            )
        ).sum(dim=2)
        gradient_scale += (residual * x_part.unsqueeze(1)).sum(dim=2)
        gradient_offset += residual.sum(dim=2)
        hessian_scale += (
            curvature * x_part.square().unsqueeze(1)
        ).sum(dim=2)
        hessian_cross += (curvature * x_part.unsqueeze(1)).sum(dim=2)
        hessian_offset += curvature.sum(dim=2)
    normalization = lane_rows.unsqueeze(0)
    objective = objective / normalization + strengths * (
        (scales - 1.0).square() + intercepts.square()
    )
    gradient_scale = gradient_scale / normalization + 2.0 * strengths * (
        scales - 1.0
    )
    gradient_offset = gradient_offset / normalization + 2.0 * strengths * intercepts
    hessian_scale = hessian_scale / normalization + 2.0 * strengths
    hessian_cross = hessian_cross / normalization
    hessian_offset = hessian_offset / normalization + 2.0 * strengths
    return {
        "objective": objective,
        "gradient_scale": gradient_scale,
        "gradient_offset": gradient_offset,
        "hessian_scale": hessian_scale,
        "hessian_cross": hessian_cross,
        "hessian_offset": hessian_offset,
    }


def _fit_fixed_offset_affine_l2_matrix_streamed(
    values: Any,
    targets: Any,
    fixed_offsets: Any,
    *,
    identity_anchor_strength: Any,
    row_validity: Any | None = None,
    minimum_scale: float = 1e-8,
    max_iterations: int = CANONICAL_CALIBRATION_MAX_ITERATIONS,
    kkt_tolerance: float = CANONICAL_CALIBRATION_KKT_TOLERANCE,
    hessian_ridge: float = CANONICAL_CALIBRATION_HESSIAN_RIDGE,
    objective_tolerance: float = CANONICAL_CALIBRATION_OBJECTIVE_TOLERANCE,
    row_chunk: int = 8192,
    convergence_test: str = FIXED_OFFSET_AFFINE_CONVERGENCE_RAW,
) -> Mapping[str, Any]:
    """Newton-fit a category chunk through one streamed tensor program."""

    projected = _require_convergence_test(convergence_test)
    x = torch.as_tensor(values, dtype=torch.float64)
    if x.ndim == 1:
        x = x.reshape(1, -1)
    category_count = int(x.shape[0])
    strengths = torch.as_tensor(
        identity_anchor_strength, device=x.device, dtype=torch.float64
    )
    if strengths.ndim == 0:
        strengths = strengths.reshape(1, 1)
    elif strengths.ndim == 1:
        strengths = strengths.reshape(1, -1)
    lane_count = int(strengths.shape[1])
    if row_validity is not None:
        validity = torch.as_tensor(row_validity, device=x.device)
        if validity.ndim == 2:
            lane_count = max(lane_count, int(validity.shape[0]))
    strengths = strengths.expand(category_count, lane_count)
    scales = torch.ones_like(strengths)
    intercepts = torch.zeros_like(scales)
    iterations = torch.zeros_like(scales, dtype=torch.int64)
    raw_poll_every = os.environ.get(
        "IRG_FIXED_OFFSET_STREAMED_POLL_EVERY", "1"
    ).strip()
    try:
        poll_every = int(raw_poll_every)
    except ValueError as error:
        raise ValueError("IRG_FIXED_OFFSET_STREAMED_POLL_EVERY must be positive") from error
    if poll_every < 1:
        raise ValueError("IRG_FIXED_OFFSET_STREAMED_POLL_EVERY must be positive")

    statistics_pass_count = 0
    inactive_passes = torch.zeros((), device=x.device, dtype=torch.int64)
    inactive_passes_host = 0
    pending_bad_hessian = torch.zeros((), device=x.device, dtype=torch.bool)
    pending_bad_step = torch.zeros_like(pending_bad_hessian)
    for step in range(int(max_iterations)):
        statistics = _fixed_offset_affine_l2_matrix_statistics_streamed(
            x,
            targets,
            fixed_offsets,
            scale=scales,
            offset=intercepts,
            identity_anchor_strength=strengths,
            row_validity=row_validity,
            row_chunk=row_chunk,
            validate_inputs=poll_every == 1 or step == 0,
        )
        statistics_pass_count += 1
        gradient_scale = statistics["gradient_scale"]
        gradient_offset = statistics["gradient_offset"]
        if projected:
            active = _fixed_offset_affine_residual(
                gradient_scale,
                gradient_offset,
                scales,
                minimum_scale=float(minimum_scale),
                projected=True,
            ) > float(kkt_tolerance)
        else:
            active = torch.maximum(
                gradient_scale.abs(), gradient_offset.abs()
            ) > float(kkt_tolerance)
        inactive_passes += (~active.any()).to(torch.int64)
        if poll_every == 1 and not bool(active.any().item()):
            inactive_passes_host = 1
            break
        hessian_scale = statistics["hessian_scale"] + float(hessian_ridge)
        hessian_offset = statistics["hessian_offset"] + float(hessian_ridge)
        hessian_cross = statistics["hessian_cross"]
        determinant = hessian_scale * hessian_offset - hessian_cross.square()
        if poll_every == 1:
            if bool((determinant <= 0.0).any().item()) or not bool(
                torch.isfinite(determinant).all().item()
            ):
                raise ValueError("batched fixed-offset Hessian is not positive definite")
            update = active
        else:
            # Cadence one stops before testing an all-converged Hessian.
            invalid_hessian = (
                (determinant <= 0.0) | ~torch.isfinite(determinant)
            ) & active.any()
            pending_bad_hessian |= invalid_hessian.any()
            update = active & ~invalid_hessian
            determinant = torch.where(update, determinant, torch.ones_like(determinant))
        delta_scale = (
            -gradient_scale * hessian_offset
            + gradient_offset * hessian_cross
        ) / determinant
        delta_offset = (
            gradient_scale * hessian_cross
            - hessian_scale * gradient_offset
        ) / determinant
        if projected:
            delta_scale, delta_offset = _fixed_offset_affine_projected_step(
                delta_scale,
                delta_offset,
                scales=scales,
                gradient_scale=gradient_scale,
                gradient_offset=gradient_offset,
                hessian_offset=hessian_offset,
                minimum_scale=float(minimum_scale),
            )
        next_scales = torch.where(
            update,
            torch.clamp(scales + delta_scale, min=float(minimum_scale)),
            scales,
        )
        next_intercepts = torch.where(update, intercepts + delta_offset, intercepts)
        if poll_every == 1:
            scales, intercepts = next_scales, next_intercepts
            iterations += active.to(torch.int64)
            if not bool(torch.isfinite(scales).all().item()) or not bool(
                torch.isfinite(intercepts).all().item()
            ):
                raise ValueError("batched fixed-offset Newton step became nonfinite")
        else:
            nonfinite_step = update & (
                ~torch.isfinite(next_scales) | ~torch.isfinite(next_intercepts)
            )
            pending_bad_step |= nonfinite_step.any()
            valid_update = update & ~nonfinite_step
            scales = torch.where(valid_update, next_scales, scales)
            intercepts = torch.where(valid_update, next_intercepts, intercepts)
            iterations += valid_update.to(torch.int64)
            if (step + 1) % poll_every == 0 or step + 1 == int(max_iterations):
                # One transfer carries all control flags for this poll.
                any_active, bad_hessian, bad_step, inactive_passes_host = torch.stack(
                    (
                        active.any().to(torch.int64),
                        pending_bad_hessian.to(torch.int64),
                        pending_bad_step.to(torch.int64),
                        inactive_passes,
                    )
                ).to(device="cpu").tolist()
                if bad_hessian:
                    raise ValueError("batched fixed-offset Hessian is not positive definite")
                if bad_step:
                    raise ValueError("batched fixed-offset Newton step became nonfinite")
                if not any_active:
                    break

    final = _fixed_offset_affine_l2_matrix_statistics_streamed(
        x,
        targets,
        fixed_offsets,
        scale=scales,
        offset=intercepts,
        identity_anchor_strength=strengths,
        row_validity=row_validity,
        row_chunk=row_chunk,
        validate_inputs=poll_every == 1 or int(max_iterations) == 0,
    )
    if projected:
        residual = _fixed_offset_affine_residual(
            final["gradient_scale"],
            final["gradient_offset"],
            scales,
            minimum_scale=float(minimum_scale),
            projected=True,
        )
    else:
        residual = torch.maximum(
            final["gradient_scale"].abs(), final["gradient_offset"].abs()
        )
    result = {
        "scale": scales,
        "offset": intercepts,
        "objective": final["objective"],
        "gradient_residual": residual,
        "converged": residual <= float(kkt_tolerance),
        "iterations": iterations,
        "objective_tolerance": float(objective_tolerance),
        # Execution accounting is separate from the numerical fit receipt.
        # The final diagnostics pass also streams the complete input axis.
        "execution_profile": {
            "active_poll_every": int(poll_every),
            "statistics_pass_count": int(statistics_pass_count + 1),
            "extra_statistics_pass_count": max(0, int(inactive_passes_host) - 1),
            "statistics_rows_per_pass": int(x.shape[1]),
            "statistics_row_chunk_pass_count": int(statistics_pass_count + 1)
            * math.ceil(int(x.shape[1]) / int(row_chunk)),
        },
    }
    if projected:
        result["convergence_test"] = FIXED_OFFSET_AFFINE_CONVERGENCE_PROJECTED
    return result


def _fixed_offset_fit_work_profile(
    selection_fit: Mapping[str, Any],
    deployment_fit: Mapping[str, Any],
    columns: Sequence[int],
) -> Mapping[str, Any]:
    """Streamed work of selection, deployment and two held-out score passes."""

    profiles = [selection_fit["execution_profile"], deployment_fit["execution_profile"]]
    return {
        "columns": tuple(int(value) for value in columns),
        "selection": dict(profiles[0]),
        "deployment": dict(profiles[1]),
        "heldout_score_statistics_pass_count": 2,
        "statistics_pass_count": 2 + sum(int(p["statistics_pass_count"]) for p in profiles),
        "extra_statistics_pass_count": sum(int(p["extra_statistics_pass_count"]) for p in profiles),
    }


def _analytic_calibration_forecast(
    *,
    current_count: int,
    first_order_bound: float,
    second_order_bound: float,
    requested_target_bce: float,
    occupancy_quantum: int,
    forecast_validated: bool,
    maximum_unvalidated_growth: float = 4.0,
) -> CalibrationForecastReceipt:
    """Solve ``a/sqrt(n) + b/n <= epsilon`` for the next prefix.

    The current first- and second-order terms identify ``a`` and ``b`` under
    regular affine-BCE asymptotics.  Before one prediction has been checked
    against a later look, growth is guarded to avoid the former unstable
    empirical-exponent extrapolation.  The guard never caps total sampling.
    """

    count = int(current_count)
    target = float(requested_target_bce)
    quantum = int(occupancy_quantum)
    if (
        count <= 0
        or target <= 0.0
        or not math.isfinite(target)
        or quantum <= 0
    ):
        raise ValueError("calibration forecast inputs are invalid")
    first = max(0.0, float(first_order_bound))
    second = max(0.0, float(second_order_bound))
    if not math.isfinite(first) or not math.isfinite(second):
        raise ValueError("calibration forecast bounds must be finite")
    coefficient_a = first * math.sqrt(float(count))
    coefficient_b = second * float(count)
    discriminant = coefficient_a * coefficient_a + 4.0 * target * coefficient_b
    root = (
        coefficient_a + math.sqrt(max(0.0, discriminant))
    ) / (2.0 * target)
    raw_required = max(count + 1, int(math.ceil(root * root)))
    # One growth guard, not three. This was an inline transcription of
    # ``guard_unvalidated_cumulative_forecast`` with ``minimum_increment=1``;
    # both branches are identical to it, so the substitution is behaviour
    # preserving and ``guarded_required_count`` -- and every receipt byte
    # downstream of it -- is unchanged.
    guarded, _guard_applied = guard_unvalidated_cumulative_forecast(
        current_count=count,
        analytic_target=raw_required,
        minimum_increment=1,
        forecast_validated=bool(forecast_validated),
        maximum_growth_factor=maximum_unvalidated_growth,
    )
    rounded = int(math.ceil(float(guarded) / float(quantum)) * quantum)
    predicted = (
        coefficient_a / math.sqrt(float(rounded))
        + coefficient_b / float(rounded)
    )
    return CalibrationForecastReceipt(
        current_count=count,
        requested_target_bce=target,
        first_order_coefficient=coefficient_a,
        second_order_coefficient=coefficient_b,
        raw_required_count=raw_required,
        guarded_required_count=guarded,
        occupancy_quantum=quantum,
        rounded_required_count=rounded,
        forecast_validated=bool(forecast_validated),
        predicted_bound_at_rounded_count=predicted,
    )


def _execution_receipt_retention() -> int:
    """Bound the retained telemetry tail; aggregate counters cover all rows."""

    raw = os.environ.get("IRG_EXECUTION_RECEIPT_RETENTION", "").strip()
    if not raw:
        return 1024
    value = int(raw)
    if value < 0:
        raise ValueError(
            "IRG_EXECUTION_RECEIPT_RETENTION must be >= 0"
        )
    return value


HOST_PRIMARY_READOUT_SLAB_ENVIRONMENT = "IRG_HOST_PRIMARY_READOUT_SLAB"


def host_primary_readout_slab_enabled() -> bool:
    """IRG_HOST_PRIMARY_READOUT_SLAB armed unless explicitly disarmed."""

    return (
        str(os.environ.get(HOST_PRIMARY_READOUT_SLAB_ENVIRONMENT, ""))
        .strip()
        .lower()
        not in _LOCAL_FALSY_TOKENS
    )


# Delivered-row label integrity at the slab boundary.
#
# ``_flush_open_decision`` compares the parent and candidate slabs' labels
# for one decision's sources.  Those two rows for one source were, in
# general, appended by DIFFERENT physical passes (the parent's rows when it
# was the candidate or during its calibration fill; the candidate's rows in
# the current decision), so a disagreement means at least one pass delivered
# a row whose (context_id -> image, label) pairing was wrong -- and the check
# fires one or many decisions after the corrupt pass, in a different pass,
# without saying which lane is wrong.  Under the class-indexed bank and the
# ordinal-sorted physical order, neighbouring rows share a label, so a
# same-class row shift is invisible to that late check altogether.
#
# The certified bank label for a context is a pure function of the context
# (``plane.authoritative_labels``).  Checking every delivered row of every
# execution against it, BEFORE anything is appended, localizes a corrupt
# delivery to the pass that produced it. Checks enqueue device flags;
# settlement ends a run whose delivered rows differ from the bank rows.
READOUT_LABEL_INTEGRITY_ENVIRONMENT = "IRG_READOUT_LABEL_INTEGRITY"
_READOUT_LABEL_INTEGRITY_SAMPLE_CAP = 16


def readout_label_integrity_enabled() -> bool:
    """IRG_READOUT_LABEL_INTEGRITY armed unless explicitly disarmed."""

    return (
        str(os.environ.get(READOUT_LABEL_INTEGRITY_ENVIRONMENT, ""))
        .strip()
        .lower()
        not in _LOCAL_FALSY_TOKENS
    )


class ReadoutDeliveryIntegrityError(RuntimeError):
    """A physical readout pass delivered rows that are not the bank's rows.

    A settled delivery flag ends the run. It reports either a label
    differing from the bank label or an image row differing from its bank
    row.  ``details`` carries the pass identity and the
    first mismatching positions so the failure is localized to its
    producing pass.
    """

    def __init__(self, message: str, details: Mapping[str, Any]) -> None:
        super().__init__(message)
        self.details = dict(details)


# CLASS3 I3: readout-slab value integrity.  Every row appended to a
# ``_ProjectedReadoutSlab`` is digested bit-exactly BEFORE it enters the
# slab, and every gather that leaves the slab (decision statistics, the
# flush, the tracker, the dense reference) re-digests the gathered rows and
# compares -- one small reduction per gather.  Under the host-primary
# residency this certifies the whole acquire/commit round trip of the
# ``HostPrimarySlabWindow`` (H2D, D2H write-back, host backing, re-acquire),
# the largest value surface that nothing else guards.
#
# The digest is the plane's dual-lane v2 word digest
# (every single-word and single-bit change detected, exact int64, no
# overflow), taken over the row's bytes AS STORED (the slab's dtype, m5) with
# the row's int64 label folded in as two extra words (m6), so a gather
# certifies the (value row, label) pair together.
SLAB_VALUE_DIGEST_ALGORITHM = "slab_row_le_i32_words_plus_label_dual_lane_odd_weight_exact_int64_v2"
CANONICAL_DENSE_ROW_DIGEST_ALGORITHM = SLAB_VALUE_DIGEST_ALGORITHM


class SlabValueIntegrityError(RuntimeError):
    """A readout slab returned rows whose bytes differ from what was appended."""

    fault_class = "slab_value"

    def __init__(self, message: str, details: Mapping[str, Any]) -> None:
        super().__init__(message)
        self.details = dict(details)


def _label_digest_words(labels: Any, rows: int, *, like: Any) -> Any:
    """Two non-negative 32-bit words per int64 label (lo, hi), [rows, 2]."""

    if labels is None:
        return None
    if torch.is_tensor(like):
        label64 = torch.as_tensor(labels, device=like.device).reshape(-1).to(torch.int64)
        if int(label64.numel()) != int(rows):
            raise ValueError("slab value digest labels differ from the row axis")
        return torch.stack(
            (label64 & 0xFFFFFFFF, (label64 >> 32) & 0xFFFFFFFF), dim=1
        )
    label64 = np.asarray(labels, dtype=np.int64).reshape(-1)
    if int(label64.shape[0]) != int(rows):
        raise ValueError("slab value digest labels differ from the row axis")
    return np.stack((label64 & 0xFFFFFFFF, (label64 >> 32) & 0xFFFFFFFF), axis=1)


def _slab_value_row_digest(values: Any, labels: Any | None = None) -> Any:
    """Bit-exact per-row digest of ``[rows, width]`` values (+ labels).

    The row's bytes (any 1/2/4/8-byte dtype, in the tensor's own dtype --
    callers pass rows in the slab's STORED dtype) are digested with the
    plane's dual-lane v2 word digest; ``labels`` (one int64 per row), when
    given, are folded in as two extra words.  NaN payload bits and signed
    zeros are distinguished, which is what a value-integrity probe wants.
    Runs on the tensor's device; no host synchronization.
    """

    from mechanistic_systems.measurement.native_panel_data_plane import (
        byte_row_digests_device,
    )

    tensor = values.detach()
    if tensor.ndim == 1:
        tensor = tensor[:, None]
    rows = int(tensor.shape[0])
    if int(tensor.element_size()) not in {1, 2, 4, 8}:
        raise TypeError("slab value digest requires a 1/2/4/8-byte element type")
    flat = tensor.contiguous().reshape(rows, -1)
    byte_rows = flat.view(torch.uint8).reshape(rows, -1)
    extra = _label_digest_words(labels, rows, like=byte_rows)
    return byte_row_digests_device(byte_rows, extra)


def _slab_value_row_digest_host(values: np.ndarray, labels: Any | None = None) -> np.ndarray:
    """Host (numpy) twin of :func:`_slab_value_row_digest` (canonical rows)."""

    from mechanistic_systems.measurement.native_panel_data_plane import (
        byte_row_digests_host,
    )

    array = np.asarray(values)
    if array.ndim == 1:
        array = array[:, None]
    rows = int(array.shape[0])
    byte_rows = np.ascontiguousarray(array).reshape(rows, -1).view(np.uint8)
    extra = _label_digest_words(labels, rows, like=byte_rows)
    return byte_row_digests_host(byte_rows, extra)


def _look_host_tensor(owner, values, *, device, dtype, key):
    """Place resident values or host row locators without a host wait.

    Windows in one look have separate buffers, so asynchronous copies never
    race with a subsequent host write. The next look starts after control.
    """
    from mechanistic_systems.inference import device_bce as db
    if torch.is_tensor(values) and (
        values.device.type != "cpu" or values.device == torch.device(device)
    ):
        # An unindexed target such as ``cuda`` and its resident ``cuda:0``
        # tensor are different torch.device objects. Keep device values on
        # the device route; upload_metadata accepts host metadata only.
        return values.to(device=device, dtype=dtype, non_blocking=True)
    if not db.DEVICE_LOOK_ACTIVE.get():
        return upload_metadata(values, device, dtype=dtype)
    if owner is None:
        buffers = db.HostTransferBuffer(device)
        return buffers.copy(key, values, dtype=dtype)
    buffers = getattr(owner, "_device_bce_index_transfers", None)
    if buffers is None:
        buffers = owner._device_bce_index_transfers = db.HostTransferBuffer(device)
    indices = db.DEVICE_LOOK_COPY_INDICES.get()
    slot = (id(owner), key)
    index = indices.get(slot, 0)
    indices[slot] = index+1
    return buffers.copy((key,index), values, dtype=dtype)


def _label_mismatch_report(
    observed: Any,
    expected: Any,
    source_ids: Sequence[str],
    *,
    batch_rows: int,
    lane_index: int,
) -> dict[str, Any] | None:
    """Positions where a delivered label row differs from the bank's label.

    Both tensors are compared on the host in int64.  Returns None when every
    row agrees; otherwise a JSON-ready mapping with the mismatch count and a
    capped sample of (position, physical chunk index, source id, expected,
    observed) rows.
    """

    observed_np = (
        observed.detach().to(device="cpu", dtype=torch.int64).numpy().reshape(-1)
        if torch.is_tensor(observed)
        else np.asarray(observed, dtype=np.int64).reshape(-1)
    )
    expected_np = np.asarray(expected, dtype=np.int64).reshape(-1)
    if observed_np.shape != expected_np.shape:
        return {
            "lane_index": int(lane_index),
            "mismatch_count": int(max(observed_np.size, expected_np.size)),
            "observed_rows": int(observed_np.size),
            "expected_rows": int(expected_np.size),
            "samples": (),
        }
    positions = np.flatnonzero(observed_np != expected_np)
    if positions.size == 0:
        return None
    rows = max(1, int(batch_rows))
    samples = tuple(
        {
            "position": int(position),
            "physical_chunk": int(position) // rows,
            "source_context_id": str(source_ids[int(position)]),
            "expected_label": int(expected_np[int(position)]),
            "observed_label": int(observed_np[int(position)]),
        }
        for position in positions[:_READOUT_LABEL_INTEGRITY_SAMPLE_CAP]
    )
    return {
        "lane_index": int(lane_index),
        "mismatch_count": int(positions.size),
        "mismatch_chunks": tuple(
            sorted({int(position) // rows for position in positions.tolist()})
        ),
        "samples": samples,
    }


def _plane_runtime_snapshot(data_plane: Any) -> Mapping[str, Any]:
    """Selected data-plane runtime counters at a delivery mismatch.

    Fail-soft and read-only.  Keeps only the counters that discriminate the
    CLASS3 hypothesis ladder (pinned-ring pressure, lookahead ready/miss and
    cancellation counts, checksum audits, degradations); the full receipt is
    still available from the plane's own runtime block.
    """

    if data_plane is None:
        return {}
    try:
        receipt = dict(data_plane.runtime_receipt())
    except Exception as error:  # diagnostic must never fail the pass
        return {"unavailable": f"{type(error).__name__}:{error}"}
    selected: dict[str, Any] = {}
    exact = (
        "pinned_host_rings",
        "delivery_checksums_verified",
        "delivery_checksum_mismatches",
        "delivery_checksum_contract",
        "delivery_integrity",
        "workspace_rings",
        "device_cache",
        "device_gather",
        "peak_hbm_allocated_bytes",
        "peak_hbm_reserved_bytes",
        "process_peak_rss_bytes",
    )
    prefixes = ("on_target", "normalize", "pinned_ring", "uint8_folded")
    for key, value in receipt.items():
        name = str(key)
        if name in exact or name.startswith(prefixes):
            selected[name] = value
    producer = receipt.get("persistent_panel_producer")
    if isinstance(producer, Mapping):
        selected["persistent_panel_producer"] = {
            key: producer[key]
            for key in (
                "closed",
                "pool_reuse_count",
                "degradation_reasons",
                "posted_looks",
                "enqueued",
                "ready_hits",
                "on_demand_misses",
                "stale_flushed_chunks",
                "budget_exhausted_posts",
                "exposed_wait_seconds_estimate",
                "lookahead",
            )
            if key in producer
        }
    return selected


def _v6_str_tuple(values: Sequence[Any]) -> tuple[str, ...]:
    """``tuple(str(v) for v in values)`` without the per-row call when exact.

    For an exact tuple of exact ``str`` the same object is returned (``str(s)
    is s``); anything else takes the per-row conversion.
    """

    if type(values) is tuple and set(map(type, values)) <= {str}:
        return values
    return tuple(str(value) for value in values)


class _ProjectedReadoutSlab:
    """Append-only projected logits for one mask/projection identity.

    CUDA logits and labels remain on the device, including during capacity
    growth. CPU storage may use :class:`HostPrimarySlabWindow` through
    ``IRG_HOST_PRIMARY_READOUT_SLAB`` or an explicit ``host_primary`` choice;
    its acquire/commit windows preserve the same append and gather values.
    """

    def __init__(
        self,
        *,
        device: Any,
        host_primary: bool | None = None,
        copy_windows: bool | None = None,
        value_integrity: bool | None = None,
    ) -> None:
        if torch is None:
            raise RuntimeError("projected readout slabs require PyTorch")
        self.device = torch.device(device)
        # Decision readouts stay resident on CUDA.  Moving the full slab
        # through host windows would add a host wait whenever its capacity
        # grows, before the look's control event has been enqueued.
        self._host_primary = self.device.type != "cuda" and (
            host_primary_readout_slab_enabled() if host_primary is None
            else bool(host_primary)
        )
        # None defers to the primitive's device-derived default (staged
        # copies on CUDA, direct host views on CPU); tests pass True on
        # CPU to certify the staged-copy discipline's value semantics.
        self._copy_windows = copy_windows
        self._window: Any | None = None
        self._source_to_index: dict[str, int] = {}
        self._values: Any | None = None
        self._labels: Any | None = None
        self._size = 0
        self._capacity = 0
        self._width = 0
        # CLASS3 I3: per-row value digests (8 bytes/row, device-resident
        # like the labels).  Armed with the one integrity variable; with
        # the kill switch set nothing below is allocated or executed.
        self._value_integrity = self.device.type != "cuda" and (
            readout_label_integrity_enabled()
            if value_integrity is None
            else bool(value_integrity)
        )
        self._row_digests: Any | None = None
        self.value_integrity_appends = 0
        self.value_integrity_gathers = 0
        self.value_integrity_rows_verified = 0
        self.value_integrity_mismatches = 0

    def __contains__(self, source_context_id: object) -> bool:
        return str(source_context_id) in self._source_to_index

    def __len__(self) -> int:
        return int(self._size)

    @property
    def resident_bytes(self) -> int:
        if self._values is None or self._labels is None:
            return 0
        return int(
            self._values.numel() * self._values.element_size()
            + self._labels.numel() * self._labels.element_size()
        )

    def _reserve(self, required: int, *, width: int, dtype: Any) -> None:
        required_count = int(required)
        resolved_width = int(width)
        if required_count <= self._capacity:
            if resolved_width != self._width:
                raise ValueError("projected readout width changed within one slab")
            return
        capacity = max(64, self._capacity)
        while capacity < required_count:
            capacity *= 2
        # CLASS3: a growth whose incoming dtype differs from the
        # stored one re-casts the existing rows below.  Certify those rows
        # against their digests BEFORE the cast; they are re-digested in the
        # new dtype right after it.
        recast_rows = bool(
            self._value_integrity
            and self._size
            and self._values is not None
            and dtype != self._values.dtype
        )
        if recast_rows:
            self._verify_rows_in_storage(self._size)
        labels = torch.empty(
            (capacity,),
            device=self.device,
            dtype=torch.int64,
        )
        if self._value_integrity:
            # CLASS3 I3: grows with the labels, device-resident, 8 B/row.
            row_digests = torch.empty(
                (capacity,),
                device=self.device,
                dtype=torch.int64,
            )
            if self._size:
                row_digests[: self._size].copy_(self._row_digests[: self._size])
            self._row_digests = row_digests
        if self._host_primary:
            # Grow through bounded windows ordered after the prior writes.
            # Both backing slabs stay on the host; CUDA transfers and the
            # value copy remain stream-ordered without a host wait.
            from mechanistic_systems.measurement.device_route_moments import (
                HostPrimarySlabWindow,
            )

            window = HostPrimarySlabWindow(
                shape=(capacity, resolved_width),
                dtype=dtype,
                route_axis=0,
                device=self.device,
                copy_windows=self._copy_windows,
                name="projected_readout_slab",
            )
            if self._size:
                # Four slots (old/new, two each) share a 64 MiB growth
                # budget. Reallocation never materializes a whole slab
                # on the device.
                bytes_per_row = resolved_width * max(
                    self._values.element_size(), window.host.element_size()
                )
                row_chunk = max(1, (64 << 20) // (4 * bytes_per_row))
                for start in range(0, self._size, row_chunk):
                    stop = min(start + row_chunk, self._size)
                    old_rows = self._window.acquire(start, stop)
                    new_rows = window.acquire(start, stop)
                    new_rows.copy_(old_rows)
                    self._window.commit(start, stop, writeback=False)
                    window.commit(start, stop)
                labels[: self._size].copy_(self._labels[: self._size])
            self._window = window
            self._values = window.host
            self._labels = labels
            self._capacity = capacity
            self._width = resolved_width
            if recast_rows:
                self._redigest_rows_in_storage(self._size)
            return
        values = torch.empty(
            (capacity, resolved_width),
            device=self.device,
            dtype=dtype,
        )
        if self._size:
            values[: self._size].copy_(self._values[: self._size])
            labels[: self._size].copy_(self._labels[: self._size])
        self._values = values
        self._labels = labels
        self._capacity = capacity
        self._width = resolved_width
        if recast_rows:
            self._redigest_rows_in_storage(self._size)

    def _stored_rows_digest(self, stop: int) -> Any:
        """Digest stored rows on their device, including host-backed windows."""

        if not self._host_primary:
            return _slab_value_row_digest(self._values[:stop], self._labels[:stop])
        result = torch.empty(stop, dtype=torch.int64, device=self.device)
        row_chunk = self._window_row_budget()
        for start in range(0, stop, row_chunk):
            end = min(start + row_chunk, stop)
            values = self._window.acquire(start, end)
            result[start:end].copy_(
                _slab_value_row_digest(values, self._labels[start:end])
            )
            self._window.commit(start, end, writeback=False)
        return result

    def _verify_rows_in_storage(self, stop: int) -> None:
        observed = self._stored_rows_digest(stop)
        expected = self._row_digests[:stop]
        def deferred_error():
            self.value_integrity_mismatches += 1
            offending = torch.nonzero(observed != expected).reshape(-1).to(device="cpu").tolist()
            return SlabValueIntegrityError(
                "projected readout rows changed before dtype conversion",
                {"fault_class":SlabValueIntegrityError.fault_class,
                 "algorithm":SLAB_VALUE_DIGEST_ALGORITHM,"stage":"before_dtype_recast",
                 "mismatch_count":len(offending),"slab_rows":tuple(offending[:16])},
            )

        DEVICE_FAULTS.note(observed.ne(expected).any(), deferred_error)

    def _redigest_rows_in_storage(self, stop: int) -> None:
        self._row_digests[:stop].copy_(self._stored_rows_digest(stop))

    def append(
        self,
        source_context_ids: Sequence[str],
        values: Any,
        labels: Any,
    ) -> None:
        source_ids = _v6_str_tuple(source_context_ids)
        if len(set(source_ids)) != len(source_ids):
            raise ValueError("projected slab append source identities must be unique")
        if not self._source_to_index.keys().isdisjoint(source_ids):
            raise ValueError("projected slab append attempted to replace a source")
        tensor = _look_host_tensor(
            self, values, device=self.device, dtype=torch.as_tensor(values).dtype,
            key="append_values",
        )
        if tensor.ndim == 1:
            tensor = tensor[:, None]
        label_tensor = _look_host_tensor(
            self, labels, device=self.device, dtype=torch.int64,
            key="append_labels",
        ).reshape(-1)
        if (
            int(tensor.shape[0]) != len(source_ids)
            or int(label_tensor.numel()) != len(source_ids)
        ):
            raise ValueError("projected slab append axes are misaligned")
        start = int(self._size)
        stop = start + len(source_ids)
        self._reserve(stop, width=int(tensor.shape[1]), dtype=tensor.dtype)
        # CLASS3 I3: digest the incoming rows BEFORE they enter the slab
        # (device-side, no synchronization); this is the authority every
        # later gather of these rows is verified against.
        # The rows are digested in the slab's STORED dtype (the value
        # ``copy_`` below writes) with their labels folded in.
        row_digests = (
            _slab_value_row_digest(
                tensor.to(dtype=self._values.dtype), label_tensor
            )
            if self._value_integrity
            else None
        )
        if self._host_primary:
            # The primitive's tested row-append pattern: acquire the
            # [start:stop) device window, copy the new rows into it, and
            # commit the write-back.  Value-exact — the copy is the same
            # single ``copy_`` the dense path issues, into a window whose
            # bytes land on the host slice.
            window = self._window.acquire(start, stop)
            window.copy_(tensor)
            self._window.commit(start, stop)
        else:
            self._values[start:stop].copy_(tensor)
        self._labels[start:stop].copy_(label_tensor)
        if row_digests is not None:
            self._row_digests[start:stop].copy_(row_digests)
            self.value_integrity_appends += 1
        self._source_to_index.update(zip(source_ids, range(start, stop)))
        self._size = stop

    def append_missing(
        self,
        source_context_ids: Sequence[str],
        values: Any,
        labels: Any,
    ) -> int:
        """Append only sources absent from this mask/projection slab.

        A fused multi-mask request evaluates the union of sources missing from
        *any* lane.  Another lane may already contain part of that union from
        parent calibration or a prior oracle look.  Those cached values remain
        authoritative; only the lane-local missing suffix is appended.
        """

        source_ids = _v6_str_tuple(source_context_ids)
        tensor = _look_host_tensor(
            self, values, device=self.device, dtype=torch.as_tensor(values).dtype,
            key="append_missing_values",
        )
        if tensor.ndim == 1:
            tensor = tensor[:, None]
        label_tensor = _look_host_tensor(
            self, labels, device=self.device, dtype=torch.int64,
            key="append_missing_labels",
        ).reshape(-1)
        if (
            int(tensor.shape[0]) != len(source_ids)
            or int(label_tensor.numel()) != len(source_ids)
        ):
            raise ValueError("projected slab append axes are misaligned")
        # Physical execution may deliberately retain repeated IID source rows
        # to keep the compiled batch shape occupancy-complete.  The slab owns
        # one deterministic readout per physical source, so append only the
        # first missing occurrence without launching one CUDA operation per
        # context.
        seen_missing: set[str] = set()
        present = self._source_to_index
        missing_positions = tuple(
            index
            for index, source_id in enumerate(source_ids)
            if source_id not in present
            and source_id not in seen_missing
            and not seen_missing.add(source_id)
        )
        if not missing_positions:
            return 0
        if len(missing_positions) == len(source_ids):
            self.append(source_ids, tensor, label_tensor)
            return len(missing_positions)
        positions = upload_metadata(missing_positions, self.device, dtype=torch.int64)
        self.append(
            tuple(source_ids[index] for index in missing_positions),
            tensor.index_select(0, positions),
            label_tensor.index_select(0, positions),
        )
        return len(missing_positions)

    def gather(self, source_context_ids: Sequence[str]) -> tuple[Any, Any]:
        source_ids = _v6_str_tuple(source_context_ids)
        try:
            positions = tuple(map(self._source_to_index.__getitem__, source_ids))
        except KeyError as error:
            raise KeyError(
                f"projected readout source is absent from slab: {error.args[0]}"
            ) from error
        indices = _look_host_tensor(
            self, positions, key="gather_indices",
            device=self.device,
            dtype=torch.int64,
        )
        if self._host_primary and self._window is not None:
            values = (
                self._windowed_gather_rows(positions)
                if positions
                else torch.empty(
                    (0, self._width),
                    device=self.device,
                    dtype=self._values.dtype,
                )
            )
        else:
            values = torch.index_select(self._values[: self._size], 0, indices)
        labels = torch.index_select(self._labels[: self._size], 0, indices)
        if self._value_integrity and positions:
            self._verify_gathered_values(values, indices, source_ids, labels=labels)
        return values, labels

    def _verify_gathered_values(
        self,
        values: Any,
        indices: Any,
        source_ids: tuple[str, ...],
        *,
        labels: Any | None = None,
    ) -> None:
        """CLASS3 I3: the gathered rows must digest to what was appended.

        One digest kernel over the gathered rows plus one comparison
        reduction.  The device decision path incorporates its failure flag
        into the look's single control read. Other consumers settle it
        after dispatch. Detailed positions and source ids are read on failure.
        """

        observed = _slab_value_row_digest(values, labels)
        expected = torch.index_select(self._row_digests[: self._size], 0, indices)
        mismatch = observed != expected
        self.value_integrity_gathers += 1
        self.value_integrity_rows_verified += int(len(source_ids))
        DEVICE_FAULTS.note(
            mismatch.any(),
            lambda: self._gathered_value_failure(mismatch, observed, expected, indices, source_ids),
        )

    def _gathered_value_failure(
        self, mismatch: Any, observed: Any, expected: Any, indices: Any, source_ids: tuple[str, ...]
    ) -> SlabValueIntegrityError:
        """The detailed refusal of a failed slab value check (failure path only)."""

        self.value_integrity_mismatches += 1
        offending = torch.nonzero(mismatch).reshape(-1).to(device="cpu").tolist()
        sample = offending[:16]
        expected_host = expected.to(device="cpu").tolist()
        observed_host = observed.to(device="cpu").tolist()
        positions_host = indices.to(device="cpu").tolist()
        return SlabValueIntegrityError(
            "projected readout slab returned rows whose bytes differ from the "
            f"appended rows ({len(offending)} of {len(source_ids)} gathered; "
            f"first sources={tuple(source_ids[int(index)] for index in sample[:4])!r}, "
            f"slab rows={tuple(positions_host[int(index)] for index in sample[:4])!r}); "
            "slab value integrity cannot be certified",
            {
                "fault_class": SlabValueIntegrityError.fault_class,
                "algorithm": SLAB_VALUE_DIGEST_ALGORITHM,
                "residency": "host_primary" if self._host_primary else "device_resident",
                "gathered_rows": int(len(source_ids)),
                "mismatch_count": int(len(offending)),
                "samples": tuple(
                    {
                        "gather_position": int(index),
                        "slab_row": int(positions_host[int(index)]),
                        "source_context_id": str(source_ids[int(index)]),
                        "expected_digest": int(expected_host[int(index)]),
                        "observed_digest": int(observed_host[int(index)]),
                    }
                    for index in sample
                ),
            },
        )

    def value_integrity_receipts(self) -> dict[str, Any]:
        """CLASS3 I3 receipt block for this slab (counts only)."""

        return {
            "armed": bool(self._value_integrity),
            "algorithm": SLAB_VALUE_DIGEST_ALGORITHM,
            "appends": int(self.value_integrity_appends),
            "gathers": int(self.value_integrity_gathers),
            "rows_verified": int(self.value_integrity_rows_verified),
            "mismatches": int(self.value_integrity_mismatches),
        }

    def _window_row_budget(self) -> int:
        """Largest acquirable row window under the core's device byte budget.

        Reuses the accumulator core's budget contract
        (IRG_HOST_PRIMARY_WINDOW_BUDGET_BYTES, default 2 GiB) with the
        primitive's two concurrently resident slots, at this slab's
        bytes-per-row.
        """

        from mechanistic_systems.measurement.device_route_moments import (
            _HOST_PRIMARY_DEFAULT_WINDOW_BUDGET_BYTES,
            HOST_PRIMARY_WINDOW_BUDGET_ENVIRONMENT,
        )

        raw = str(
            os.environ.get(HOST_PRIMARY_WINDOW_BUDGET_ENVIRONMENT, "")
        ).strip()
        budget = int(raw) if raw else _HOST_PRIMARY_DEFAULT_WINDOW_BUDGET_BYTES
        if budget <= 0:
            raise ValueError("host-primary window byte budget is invalid")
        budget = process_device_memory_budget_bytes(budget)
        bytes_per_row = max(1, int(self._width)) * int(
            self._values.element_size()
        )
        return max(1, budget // (2 * bytes_per_row))

    def _windowed_gather_rows(self, positions: Sequence[int]) -> Any:
        """Gather requested rows through bounded device windows.

            Stable row sorting and vectorized window bounds keep repeated rows
            together. Each window writes directly into the requested result
            positions and releases without host write-back.
            """
        max_rows = self._window_row_budget()
        return self._windowed_gather_rows_v6(positions, int(max_rows))

    def _windowed_gather_rows_v6(self, positions: Sequence[int], max_rows: int) -> Any:
        """The same windows, index sets and copies, planned in numpy.

        ``np.argsort(kind="stable")`` is the stable sort by position that
        ``sorted`` builds; each window's extent is found by ``searchsorted``
        instead of a per-row loop.  The acquired windows, the local row
        indices and the destination indices are the same integers, so the
        gathered tensor is the same bit for bit.
        """

        position_array = np.asarray(positions, dtype=np.int64).reshape(-1)
        order = np.argsort(position_array, kind="stable")
        ordered = position_array[order]
        gathered: Any | None = None
        cursor = 0
        count = int(ordered.size)
        while cursor < count:
            window_start = int(ordered[cursor])
            bound = int(
                np.searchsorted(ordered, window_start + max_rows, side="left")
            )
            local_rows = ordered[cursor:bound] - window_start
            window_stop = window_start + int(local_rows[-1]) + 1
            window = self._window.acquire(window_start, window_stop)
            rows = torch.index_select(
                window,
                0,
                _look_host_tensor(self, local_rows, device=self.device, dtype=torch.int64, key="window_local_rows"),
            )
            self._window.commit(window_start, window_stop, writeback=False)
            if gathered is None:
                gathered = torch.empty(
                    (count, int(rows.shape[1])),
                    device=rows.device,
                    dtype=rows.dtype,
                )
            gathered.index_copy_(
                0,
                _look_host_tensor(self, order[cursor:bound], device=rows.device, dtype=torch.int64, key="window_destination_rows"),
                rows,
            )
            del rows
            cursor = bound
        return gathered

    def host_primary_receipts(self) -> dict[str, Any]:
        """Receipt block for this slab's residency mode and window traffic."""

        receipts: dict[str, Any] = {
            "environment": HOST_PRIMARY_READOUT_SLAB_ENVIRONMENT,
            "mode": (
                "host_primary" if self._host_primary else "device_resident"
            ),
        }
        if self._window is not None:
            receipts["compute_device"] = str(self.device)
            receipts["window_row_budget"] = int(self._window_row_budget())
            # Nested: the primitive's own ``mode`` (staged/host_view)
            # must not shadow the residency mode above.
            receipts["window"] = self._window.receipts()
        return receipts


def _sealed_order(
    context_ids: Sequence[str],
    *,
    namespace: str,
) -> tuple[str, ...]:
    """Deterministic content-seeded order for a frozen finite population."""

    population = tuple(sorted(str(value) for value in context_ids))
    if not population or len(set(population)) != len(population):
        raise ValueError("sealed context population must be nonempty and unique")
    # The per-row key is the same SHA-256 hex digest of
    # the same canonical JSON bytes as ``_raw_sha256({"algorithm": ...,
    # "namespace": ..., "context_id": ...})``, assembled without the generic
    # canonicalizer (checked against ``content_hash`` on every call), so the
    # permutation is identical.
    from mechanistic_systems.measurement.sealed_sort_keys import (
        sealed_order_sort_keys,
        sorted_by_keys,
    )

    return sorted_by_keys(
        population,
        sealed_order_sort_keys(population, namespace=str(namespace)),
    )


def _backend_profile_without_wait(backend: Any) -> Any:
    """The backend's runtime profile, reading only CUDA events already complete."""

    return backend.runtime_profile(wait_for_device=False)


def _backend_cuda_event_count(backend: Any) -> int | None:
    profiler = getattr(backend, "profiler", None)
    counter = getattr(profiler, "cuda_event_count", None)
    return None if not callable(counter) else int(counter())


def _torch_compile_counter_snapshot() -> dict[str, int]:
    """Return selected process-local compile counters without synchronization."""

    try:
        counters = torch._dynamo.utils.counters
    except (AttributeError, RuntimeError):
        return {}
    selected: dict[str, int] = {}
    for group, names in {
        "stats": ("unique_graphs", "calls_captured"),
        "inductor": (
            "fxgraph_cache_hit",
            "fxgraph_cache_miss",
            "fxgraph_cache_bypass",
        ),
        "aot_autograd": ("total", "ok", "not_ok"),
    }.items():
        values = counters.get(group, {})
        for name in names:
            selected[f"{group}.{name}"] = int(values.get(name, 0))
    return selected


def _summary_packet_moments(
    *,
    metadata: Mapping[str, Any],
    candidate_id: str,
    strata: Sequence[str],
) -> dict[str, RunningMoment]:
    """Decode one summary-only suffix under cumulative binary support.

    Neyman growth may allocate a later suffix entirely to one stratum.  Both
    strata are required cumulatively, not inside every incremental packet.
    The packet must therefore contain exactly the moments represented by its
    own logical draws; its caller merges them with the prior history.
    """

    packet = {
        str(stratum): RunningMoment.from_mapping(moment)
        for stratum, moment in dict(
            dict(metadata.get("oracle_stratified_moments", {})).get(
                str(candidate_id),
                {},
            )
        ).items()
    }
    # One counting pass instead of one scan of ``strata`` per
    # declared stratum (strata x contexts); the counts are the same integers.
    stratum_labels = tuple(str(value) for value in strata)
    declared = tuple(dict.fromkeys(stratum_labels))
    label_counts = Counter(stratum_labels)
    expected_counts = {stratum: label_counts[stratum] for stratum in declared}
    represented = {
        stratum for stratum, count in expected_counts.items() if count > 0
    }
    if (
        not packet
        or not set(packet).issubset(declared)
        or set(packet) != represented
        or any(
            packet[stratum].count != expected_counts[stratum]
            for stratum in represented
        )
    ):
        raise ValueError(
            "summary-only native validation oracle has misaligned packet moments"
        )
    return packet


# v6 R2 (terminal lane handoff): the layout is a pure function of (labels,
# ordered context IDs, requested blocks).  The dense bank (step setup) and the
# final bank (terminal fit) rebuild it from identical inputs (~3-4 s at 256k
# rows: one sha256 per row).  The frozen, immutable layout is reused when the
# inputs compare equal; nothing else is keyed on its object identity.
_TERMINAL_LAYOUT_MEMO_LOCK = threading.Lock()
_TERMINAL_LAYOUT_MEMO: list[
    tuple[tuple[int, ...], tuple[str, ...], int, CrossFitLayout]
] = []
_TERMINAL_LAYOUT_MEMO_ENTRIES = 2


def terminal_category_crossfit_layout(
    labels: Sequence[int],
    context_ids: Sequence[str],
    *,
    requested_blocks: int,
    calibration_penalty_value: str | None = None,
) -> CrossFitLayout:
    """Memoized ``_terminal_category_crossfit_layout_uncached`` (exact)."""

    label_values = tuple(int(value) for value in labels)
    ids = tuple(str(value) for value in context_ids)
    blocks = int(requested_blocks)
    if (calibration_penalty() if calibration_penalty_value is None else calibration_penalty_value) == "firth":
        return CrossFitLayout.from_outer_fit_membership(ids, torch.ones((1, len(ids)), dtype=torch.bool))
    with _TERMINAL_LAYOUT_MEMO_LOCK:
        for cached_labels, cached_ids, cached_blocks, cached in _TERMINAL_LAYOUT_MEMO:
            if (
                cached_blocks == blocks
                and cached_labels == label_values
                and cached_ids == ids
            ):
                return cached
    layout = _terminal_category_crossfit_layout_uncached(
        label_values, ids, requested_blocks=blocks
    )
    with _TERMINAL_LAYOUT_MEMO_LOCK:
        _TERMINAL_LAYOUT_MEMO.append((label_values, ids, blocks, layout))
        del _TERMINAL_LAYOUT_MEMO[:-_TERMINAL_LAYOUT_MEMO_ENTRIES]
    return layout


def _multiclass_label_block_assignment(
    columns: Sequence[int],
    context_ids: tuple[str, ...],
    *,
    class_count: int,
    requested_blocks: int,
) -> tuple[list[int], int, str, str]:
    """``_binary_stratified_block_assignment`` on a one-hot target, from labels.

    Every one-hot row sums to one, so its multiclass stratum is its label
    column; block counts are integer label counts per block.
    """

    from contracts.hashing import stable_digest

    rule = "sha256_ordered_within_multiclass_stratum_round_robin_v1"
    groups: dict[int, list[int]] = {}
    for index, stratum in enumerate(columns):
        groups.setdefault(int(stratum), []).append(index)
    block_count = min(
        max(2, int(requested_blocks)), *(len(indices) for indices in groups.values())
    )
    if block_count < 2:
        raise ValueError(
            "cross-fit selection requires at least two examples of each stratum"
        )
    assignment = [-1] * len(context_ids)
    for stratum in sorted(groups):
        ordered = sorted(
            groups[stratum],
            key=lambda index: hashlib.sha256(
                f"{stratum}\0{context_ids[index]}".encode("utf-8")
            ).hexdigest(),
        )
        for rank, index in enumerate(ordered):
            assignment[index] = int(rank % block_count)
    blocks = np.asarray(assignment, dtype=np.int64)
    labels = np.asarray(columns, dtype=np.int64)
    heldout_positive = np.bincount(
        blocks * int(class_count) + labels, minlength=block_count * int(class_count)
    ).reshape(block_count, int(class_count))
    total_positive = np.bincount(labels, minlength=int(class_count))
    training_positive = total_positive[None, :] - heldout_positive
    heldout_rows = np.bincount(blocks, minlength=block_count)[:, None]
    training_rows = len(context_ids) - heldout_rows
    degenerate = (
        (heldout_positive == 0)
        | (heldout_positive == heldout_rows)
        | (training_positive == 0)
        | (training_positive == training_rows)
    )
    if bool(degenerate.any()):
        raise ValueError(
            "cross-fit inner blocks must retain both classes in train and holdout"
        )
    assignment_hash = stable_digest(
        {
            "rule": rule,
            "context_ids": context_ids,
            "block_ids": assignment,
            "block_count": block_count,
        }
    )
    return assignment, int(block_count), rule, assignment_hash


def _terminal_category_crossfit_layout_uncached(
    labels: Sequence[int],
    context_ids: Sequence[str],
    *,
    requested_blocks: int,
) -> CrossFitLayout:
    """One shared multiclass-stratified selection layout for category matrices.

    The registered batched one-vs-rest calibration shares ONE deterministic
    block assignment across every category column — the sealed core's
    ``sha256_ordered_within_multiclass_stratum_round_robin_v1`` rule, computed
    by the exact factored helper the core itself uses.  This constructor is
    equal to ``CrossFitLayout.from_binary_targets`` on the implied one-hot
    target matrix (membership, blocks, counts, support, rule, and block
    assignment hash all agree; a unit test pins the equality) but derives its
    content digest from the integer label vector instead of the full
    ``[context, category]`` float matrix, whose ``tolist()`` digest would
    transiently cost gigabytes at census scale.
    """

    if torch is None:
        raise RuntimeError("terminal category layout requires PyTorch")
    ids = tuple(str(value) for value in context_ids)
    label_values = tuple(int(value) for value in labels)
    if len(ids) != len(label_values) or len(set(ids)) != len(ids):
        raise ValueError(
            "terminal category layout requires aligned unique context IDs"
        )
    class_ids = tuple(sorted(set(label_values)))
    if len(class_ids) < 2:
        raise ValueError(
            "terminal category layout requires at least two represented classes"
        )
    column_by_class = {value: index for index, value in enumerate(class_ids)}
    columns = [column_by_class[value] for value in label_values]
    # The multiclass rule of ``_binary_stratified_block_assignment``
    # computed from the label columns instead of a [row, class] float64
    # one-hot (2 GB and about 2.5 s at 256k x 1000); same blocks and hashes.
    assignment, block_count, rule, block_hash = _multiclass_label_block_assignment(
        columns,
        ids,
        class_count=len(class_ids),
        requested_blocks=int(requested_blocks),
    )
    positive_counts = tuple(
        int(value) for value in np.bincount(columns, minlength=len(class_ids))
    )
    support = CrossFitSupport(
        outer_fold_index=0,
        fit_row_count=len(ids),
        positive_counts=positive_counts,
        negative_counts=tuple(
            len(ids) - value for value in positive_counts
        ),
        block_count=int(block_count),
    )
    context_digest = _raw_sha256(
        {"terminal_category_layout_context_ids": ids}
    )
    assignment_rows = tuple(int(value) for value in assignment)
    content_digest = _raw_sha256(
        {
            "schema_name": "terminal_category_cross_fit_layout_v1",
            "context_digest": context_digest,
            "labels": label_values,
            "class_ids": class_ids,
            "inner_block_ids": assignment_rows,
            "inner_block_count": int(block_count),
            "requested_block_count": int(requested_blocks),
            "stratification_rule": rule,
            "block_assignment_hash": block_hash,
        }
    )
    layout = CrossFitLayout(
        context_ids=ids,
        outer_fit_membership=(tuple(True for _ in ids),),
        inner_block_ids=(assignment_rows,),
        inner_block_counts=(int(block_count),),
        support=(support,),
        requested_block_count=int(requested_blocks),
        selection_enabled=True,
        stratification_rule=rule,
        block_assignment_hash=block_hash,
        context_digest=context_digest,
        content_digest=content_digest,
    )
    layout.validate()
    return layout


def _terminal_category_matrix_rows(
    readout_row: Any,
    declared_labels: Any,
    scale: Any,
    center: Any,
    offset: Any,
    bce_logit_clip: float | None,
    class_id: Any,
) -> tuple[Any, Any]:
    """Pure vector-shaped registered BCE and correctness rows."""

    logits = scale * (readout_row - center) + offset
    if bce_logit_clip is not None:
        logits = torch.clamp(
            logits,
            min=-bce_logit_clip,
            max=bce_logit_clip,
        )
    one_vs_rest = declared_labels == class_id
    bce_rows = torch.where(
        one_vs_rest,
        torch.nn.functional.softplus(-logits),
        torch.nn.functional.softplus(logits),
    ).to(dtype=torch.float64)
    correct_rows = (
        ((logits >= 0.0) == one_vs_rest).to(dtype=torch.float64)
    )
    return bce_rows, correct_rows


def _substituted_category_matrix_rows(
    readout_row: Any,
    declared_labels: Any,
    scale: Any,
    center: Any,
    offset: Any,
    c_row: Any,
    max_excluding_row: Any,
    bce_logit_clip: float | None,
    class_id: Any,
) -> tuple[Any, Any, Any]:
    """Pure vector-shaped substituted BCE and correctness rows."""

    calibrated_substituted_logit = scale * (readout_row - center) + offset
    substituted_logits = calibrated_substituted_logit - c_row.to(torch.float32)
    if bce_logit_clip is not None:
        substituted_logits = torch.clamp(
            substituted_logits,
            min=-bce_logit_clip,
            max=bce_logit_clip,
        )
    one_vs_rest = declared_labels == class_id
    substituted_bce_rows = torch.where(
        one_vs_rest,
        torch.nn.functional.softplus(-substituted_logits),
        torch.nn.functional.softplus(substituted_logits),
    ).to(dtype=torch.float64)
    substituted_correct_rows = (
        ((substituted_logits >= 0.0) == one_vs_rest).to(dtype=torch.float64)
    )
    hybrid_correct_rows = (
        ((calibrated_substituted_logit > max_excluding_row) == one_vs_rest).to(
            dtype=torch.float64
        )
    )
    return (
        substituted_bce_rows,
        substituted_correct_rows,
        hybrid_correct_rows,
    )


def _terminal_category_matrices_deferred_transfer(
    *,
    readout_by_category: Any,
    declared_labels: Any,
    class_ids: Sequence[int],
    segment_bounds: Sequence[tuple[int, int]],
    width: int,
    scale_values: Any,
    offset_values: Any,
    center_values: Any,
    bce_logit_clip: float | None,
) -> tuple[np.ndarray, np.ndarray]:
    """Registered per-category rows with one host capture per matrix."""

    row_count = int(readout_by_category.shape[1])
    bce_rows_device = torch.empty(
        (width, row_count),
        device=readout_by_category.device,
        dtype=torch.float64,
    )
    correct_rows_device = torch.empty_like(bce_rows_device)
    rows_fn, is_compiled = _terminal_compile_coverage_callable(
        "terminal_category_matrix_rows",
        _terminal_category_matrix_rows,
    )
    for class_id in class_ids:
        column = int(class_id)
        readout_row = readout_by_category[column].to(torch.float64)
        if is_compiled:
            scale: Any = readout_row.new_tensor(
                float(scale_values[column])
            )
            center: Any = readout_row.new_tensor(
                float(center_values[column])
            )
            offset: Any = readout_row.new_tensor(
                float(offset_values[column])
            )
            class_value: Any = declared_labels.new_tensor(column)
        else:
            scale = float(scale_values[column])
            center = float(center_values[column])
            offset = float(offset_values[column])
            class_value = column
        bce_rows, correct_rows = rows_fn(
            readout_row,
            declared_labels,
            scale,
            center,
            offset,
            bce_logit_clip,
            class_value,
        )
        bce_rows_device[column] = bce_rows
        correct_rows_device[column] = correct_rows

    bce_rows_by_category = (
        bce_rows_device.to(device="cpu").numpy()
    )
    correct_rows_by_category = (
        correct_rows_device.to(device="cpu").numpy()
    )
    stratum_count = len(segment_bounds)
    bce_matrix = np.full((stratum_count, width), np.nan, dtype=np.float64)
    accuracy_matrix = np.full(
        (stratum_count, width), np.nan, dtype=np.float64
    )
    for class_id in class_ids:
        column = int(class_id)
        bce_rows = bce_rows_by_category[column]
        correct_rows = correct_rows_by_category[column]
        for index, (start, stop) in enumerate(segment_bounds):
            bce_matrix[index, column] = np.mean(bce_rows[start:stop])
            accuracy_matrix[index, column] = np.mean(
                correct_rows[start:stop]
            )
    return bce_matrix, accuracy_matrix


def _category_accuracy_component_matrices(
    *,
    accuracy_matrix: np.ndarray,
    class_ids: Sequence[int],
    width: int,
) -> tuple[np.ndarray, np.ndarray]:
    """Split one-vs-rest correctness into sensitivity/specificity cells.

    Rows are true input strata and columns are one-vs-rest classifier
    categories.  A diagonal cell (row class == classifier class) is a
    sensitivity cell; an off-diagonal cell is a specificity cell.  This helper
    deliberately does not average across rows: it preserves the full matrix
    geometry and leaves inapplicable component cells as NaN.
    """

    accuracy = np.asarray(accuracy_matrix, dtype=np.float64)
    if accuracy.ndim != 2 or accuracy.shape != (len(class_ids), int(width)):
        raise ValueError("accuracy component matrix axes are misaligned")
    sensitivity = np.full_like(accuracy, np.nan, dtype=np.float64)
    specificity = np.full_like(accuracy, np.nan, dtype=np.float64)
    for row_index, class_id in enumerate(class_ids):
        for column in range(int(width)):
            if int(column) == int(class_id):
                sensitivity[row_index, column] = accuracy[row_index, column]
            else:
                specificity[row_index, column] = accuracy[row_index, column]
    return sensitivity, specificity


def _substituted_category_matrices_deferred_transfer(
    *,
    readout_by_category: Any,
    declared_labels: Any,
    class_ids: Sequence[int],
    segment_bounds: Sequence[tuple[int, int]],
    width: int,
    substituted_scale: Any,
    substituted_offset: Any,
    substituted_center: Any,
    c_matrix: Any,
    max_excluding_matrix: Any,
    bce_logit_clip: float | None,
) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
    """Substituted per-category rows with one host capture per matrix.

    The calibrated substituted-softmax OVR functional applies the target
    affine in its frozen centered frame and then subtracts the fixed dense
    competitor term:

        eta_k(x) = a_k (r_k(x; mask) - c_k) + b_k
                   - logsumexp_{j != k} r_j(x; dense).
    """

    row_count = int(readout_by_category.shape[1])
    substituted_bce_rows_device = torch.empty(
        (width, row_count),
        device=readout_by_category.device,
        dtype=torch.float64,
    )
    substituted_probability_rows_device = torch.empty_like(
        substituted_bce_rows_device
    )
    substituted_correct_rows_device = torch.empty_like(
        substituted_bce_rows_device
    )
    hybrid_correct_rows_device = torch.empty_like(
        substituted_bce_rows_device
    )
    for class_id in class_ids:
        column = int(class_id)
        readout_row = readout_by_category[column].to(torch.float64)
        substituted_logits = (
            float(substituted_scale[column])
            * (
                readout_row
                - float(substituted_center[column])
            )
            + float(substituted_offset[column])
            - c_matrix[column].to(torch.float64)
        )
        if bce_logit_clip is not None:
            substituted_logits = torch.clamp(
                substituted_logits,
                min=-bce_logit_clip,
                max=bce_logit_clip,
            )
        one_vs_rest = declared_labels == column
        substituted_bce_rows_device[column] = torch.where(
            one_vs_rest,
            torch.nn.functional.softplus(-substituted_logits),
            torch.nn.functional.softplus(substituted_logits),
        ).to(dtype=torch.float64)
        substituted_probability_rows_device[column] = torch.sigmoid(
            substituted_logits
        ).to(dtype=torch.float64)
        substituted_correct_rows_device[column] = (
            ((substituted_logits >= 0.0) == one_vs_rest).to(
                dtype=torch.float64
            )
        )
        # Independent one-vs-rest affines are not a calibrated joint multiclass
        # top-1 model.  Preserve the legacy array slot as NaN and disclose the
        # refusal in the sidecar receipt instead of mixing calibrated OVR logits
        # with raw rival logits.
        hybrid_correct_rows_device[column] = (
            torch.full_like(substituted_logits, torch.nan, dtype=torch.float64)
        )

    substituted_bce_rows_by_category = (
        substituted_bce_rows_device.to(device="cpu").numpy()
    )
    substituted_probability_rows_by_category = (
        substituted_probability_rows_device.to(device="cpu").numpy()
    )
    substituted_correct_rows_by_category = (
        substituted_correct_rows_device.to(device="cpu").numpy()
    )
    hybrid_correct_rows_by_category = (
        hybrid_correct_rows_device.to(device="cpu").numpy()
    )
    stratum_count = len(segment_bounds)
    substituted_bce_matrix = np.full(
        (stratum_count, width), np.nan, dtype=np.float64
    )
    substituted_probability_matrix = np.full(
        (stratum_count, width), np.nan, dtype=np.float64
    )
    substituted_accuracy_matrix = np.full(
        (stratum_count, width), np.nan, dtype=np.float64
    )
    hybrid_top1_matrix = np.full(
        (stratum_count, width), np.nan, dtype=np.float64
    )
    for class_id in class_ids:
        column = int(class_id)
        substituted_bce_rows = substituted_bce_rows_by_category[column]
        substituted_probability_rows = (
            substituted_probability_rows_by_category[column]
        )
        substituted_correct_rows = substituted_correct_rows_by_category[
            column
        ]
        hybrid_correct_rows = hybrid_correct_rows_by_category[column]
        for index, (start, stop) in enumerate(segment_bounds):
            substituted_bce_matrix[index, column] = np.mean(
                substituted_bce_rows[start:stop]
            )
            substituted_probability_matrix[index, column] = np.mean(
                substituted_probability_rows[start:stop]
            )
            substituted_accuracy_matrix[index, column] = np.mean(
                substituted_correct_rows[start:stop]
            )
            hybrid_top1_matrix[index, column] = np.mean(
                hybrid_correct_rows[start:stop]
            )
    return (
        substituted_probability_matrix,
        substituted_bce_matrix,
        substituted_accuracy_matrix,
        *_category_accuracy_component_matrices(
            accuracy_matrix=substituted_accuracy_matrix,
            class_ids=class_ids,
            width=width,
        ),
        hybrid_top1_matrix,
    )


# ---------------------------------------------------------------------------
# Per-step category-structure stack — pure derivation helpers.
#
# Everything in this block is deterministic closed-form mathematics over
# explicit array inputs (no provider state), so the sidecar consumers and the
# auditability tests can reproduce every emitted quantity offline from the
# stored raw objects alone.
# ---------------------------------------------------------------------------

STEP_CATEGORY_STRUCTURE_SCHEMA_V1 = "step_category_structure_v1"
STEP_CATEGORY_STRUCTURE_SCHEMA = "step_category_structure_v2"
STEP_CATEGORY_STRUCTURE_SCHEMA_V3 = "step_category_structure_v3"
STEP_CATEGORY_STRUCTURE_SCHEMA_V4 = "step_category_structure_v4"
STEP_CATEGORY_SUBSTITUTED_ENV = "CIRCUIT_STEP_CATEGORY_SUBSTITUTED"

# Registered numerics of the frozen-category readout lanes.
# ``runtime`` (default): the lanes run on the runtime backend
# under the process TF32 policy.  ``exact_float32`` runs the validation role's
# live lanes (the K=1 dense shortcut and the K=2 final/dense lanes alike)
# under ``core.numerics.exact_float32_numerics`` on a dedicated EAGER
# backend, so the dense capture and the final capture share one strict fp32
# context.  ``exact_float32_all_roles`` also applies it to the training role,
# so the mask rows match the fp32 canonical dense rows.  Opt-in only.
FROZEN_CATEGORY_READOUT_NUMERICS_ENV = "IRG_FROZEN_CATEGORY_READOUT_NUMERICS"
FROZEN_CATEGORY_READOUT_NUMERICS_RUNTIME = "runtime"
FROZEN_CATEGORY_READOUT_NUMERICS_EXACT = "exact_float32"
FROZEN_CATEGORY_READOUT_NUMERICS_EXACT_ALL_ROLES = "exact_float32_all_roles"
FROZEN_CATEGORY_READOUT_NUMERICS_STRICT_ROLES: Mapping[str, frozenset[str]] = {
    FROZEN_CATEGORY_READOUT_NUMERICS_RUNTIME: frozenset(),
    FROZEN_CATEGORY_READOUT_NUMERICS_EXACT: frozenset({"validation"}),
    FROZEN_CATEGORY_READOUT_NUMERICS_EXACT_ALL_ROLES: frozenset(
        {"validation", "training"}
    ),
}
FROZEN_CATEGORY_READOUT_NUMERICS_SCHEMA = "frozen_category_readout_numerics_v1"
FROZEN_CATEGORY_READOUT_STRICT_BACKEND_ID = (
    "torch_candidate_execution_shared_prefix_strict_fp32_v63"
)


def frozen_category_readout_numerics_setting(
    environ: Mapping[str, str] | None = None,
) -> str:
    """Resolve ``IRG_FROZEN_CATEGORY_READOUT_NUMERICS`` (default ``runtime``)."""

    source = os.environ if environ is None else environ
    raw = source.get(FROZEN_CATEGORY_READOUT_NUMERICS_ENV)
    if raw is None or not str(raw).strip():
        return FROZEN_CATEGORY_READOUT_NUMERICS_RUNTIME
    value = str(raw).strip().lower()
    if value not in FROZEN_CATEGORY_READOUT_NUMERICS_STRICT_ROLES:
        raise ValueError(
            f"{FROZEN_CATEGORY_READOUT_NUMERICS_ENV} must be one of "
            f"{sorted(FROZEN_CATEGORY_READOUT_NUMERICS_STRICT_ROLES)!r}, got {raw!r}"
        )
    return value


def _frozen_category_readout_numerics_of(provider: Any) -> str:
    """The provider's setting, resolved once at first use (duck-typed)."""

    resolved = getattr(provider, "_frozen_category_readout_numerics_resolved", None)
    if isinstance(resolved, str):
        return resolved
    resolved = frozen_category_readout_numerics_setting()
    try:
        setattr(provider, "_frozen_category_readout_numerics_resolved", resolved)
    except (AttributeError, TypeError):  # pragma: no cover - frozen shims
        pass
    return resolved


def _fixed_offset_affine_convergence_of(provider: Any) -> str:
    """The provider's convergence-test setting, resolved once at first use.

    Mirrors :func:`_frozen_category_readout_numerics_of`: the first reader
    pins the value on the provider, so the solver-request identity, the
    dense-fit cache key and the solver itself can never disagree within one
    provider's lifetime (rather than read from the environment per call).
    """

    resolved = getattr(provider, "_fixed_offset_affine_convergence_resolved", None)
    if isinstance(resolved, str):
        return resolved
    resolved = fixed_offset_affine_convergence_setting()
    try:
        setattr(provider, "_fixed_offset_affine_convergence_resolved", resolved)
    except (AttributeError, TypeError):  # pragma: no cover - frozen shims
        pass
    return resolved


def pin_frozen_category_optin_settings(
    provider: Any,
    *,
    frozen_category_readout_numerics: str | None = None,
    fixed_offset_affine_convergence: str | None = None,
) -> dict[str, str]:
    """Resolve (or accept pre-validated) opt-in settings and pin them.

    Called by the registered pilot right after it builds a provider, with the
    values it validated at entry, so an arm's settings are fixed before any
    fit, capture or cache key reads them.  Returns the pinned pair.
    """

    numerics = (
        frozen_category_readout_numerics_setting()
        if frozen_category_readout_numerics is None
        else frozen_category_readout_numerics_setting(
            {FROZEN_CATEGORY_READOUT_NUMERICS_ENV: str(frozen_category_readout_numerics)}
        )
    )
    convergence = (
        fixed_offset_affine_convergence_setting()
        if fixed_offset_affine_convergence is None
        else fixed_offset_affine_convergence_setting(
            {FIXED_OFFSET_AFFINE_CONVERGENCE_ENV: str(fixed_offset_affine_convergence)}
        )
    )
    for name, value in (
        ("_frozen_category_readout_numerics_resolved", numerics),
        ("_fixed_offset_affine_convergence_resolved", convergence),
    ):
        existing = getattr(provider, name, None)
        if isinstance(existing, str) and existing != value:
            raise ValueError(
                f"provider already pinned {name.strip('_')}={existing!r}; "
                f"refusing to re-pin it to {value!r}"
            )
        try:
            setattr(provider, name, value)
        except (AttributeError, TypeError):  # pragma: no cover - frozen shims
            pass
    return {
        "frozen_category_readout_numerics": numerics,
        "fixed_offset_affine_convergence": convergence,
    }


def frozen_category_fit_optin_fields(provider: Any) -> dict[str, str]:
    """Effective numerical and solver settings of a category fit."""
    from mechanistic_systems.backends.calibration_backend import (
        DENSE_REFERENCE_BANK_MAXIMUM_MISSING_CATEGORIES,
        FINAL_MASK_BANK_MAXIMUM_MISSING_CATEGORY_FRACTION,
        TERMINAL_BANK_MISSING_CELL_POLICY_ID,
    )
    return {
        "substituted_convergence_test": _fixed_offset_affine_convergence_of(provider),
        "frozen_category_readout_numerics": _frozen_category_readout_numerics_of(provider),
        "terminal_fit_execution": "fused_bank_fit_v6",
        "terminal_bank_missing_cell_policy": (
            f"{TERMINAL_BANK_MISSING_CELL_POLICY_ID}:dense="
            f"{DENSE_REFERENCE_BANK_MAXIMUM_MISSING_CATEGORIES}:final_fraction="
            f"{FINAL_MASK_BANK_MAXIMUM_MISSING_CATEGORY_FRACTION!r}"
        ),
    }


STEP_CATEGORY_LANES_ENV = "IRG_STEP_MATRIX_LANES"
# Registered default: exactly three per-step matrix
# families — raw logits, dynamically calibrated BCE, and dynamically
# calibrated substituted softmax. Everything else is opt-in ("all", or an
# explicit comma list) for special runs; at the AlexNet shape each extra
# lane costs 0.748 GB per arm.
_STEP_CATEGORY_ALL_LANES = frozenset(
    {
        "raw",
        "frozen_probability",
        "frozen_bce",
        "tracked_probability",
        "tracked_bce",
        "substituted_frozen_probability",
        "substituted_frozen_bce",
        "substituted_tracked_probability",
        "substituted_tracked_bce",
    }
)
_STEP_CATEGORY_DEFAULT_LANES = frozenset(
    {"raw", "tracked_bce", "substituted_tracked_probability"}
)


@dataclass(frozen=True)
class StepMatrixLanePreset:
    """A named ``IRG_STEP_MATRIX_LANES`` value.

    ``lanes`` is the delta-family lane set the preset selects.
    ``substituted_default`` is the value ``CIRCUIT_STEP_CATEGORY_SUBSTITUTED``
    takes when it is UNSET under this preset (``None`` = the module default,
    on).  An explicit ``CIRCUIT_STEP_CATEGORY_SUBSTITUTED`` always wins; the
    preset only supplies the default so that one environment value selects
    a complete registered configuration.
    """

    name: str
    lanes: frozenset
    substituted_default: bool | None


# Named lane presets.  ``production_v1`` is the set chosen
# for the modern-v0 kernel-tap campaign: the three ordinary ABSOLUTE families
# (raw_logit_mean, ordinary_calibrated_logit_mean, ordinary_bce_mean — the
# contract's load-bearing record, always registered regardless of lanes) plus
# the raw and tracked-BCE deltas, with the substituted functional OFF.  The
# module default (unset variable) remains the three-lane set so
# every pre-existing test and replay is unchanged; the runner lane selects
# the preset explicitly.
STEP_MATRIX_LANE_PRESETS: Mapping[str, StepMatrixLanePreset] = {
    "all": StepMatrixLanePreset(
        name="all", lanes=_STEP_CATEGORY_ALL_LANES, substituted_default=None
    ),
    "production_v1": StepMatrixLanePreset(
        name="production_v1",
        lanes=frozenset({"raw", "tracked_bce"}),
        substituted_default=False,
    ),
}


def _step_category_lanes_text() -> str:
    raw = os.environ.get(STEP_CATEGORY_LANES_ENV)
    return "" if raw is None else raw.strip().lower()


def step_category_matrix_lane_preset() -> str:
    """Name of the lane preset selected by ``IRG_STEP_MATRIX_LANES`` ('' if none)."""

    text = _step_category_lanes_text()
    return text if text in STEP_MATRIX_LANE_PRESETS else ""


def step_category_matrix_lanes() -> frozenset:
    """Resolve the enabled per-step matrix lane set.

    ``IRG_STEP_MATRIX_LANES`` accepts: unset/empty (module default, three
    lanes), a preset name from ``STEP_MATRIX_LANE_PRESETS`` (``all``,
    ``production_v1``), or an explicit comma list of lane names.  Unknown
    lane names raise.
    """

    text = _step_category_lanes_text()
    if not text:
        return _STEP_CATEGORY_DEFAULT_LANES
    preset = STEP_MATRIX_LANE_PRESETS.get(text)
    if preset is not None:
        return preset.lanes
    lanes = frozenset(part.strip() for part in text.split(",") if part.strip())
    unknown = lanes - _STEP_CATEGORY_ALL_LANES
    if unknown:
        raise ValueError(
            f"unknown step matrix lanes {sorted(unknown)!r}; "
            f"valid: {sorted(_STEP_CATEGORY_ALL_LANES)!r} or a preset in "
            f"{sorted(STEP_MATRIX_LANE_PRESETS)!r}"
        )
    return lanes


STEP_MATRIX_ROW_BUDGET_ENV = "IRG_STEP_MATRIX_ROW_BUDGET_BYTES"
STEP_MATRIX_ROW_BUDGET_DEFAULT_BYTES = 1 << 30


def step_matrix_row_budget_bytes() -> int:
    """Per-chunk byte budget for segment-reduction row/one-hot buffers."""

    raw = os.environ.get(STEP_MATRIX_ROW_BUDGET_ENV)
    if raw is None or not raw.strip():
        return process_device_memory_budget_bytes(STEP_MATRIX_ROW_BUDGET_DEFAULT_BYTES)
    value = int(raw.strip())
    if value <= 0:
        raise ValueError(f"{STEP_MATRIX_ROW_BUDGET_ENV} must be positive")
    return process_device_memory_budget_bytes(value)


STEP_CATEGORY_VARIANCE_EXPLAINED_ENV = "CIRCUIT_STEP_VARIANCE_EXPLAINED"
# corr^2 is identically 1 at n = 2 and undefined at n = 1: below this many
# covered contexts a variance-explained cell is DEGENERATE, not noisy, and is
# emitted as NaN with the per-cell count disclosed (excluded, never imputed).
VARIANCE_EXPLAINED_MIN_CONTEXTS = 3
# Registered tracker constants: chosen once at implementation time,
# receipted, never tuned per arm.
STEP_TRACKER_WEIGHT_FLOOR = 1e-6
STEP_TRACKER_DELTA_CLAMP = 1.0
STEP_TRACKER_SCALE_FLOOR = 1e-8
STEP_ANCHOR_INTERVAL = 10
STEP_TRACKER_STAT_AXIS = ("sw", "swx", "swxx", "swz", "swxz")
# Registered row chunk of the per-step category row pipeline
# (tracker sufficient statistics and the flush's elementwise row frames).
#
# Measured motivation: a K=2 production array lost 4 of 5
# tasks to CUDA OOM inside the accepted-step flush at the census-terminal
# decision shape (1,281,167 adjudication + 512 calibration rows, width 1000):
# the tracker held six to eight full [rows, width] float64 planes (9.55 GiB
# each) and the flush upcast whole matrices before every reduction.
#
# The constant is a ROW COUNT, fixed at registration: it never depends on free
# memory, on K, or on MPS co-tenancy, so the reassociation pattern of every
# chunked row sum (and therefore every emitted bit) is a pure function of the
# decision's row count.  2**16 rows is one 500 MiB float64 plane at width
# 1000: the tracker's per-chunk working set is at most eight such planes
# (about 4 GiB), a census decision takes 20 chunks, and each elementwise
# launch still covers 65.5M elements, far above the size at which an H200
# elementwise kernel is bandwidth-bound, so launch overhead stays negligible.
# Every decision with at most 2**16 rows (all early looks in the logs:
# 2,304 ... 55,040 rows) is a single chunk and reproduces the unchunked
# arithmetic bit-for-bit.
STEP_CATEGORY_ROW_CHUNK = 1 << 16


def step_category_substituted_enabled() -> bool:
    """Return whether substituted per-step category matrices are enabled.

    An explicit ``CIRCUIT_STEP_CATEGORY_SUBSTITUTED`` value decides.  When
    it is unset, the selected ``IRG_STEP_MATRIX_LANES`` preset supplies the
    default (``production_v1`` -> off); with no preset the default is on
    (unchanged behaviour).
    """

    value = os.environ.get(STEP_CATEGORY_SUBSTITUTED_ENV)
    if value is None or not value.strip():
        preset = STEP_MATRIX_LANE_PRESETS.get(step_category_matrix_lane_preset())
        if preset is not None and preset.substituted_default is not None:
            return bool(preset.substituted_default)
        return True
    return value.strip().lower() not in {"0", "false", "no"}


def step_category_variance_explained_enabled() -> bool:
    """Return whether per-step variance-explained matrices are enabled.

    DEFAULT OFF (exactly three
    per-step matrix families by default; each variance lane costs
    0.748 GB/arm at the AlexNet shape). Opt in explicitly.
    """

    value = os.environ.get(STEP_CATEGORY_VARIANCE_EXPLAINED_ENV)
    return value is not None and value.strip().lower() in {"1", "true", "yes"}


def _np_sigmoid(values: np.ndarray) -> np.ndarray:
    """Numerically stable float64 logistic function (branch-free per cell)."""

    values = np.asarray(values, dtype=np.float64)
    out = np.empty_like(values)
    positive = values >= 0.0
    out[positive] = 1.0 / (1.0 + np.exp(-values[positive]))
    exp_v = np.exp(values[~positive])
    out[~positive] = exp_v / (1.0 + exp_v)
    return out


def step_category_lambda_derivation(
    *,
    dense_census_counts: Sequence[int],
    oracle_minimum_per_stratum: int,
    measurement_role_streams: int = 2,
) -> dict[str, Any]:
    """Tracker decay derivation: lambda = 1 - 1/W_eff, receipted arithmetic.

    ``W_eff = ceil(dense_positives_per_class / expected_positives_per_step)``
    with ``dense_positives_per_class`` the median census-stratum population of
    the dense capture (the anchor's support, ~50 at ImageNet scale) and
    ``expected_positives_per_step`` the class-stratified draw-design floor per
    role (``oracle_minimum_per_stratum``: "2/stratum/step per role")
    times the number of measurement-side streams the tracker consumes (stream
    reuse: calibration + adjudication = 2).  Derived from actual counts
    at setup; never tuned.
    """

    counts = np.asarray(tuple(int(v) for v in dense_census_counts), dtype=np.int64)
    if counts.size == 0 or np.any(counts <= 0):
        raise ValueError("lambda derivation requires positive census counts")
    per_stratum = int(oracle_minimum_per_stratum)
    streams = int(measurement_role_streams)
    if per_stratum < 1 or streams < 1:
        raise ValueError("lambda derivation requires positive design floors")
    dense_positives_per_class = float(np.median(counts))
    expected_positives_per_step = float(per_stratum * streams)
    w_eff = int(math.ceil(dense_positives_per_class / expected_positives_per_step))
    w_eff = max(1, w_eff)
    decay = 1.0 - 1.0 / float(w_eff)
    return {
        "schema": "step_category_tracker_lambda_derivation_v1",
        "dense_positives_per_class_median": dense_positives_per_class,
        "dense_positives_per_class_min": int(counts.min()),
        "dense_positives_per_class_max": int(counts.max()),
        "oracle_minimum_per_stratum": per_stratum,
        "measurement_role_streams": streams,
        "expected_positives_per_step_per_category": expected_positives_per_step,
        "w_eff_rule": (
            "ceil(median_dense_census_stratum_count / "
            "(oracle_minimum_per_stratum * measurement_role_streams))"
        ),
        "w_eff": w_eff,
        "decay_lambda_rule": "1 - 1/w_eff",
        "decay_lambda": float(decay),
    }


def derive_category_clusters(
    moment_mean: np.ndarray,
    *,
    fitted_mask: np.ndarray,
) -> dict[str, Any]:
    """Cluster derivation from the DENSE terminal moment-mean matrix.

    Columns (categories) of the dense per-(stratum, logit) raw-moment mean
    matrix are clustered by agglomerative AVERAGE linkage on the column
    correlation distance ``d = 1 - corr`` (scipy.cluster.hierarchy.linkage,
    method="average", on the condensed float64 distance;
    scipy.cluster.hierarchy.fcluster criterion="maxclust").  The cluster count
    ``k`` is the eigengap-maximal rule on the correlation spectrum: with
    eigenvalues sorted descending, ``k = argmax_k (lam_k - lam_{k+1})`` over
    ``k in 1..W_f-1`` breaking ties toward the SMALLEST ``k`` (first
    occurrence).  Zero-variance columns are defined to carry correlation 0
    with every other column (distance 1) and 1 with themselves.  Cluster ids
    are relabeled deterministically by the smallest member column index.
    Unfitted categories receive assignment -1 and never enter the hierarchy.
    """

    matrix = np.asarray(moment_mean, dtype=np.float64)
    fitted = np.asarray(fitted_mask, dtype=bool).reshape(-1)
    if matrix.ndim != 2 or matrix.shape[1] != fitted.size:
        raise ValueError("cluster derivation axes are misaligned")
    width = int(matrix.shape[1])
    fitted_columns = np.flatnonzero(fitted)
    assignment = np.full(width, -1, dtype=np.int64)
    spectrum = np.full(width, np.nan, dtype=np.float64)
    if fitted_columns.size == 0:
        raise ValueError("cluster derivation requires at least one fitted category")
    sub = matrix[:, fitted_columns]
    centered = sub - sub.mean(axis=0, keepdims=True)
    scale = np.sqrt((centered * centered).sum(axis=0))
    degenerate = scale <= 0.0
    safe_scale = np.where(degenerate, 1.0, scale)
    normalized = centered / safe_scale[None, :]
    correlation = normalized.T @ normalized
    correlation[degenerate, :] = 0.0
    correlation[:, degenerate] = 0.0
    np.fill_diagonal(correlation, 1.0)
    correlation = np.clip((correlation + correlation.T) / 2.0, -1.0, 1.0)
    np.fill_diagonal(correlation, 1.0)
    eigenvalues = np.linalg.eigvalsh(correlation)[::-1].copy()
    spectrum[: eigenvalues.size] = eigenvalues
    count = int(fitted_columns.size)
    if count == 1:
        k = 1
        assignment[fitted_columns[0]] = 0
        realized = 1
        linkage_call = "single_fitted_category_no_linkage"
    else:
        gaps = eigenvalues[:-1] - eigenvalues[1:]
        k = int(np.argmax(gaps)) + 1
        from scipy.cluster.hierarchy import fcluster, linkage
        from scipy.spatial.distance import squareform

        distance = 1.0 - correlation
        np.fill_diagonal(distance, 0.0)
        condensed = squareform(distance, checks=False)
        tree = linkage(condensed, method="average")
        raw_labels = fcluster(tree, t=k, criterion="maxclust")
        order: dict[int, int] = {}
        for label in raw_labels:
            if int(label) not in order:
                order[int(label)] = len(order)
        for position, column in enumerate(fitted_columns):
            assignment[column] = order[int(raw_labels[position])]
        realized = len(order)
        linkage_call = (
            "scipy.cluster.hierarchy.linkage(squareform(1-corr, checks=False),"
            " method='average'); fcluster(tree, t=k, criterion='maxclust')"
        )
    import scipy

    return {
        "schema": "step_category_cluster_derivation_v1",
        "assignment": assignment,
        "spectrum": spectrum,
        "k_rule": (
            "eigengap_maximal_first_occurrence_on_descending_"
            "correlation_spectrum"
        ),
        "k_eigengap": int(k),
        "k_realized": int(realized),
        "distance": "one_minus_column_pearson_correlation_float64",
        "zero_variance_rule": "correlation_zero_against_all_other_columns",
        "linkage_call": linkage_call,
        "tie_breaking": (
            "argmax first occurrence for k; cluster ids relabeled by "
            "smallest member column index"
        ),
        "scipy_version": str(scipy.__version__),
        "fitted_category_count": count,
    }


def tracker_anchor_sufficient_statistics(
    *,
    dense_scale: np.ndarray,
    dense_offset: np.ndarray,
    moment_mean: np.ndarray,
    moment_m2: np.ndarray,
    counts: np.ndarray,
    stratum_class_ids: np.ndarray,
    fitted_mask: np.ndarray,
) -> dict[str, np.ndarray]:
    """Dense anchoring: initial EW sufficient statistics per category.

    The anchor is constructed so the 2-parameter weighted-least-squares solve
    on the initial statistics returns the dense affine as its exact fixpoint:
    (Sw, Swx, Swxx) are the census IRLS moments approximated from the STORED
    dense matrices (per-stratum pseudo-rows at the stratum mean readout with
    the within-stratum variance folded into Swxx, IRLS weight evaluated at
    the dense affine), and (Swz, Swxz) are then DEFINED as
    ``Swz = Sw*b0 + Swx*a0`` and ``Swxz = Swx*b0 + Swxx*a0``.  Everything is
    float64 and reproducible offline from the dense sidecar arrays alone.
    """

    scale = np.asarray(dense_scale, dtype=np.float64).reshape(-1)
    offset = np.asarray(dense_offset, dtype=np.float64).reshape(-1)
    mean = np.asarray(moment_mean, dtype=np.float64)
    m2 = np.asarray(moment_m2, dtype=np.float64)
    stratum_counts = np.asarray(counts, dtype=np.float64).reshape(-1)
    classes = np.asarray(stratum_class_ids, dtype=np.int64).reshape(-1)
    fitted = np.asarray(fitted_mask, dtype=bool).reshape(-1)
    width = scale.size
    if (
        mean.shape != m2.shape
        or mean.shape != (stratum_counts.size, width)
        or classes.size != stratum_counts.size
        or offset.size != width
        or fitted.size != width
    ):
        raise ValueError("tracker anchor axes are misaligned")
    safe_scale = np.where(fitted, scale, 0.0)
    safe_offset = np.where(fitted, offset, 0.0)
    variance = m2 / stratum_counts[:, None]
    logits = safe_scale[None, :] * mean + safe_offset[None, :]
    probability = _np_sigmoid(logits)
    weight = probability * (1.0 - probability)
    weighted = stratum_counts[:, None] * weight
    sw = weighted.sum(axis=0)
    swx = (weighted * mean).sum(axis=0)
    swxx = (weighted * (mean * mean + variance)).sum(axis=0)
    swz = sw * safe_offset + swx * safe_scale
    swxz = swx * safe_offset + swxx * safe_scale
    stats = np.stack((sw, swx, swxx, swz, swxz), axis=0)
    stats[:, ~fitted] = 0.0
    rows = np.where(fitted, float(stratum_counts.sum()), 0.0)
    positives = np.zeros(width, dtype=np.float64)
    for index, class_id in enumerate(classes):
        if 0 <= int(class_id) < width and fitted[int(class_id)]:
            positives[int(class_id)] = float(stratum_counts[index])
    return {
        "stats": stats,
        "rows": rows,
        "positives": positives,
    }


class _StepRowSource:
    """Lazy ``[rows, width]`` row matrix materialized one row window at a time.

    The logical matrix is the row concatenation of
    ``segments`` (each slice cast to ``cast_dtype`` when given -- a
    per-segment ``.to(torch.float32)`` before ``torch.cat``),
    optionally row-gathered by ``index`` (int64 positions into that
    concatenation -- an ``index_select`` chain), optionally
    negated, and optionally centered by ``center`` (subtracted in the window
    dtype, exactly a full-matrix ``rows - center[None, :]``).
    Every step is either a value copy or the same elementwise IEEE operation
    applied to the same operands, so ``window(a, b)`` equals rows ``a:b`` of
    the fully materialized matrix bit-for-bit, while only one window
    is ever resident.
    """

    __slots__ = (
        "segments",
        "index",
        "center",
        "cast_dtype",
        "negate",
        "row_count",
        "width",
        "device",
        "dtype",
        "_offsets",
        "_index_host",
    )
    ndim = 2

    def __init__(
        self,
        segments: Sequence[Any],
        *,
        index: Any | None = None,
        center: Any | None = None,
        cast_dtype: Any | None = None,
        negate: bool = False,
    ) -> None:
        if torch is None:
            raise RuntimeError("step row sources require PyTorch")
        parts = tuple(segments)
        if not parts:
            raise ValueError("step row source requires at least one segment")
        for part in parts:
            if int(part.ndim) != 2:
                raise ValueError(
                    "tracker update requires a [row, category] matrix"
                )
        widths = {int(part.shape[1]) for part in parts}
        if len(widths) != 1:
            raise ValueError("step row source segments differ in width")
        dtypes = {part.dtype for part in parts}
        if cast_dtype is None and len(dtypes) != 1:
            raise ValueError(
                "step row source segments differ in dtype and no cast is set"
            )
        self.segments = parts
        self.width = widths.pop()
        self.device = parts[0].device
        self.cast_dtype = cast_dtype
        self.dtype = cast_dtype if cast_dtype is not None else parts[0].dtype
        offsets = [0]
        for part in parts:
            offsets.append(offsets[-1] + int(part.shape[0]))
        self._offsets = tuple(offsets)
        total = offsets[-1]
        if index is not None:
            # The locator is metadata built from host source identities.
            # Keep it on the host for static window planning as well as on
            # the device for the row gather.
            host_index = np.asarray(index).reshape(-1)
            if host_index.dtype != np.int64:
                raise TypeError("step row source index must be int64")
            if host_index.size and (
                int(host_index.min()) < 0 or int(host_index.max()) >= total
            ):
                raise IndexError("step row source index out of range")
            self._index_host = host_index.copy()
            index = upload_metadata(host_index, self.device, dtype=torch.int64)
            self.row_count = int(host_index.size)
        else:
            self._index_host = None
            self.row_count = total
        self.index = index
        self.center = center
        self.negate = bool(negate)

    @property
    def shape(self) -> tuple[int, int]:
        return (int(self.row_count), int(self.width))

    def _cast(self, rows: Any) -> Any:
        return rows if self.cast_dtype is None else rows.to(self.cast_dtype)

    def _contiguous_rows(self, start: int, stop: int) -> Any:
        pieces = []
        for part, lo, hi in zip(
            self.segments, self._offsets[:-1], self._offsets[1:], strict=True
        ):
            a, b = max(start, lo), min(stop, hi)
            if b > a:
                pieces.append(self._cast(part[a - lo : b - lo]))
        if not pieces:
            return torch.empty(
                (0, self.width), device=self.device, dtype=self.dtype
            )
        return pieces[0] if len(pieces) == 1 else torch.cat(pieces, dim=0)

    def _gathered_rows(self, start: int, stop: int) -> Any:
        positions = self.index[start:stop]
        if len(self.segments) == 1:
            return self._cast(torch.index_select(self.segments[0], 0, positions))
        out = torch.empty(
            (int(positions.numel()), self.width),
            device=self.device,
            dtype=self.dtype,
        )
        for part, lo, hi in zip(
            self.segments, self._offsets[:-1], self._offsets[1:], strict=True
        ):
            host_positions = self._index_host[start:stop]
            host_local = np.flatnonzero((host_positions >= lo) & (host_positions < hi))
            if host_local.size:
                local = upload_metadata(host_local, self.device, dtype=torch.int64)
                out.index_copy_(
                    0,
                    local,
                    self._cast(
                        torch.index_select(part, 0, positions[local] - lo)
                    ),
                )
        return out

    def window(self, start: int, stop: int) -> Any:
        """Rows ``start:stop`` of the logical matrix (window dtype)."""

        rows = (
            self._contiguous_rows(start, stop)
            if self.index is None
            else self._gathered_rows(start, stop)
        )
        if self.negate:
            rows = -rows
        if self.center is not None:
            rows = rows - self.center[None, :]
        return rows


def _step_row_chunks(row_count: int, row_chunk: int) -> tuple[tuple[int, int], ...]:
    """Fixed-size ``[start, stop)`` row windows tiling ``range(row_count)``."""

    chunk = int(row_chunk)
    if chunk <= 0:
        raise ValueError("step category row chunk must be positive")
    return tuple(
        (start, min(start + chunk, int(row_count)))
        for start in range(0, int(row_count), chunk)
    )


def tracker_decision_update(
    *,
    stats: Any,
    rows: Any,
    positives: Any,
    scale: Any,
    offset: Any,
    fitted: Any,
    readouts: Any,
    labels: Any,
    decay_lambda: float,
    fixed_offset: Any | None = None,
    weight_floor: float = STEP_TRACKER_WEIGHT_FLOOR,
    delta_clamp: float = STEP_TRACKER_DELTA_CLAMP,
    scale_floor: float = STEP_TRACKER_SCALE_FLOOR,
    row_chunk: int = STEP_CATEGORY_ROW_CHUNK,
) -> dict[str, Any]:
    """One per-decision EW-IRLS tracker update, batched over categories.

    Float64 throughout.  The working response is linearized at the CURRENT
    tracker affine (one bounded Newton/IRLS step per decision): with
    ``z = a*x + b + c``, ``p = sigmoid(z)``,
    ``w = clamp(p(1-p), weight_floor)``
    and one-vs-rest label ``y``, the working response is
    ``z_work = z + (y - p)/w``; the five sufficient statistics decay by
    ``lambda`` and absorb the batch sums; the 2x2 weighted normal
    equations regress the offset-adjusted working response
    ``z_work - c`` and solve in closed form; the parameter step is clamped
    elementwise
    to ``delta_clamp`` (the registered bound) and the scale floored at
    ``scale_floor``.  Categories with a singular system keep their previous
    affine for the step (solve_ok False).

    Row streaming.  The five batch statistics and the
    positive counts are plain sums over the row axis, so the row axis is
    streamed in fixed ``row_chunk`` windows (registered
    ``STEP_CATEGORY_ROW_CHUNK``, never derived from free memory or K): each
    window's per-cell quantities are the identical float64 expressions
    evaluated on that window's rows, reduced by ``torch.sum(..., dim=0)``,
    and the per-window float64 sums are added in window order.  A decision
    with at most ``row_chunk`` rows is one window and reproduces the
    unchunked arithmetic bit-for-bit; a larger one differs only by float64
    reassociation of the same terms (positives are exact integer sums in any
    order).  The closed-form solve, clamp, floor and where-guards are
    unchanged.  ``readouts`` / ``fixed_offset`` may be a tensor or a
    ``_StepRowSource`` (lazy concatenation / gather / centering of row
    segments, bit-exact per window); ``fixed_offset`` finiteness is checked
    over every row before any statistic is formed.
    """

    if torch is None:
        raise RuntimeError("step category tracker requires PyTorch")
    if isinstance(readouts, _StepRowSource):
        source = readouts
    else:
        if int(readouts.ndim) != 2:
            raise ValueError("tracker update requires a [row, category] matrix")
        source = _StepRowSource((readouts,))
    row_count = int(source.row_count)
    width = int(source.width)
    device = source.device
    label64 = labels.to(dtype=torch.int64).reshape(-1)
    if int(label64.numel()) != row_count:
        raise ValueError("tracker update labels differ from the row axis")
    class_index = torch.arange(width, device=device, dtype=torch.int64)
    windows = _step_row_chunks(row_count, row_chunk)
    fixed_source = None
    if fixed_offset is not None:
        if isinstance(fixed_offset, _StepRowSource):
            fixed_source = fixed_offset
        else:
            fixed_tensor = (
                fixed_offset
                if torch.is_tensor(fixed_offset)
                else torch.as_tensor(
                    fixed_offset, device=device, dtype=torch.float64
                )
            )
            if int(fixed_tensor.ndim) != 2:
                raise ValueError(
                    "tracker fixed offset requires a [row, category] matrix"
                )
            fixed_source = _StepRowSource((fixed_tensor,))
        if tuple(fixed_source.shape) != (row_count, width):
            raise ValueError(
                "tracker fixed offset requires a [row, category] matrix"
            )
        # Finite in the source dtype <=> finite after the exact float64 upcast
        # (negation preserves finiteness), so this covers every row exactly as
        # a full-matrix check would, one window at a time.
        for start, stop in windows:
            DEVICE_FAULTS.note(
                ~torch.isfinite(fixed_source.window(start, stop)).all(),
                lambda: ValueError("tracker fixed offset must be finite"),
            )
    totals: list[Any] | None = None
    for start, stop in windows:
        x64 = source.window(start, stop).to(dtype=torch.float64)
        one_vs_rest = (
            label64[start:stop, None] == class_index[None, :]
        ).to(torch.float64)
        z = x64 * scale[None, :] + offset[None, :]
        fixed64 = None
        if fixed_source is not None:
            fixed64 = fixed_source.window(start, stop).to(
                device=x64.device, dtype=torch.float64
            )
            z = z + fixed64
        p = torch.sigmoid(z)
        w = torch.clamp(p * (1.0 - p), min=float(weight_floor))
        z_work = z + (one_vs_rest - p) / w
        del z, p
        # ``w * x64 * x64`` and ``w * x64 * adjusted`` evaluate left to right,
        # so reusing the one ``w * x64`` product is the same IEEE sequence.
        wx = w * x64
        adjusted_work = z_work if fixed64 is None else z_work - fixed64
        del z_work, fixed64
        partial = (
            torch.sum(w, dim=0),
            torch.sum(wx, dim=0),
            torch.sum(wx * x64, dim=0),
            torch.sum(w * adjusted_work, dim=0),
            torch.sum(wx * adjusted_work, dim=0),
            torch.sum(one_vs_rest, dim=0),
        )
        del x64, one_vs_rest, w, wx, adjusted_work
        if totals is None:
            totals = list(partial)
        else:
            for total, value in zip(totals, partial, strict=True):
                total.add_(value)
    if totals is None:
        totals = [
            torch.zeros(width, device=device, dtype=torch.float64)
            for _ in range(6)
        ]
    batch_sw, batch_swx, batch_swxx, batch_swz, batch_swxz, batch_positives = (
        totals
    )
    batch = torch.stack(
        (batch_sw, batch_swx, batch_swxx, batch_swz, batch_swxz), dim=0
    )
    lam = float(decay_lambda)
    new_stats = lam * stats + batch
    new_rows = lam * rows + float(row_count)
    new_positives = lam * positives + batch_positives
    sw, swx, swxx, swz, swxz = (new_stats[i] for i in range(5))
    det = sw * swxx - swx * swx
    solve_ok = fitted & (det > 0.0) & (sw > 0.0) & (swxx > 0.0)
    safe_det = torch.where(solve_ok, det, torch.ones_like(det))
    offset_raw = (swxx * swz - swx * swxz) / safe_det
    scale_raw = (sw * swxz - swx * swz) / safe_det
    clamp = float(delta_clamp)
    offset_new = offset + torch.clamp(offset_raw - offset, min=-clamp, max=clamp)
    scale_new = scale + torch.clamp(scale_raw - scale, min=-clamp, max=clamp)
    scale_new = torch.clamp(scale_new, min=float(scale_floor))
    offset_new = torch.where(solve_ok, offset_new, offset)
    scale_new = torch.where(solve_ok, scale_new, scale)
    zero = torch.zeros_like(det)
    precision_offset = torch.where(solve_ok, det / swxx, zero)
    precision_scale = torch.where(solve_ok, det / sw, zero)
    new_stats = torch.where(fitted[None, :], new_stats, torch.zeros_like(new_stats))
    return {
        "stats": new_stats,
        "rows": torch.where(fitted, new_rows, torch.zeros_like(new_rows)),
        "positives": torch.where(
            fitted, new_positives, torch.zeros_like(new_positives)
        ),
        "scale": scale_new,
        "offset": offset_new,
        "solve_ok": solve_ok,
        "precision_offset": precision_offset,
        "precision_scale": precision_scale,
        "batch_row_count": row_count,
    }


@dataclass(frozen=True)
class StepCategoryStructureConfig:
    """Frozen setup-scope inputs for the per-step category-structure stack.

    Built once per arm at walk setup (dense-side terminal arrays via the
    shared cache; cluster derivation; derived decay) and handed
    to the provider before the first paired decision.  Every array is float64
    or int64 numpy; the accumulator moves what it needs onto the device.
    """

    target_class_id: int
    stratum_class_ids: tuple[int, ...]
    dense_scale: np.ndarray
    dense_offset: np.ndarray
    dense_input_center: np.ndarray
    dense_fitted_mask: np.ndarray
    dense_moment_mean: np.ndarray
    dense_moment_m2: np.ndarray
    dense_counts: np.ndarray
    dense_stratum_class_ids: np.ndarray
    cluster_assignment: np.ndarray
    cluster_spectrum: np.ndarray
    cluster_receipt: Mapping[str, Any]
    lambda_receipt: Mapping[str, Any]
    anchor_interval: int = STEP_ANCHOR_INTERVAL
    substituted_dense_scale: np.ndarray | None = None
    substituted_dense_offset: np.ndarray | None = None
    substituted_dense_input_center: np.ndarray | None = None
    substituted_dense_fitted_mask: np.ndarray | None = None

    @property
    def decay_lambda(self) -> float:
        return float(self.lambda_receipt["decay_lambda"])

    @property
    def cluster_count(self) -> int:
        return int(self.cluster_receipt["k_realized"])


def _immutable_category_array(
    value: Any,
    *,
    dtype: str,
    name: str,
    shape: tuple[int, ...],
    finite: bool = False,
) -> np.ndarray:
    """Freeze a provider-owned array on an immutable ``bytes`` backing."""

    array = np.asarray(value, dtype=np.dtype(dtype))
    if tuple(array.shape) != tuple(shape):
        raise CalibrationContractError(
            f"{name} shape {array.shape!r} differs from {shape!r}"
        )
    if finite and not np.isfinite(array).all():
        raise CalibrationContractError(f"{name} must contain only finite values")
    contiguous = np.ascontiguousarray(array)
    return np.frombuffer(contiguous.tobytes(order="C"), dtype=contiguous.dtype).reshape(
        contiguous.shape
    )


def _exact_category_identity(value: Any, *, name: str) -> str:
    """Require an exact nonempty string on category evidence boundaries."""

    if not isinstance(value, str):
        raise CalibrationContractError(f"{name} must be an exact string identity")
    checked = value.strip()
    if not checked:
        raise CalibrationContractError(f"{name} must be non-empty")
    return checked


def _category_ready_columns(
    class_ids: np.ndarray,
    unready: tuple[int, ...],
) -> np.ndarray | None:
    """Ready classifier columns, or ``None`` on the strict default path."""

    if not unready:
        return None
    return ~np.isin(
        np.asarray(class_ids, dtype=np.int64),
        np.asarray(unready, dtype=np.int64),
    )


def _category_training_evaluation_hash_payload(
    *,
    bank: FrozenCategoryCalibrationBank,
    functional: CalibrationFunctional,
    mask_readout_hash: str,
    dense_reference_readout_hash: str,
    class_ids: np.ndarray,
    labels: np.ndarray,
    counts: np.ndarray,
    mean_functional_input: np.ndarray,
    mean_calibrated_logit: np.ndarray,
    mean_probability: np.ndarray,
    mean_bce: np.ndarray,
    binary_accuracy: np.ndarray,
    unready_class_ids: tuple[int, ...],
) -> dict[str, Any]:
    """The train-side evaluation identity; carried ids only when present."""

    payload: dict[str, Any] = {
        "schema": "irg_frozen_category_training_evaluation_v1",
        "role": "training_descriptive_no_validation_authority",
        "bank_hash": bank.content_hash,
        "functional": functional.value,
        "mask_training_readout_hash": mask_readout_hash,
        "dense_reference_training_readout_hash": dense_reference_readout_hash,
        "class_ids": class_ids,
        "labels": labels,
        "counts": counts,
        "mean_functional_input": mean_functional_input,
        "mean_calibrated_logit": mean_calibrated_logit,
        "mean_probability": mean_probability,
        "mean_bce": mean_bce,
        "binary_accuracy": binary_accuracy,
    }
    if unready_class_ids:
        payload["unready_class_ids"] = tuple(unready_class_ids)
    return payload


def _frozen_category_training_matrices(
    *,
    bank: FrozenCategoryCalibrationBank,
    functional: CalibrationFunctional,
    mask_rows: np.ndarray,
    dense_exclusion_rows: np.ndarray,
    labels: np.ndarray,
    counts: np.ndarray,
    mask_readout_hash: str,
    dense_reference_readout_hash: str,
) -> CategoryStratifiedEvaluationMatrices:
    """Reduce train-side rows under already-fitted states without a forward.

    This is descriptive setup evidence, not a validation evaluation.  The
    source hashes bind the exact readouts that were still live during fitting,
    and the returned typed matrices are bytes-backed and immutable.

    The substituted functional of a tolerated bank carries
    its unready classes as NaN columns with explicit ids; the ordinary
    functional reads strictly and raises exactly as before.
    """

    checked_functional = CalibrationFunctional(functional)
    class_ids = np.asarray(bank.class_ids, dtype=np.int64)
    width = int(class_ids.size)
    raw = np.asarray(mask_rows, dtype=np.float64)
    exclusions = np.asarray(dense_exclusion_rows, dtype=np.float64)
    label_values = np.asarray(labels, dtype=np.int64)
    count_values = np.asarray(counts, dtype=np.int64)
    expected_shape = (int(label_values.size), width)
    if (
        raw.shape != expected_shape
        or exclusions.shape != expected_shape
        or count_values.shape != (width,)
        or int(np.sum(count_values, dtype=np.int64)) != int(label_values.size)
        or not np.isfinite(raw).all()
        or not np.isfinite(exclusions).all()
    ):
        raise CalibrationContractError(
            "training category matrix source axes are invalid"
        )
    scale, offset, center, unready = bank.evaluation_affine_arrays(
        checked_functional
    )
    ready = _category_ready_columns(class_ids, unready)
    if ready is not None:
        # Carried columns are never evaluated: a zero placeholder affine keeps
        # NaN out of the arithmetic, leaves every ready column byte-identical
        # (all operations are elementwise or per column), and each carried
        # column is overwritten with NaN below.
        scale, offset, center = (
            np.where(ready, array, 0.0) for array in (scale, offset, center)
        )
    fixed_offsets = (
        np.zeros_like(raw, dtype=np.float64)
        if checked_functional is CalibrationFunctional.ORDINARY_OVR
        else exclusions
    )
    calibrated = (
        scale[None, :] * (raw - center[None, :])
        + offset[None, :]
        - fixed_offsets
    )
    if not np.isfinite(calibrated).all():
        raise CalibrationContractError(
            "training frozen affine application produced non-finite logits"
        )
    probability = np.empty_like(calibrated, dtype=np.float64)
    nonnegative = calibrated >= 0.0
    probability[nonnegative] = 1.0 / (1.0 + np.exp(-calibrated[nonnegative]))
    exponent = np.exp(calibrated[~nonnegative])
    probability[~nonnegative] = exponent / (1.0 + exponent)
    targets = label_values[:, None] == class_ids[None, :]
    target_float = targets.astype(np.float64, copy=False)
    bce = (
        np.maximum(calibrated, 0.0)
        - calibrated * target_float
        + np.log1p(np.exp(-np.abs(calibrated)))
    )
    correct = (calibrated >= 0.0) == targets

    shape = (width, width)
    mean_raw = np.empty(shape, dtype=np.float64)
    mean_calibrated = np.empty(shape, dtype=np.float64)
    mean_probability = np.empty(shape, dtype=np.float64)
    mean_bce = np.empty(shape, dtype=np.float64)
    binary_accuracy = np.empty(shape, dtype=np.float64)
    cursor = 0
    for row_index, raw_count in enumerate(count_values):
        stop = cursor + int(raw_count)
        selection = slice(cursor, stop)
        mean_raw[row_index] = np.mean(raw[selection], axis=0, dtype=np.float64)
        mean_calibrated[row_index] = np.mean(
            calibrated[selection], axis=0, dtype=np.float64
        )
        mean_probability[row_index] = np.mean(
            probability[selection], axis=0, dtype=np.float64
        )
        mean_bce[row_index] = np.mean(bce[selection], axis=0, dtype=np.float64)
        binary_accuracy[row_index] = np.mean(
            correct[selection], axis=0, dtype=np.float64
        )
        cursor = stop
    if ready is not None:
        for matrix in (mean_calibrated, mean_probability, mean_bce, binary_accuracy):
            matrix[:, ~ready] = np.nan
    sensitivity_defined = np.eye(width, dtype=np.bool_)
    specificity_defined = ~sensitivity_defined
    sensitivity = np.where(sensitivity_defined, binary_accuracy, 0.0)
    specificity = np.where(specificity_defined, binary_accuracy, 0.0)
    evaluation_hash = content_hash(
        _category_training_evaluation_hash_payload(
            bank=bank,
            functional=checked_functional,
            mask_readout_hash=mask_readout_hash,
            dense_reference_readout_hash=dense_reference_readout_hash,
            class_ids=class_ids,
            labels=label_values,
            counts=count_values,
            mean_functional_input=mean_raw,
            mean_calibrated_logit=mean_calibrated,
            mean_probability=mean_probability,
            mean_bce=mean_bce,
            binary_accuracy=binary_accuracy,
            unready_class_ids=unready,
        ),
        prefix="irg-category-training-evaluation-",
    )
    return CategoryStratifiedEvaluationMatrices(
        evaluation_hash=evaluation_hash,
        functional=checked_functional,
        class_ids=class_ids,
        labels=label_values,
        stratum_counts=count_values,
        mean_functional_input=mean_raw,
        mean_calibrated_logit=mean_calibrated,
        mean_probability=mean_probability,
        mean_bce=mean_bce,
        binary_accuracy=binary_accuracy,
        sensitivity_component=sensitivity,
        sensitivity_defined=sensitivity_defined,
        specificity_component=specificity,
        specificity_defined=specificity_defined,
        unready_class_ids=unready,
    )


def _frozen_category_training_matrices_streamed_device(
    *,
    bank: FrozenCategoryCalibrationBank,
    functional: CalibrationFunctional,
    mask_rows: Any,
    dense_exclusion_by_category: Any,
    labels: Any,
    counts: Any,
    mask_readout_hash: str,
    dense_reference_readout_hash: str,
    category_chunk: int,
    vectorized_strata: bool = False,
) -> CategoryStratifiedEvaluationMatrices:
    """Reduce train-side category matrices without census-sized host planes.

    The former NumPy implementation formed calibrated-logit, probability,
    BCE, and correctness arrays over the complete ``contexts x classes``
    census simultaneously, twice.  At ImageNet scale that is tens of GiB of
    short-lived host storage after the readouts already exist on device.

    This path keeps the exact row and class axes, visits the class axis in a
    fixed declared order, and reduces each true-label stratum before moving
    only the final ``classes x classes`` matrices to the host.  It changes no
    fit, threshold, response, or pruning decision; it is solely the
    deterministic execution strategy for descriptive train-side matrices.

    Exactly as the host path, the substituted functional
    of a tolerated bank carries its unready classes as NaN columns with
    explicit ids; the ordinary functional stays strict.

    ``vectorized_strata``: when every class stratum has the same
    size (the terminal bank's ``min(n_c, 256)`` rule gives 256 rows per
    class), each chunk's per-stratum means are ONE ``reshape(width, count,
    columns).mean(dim=1)`` instead of ``width`` segment means (1,000 small
    kernels per output per chunk at ImageNet scale).  The class-axis chunk
    and every elementwise op are the same; each stratum mean is the same
    mean over the same rows, batched into one reduction, so the matrices
    equal the segment loop's.  Unequal strata take the
    segment loop.
    """

    if torch is None:
        raise RuntimeError("streamed category reduction requires PyTorch")
    checked_functional = CalibrationFunctional(functional)
    width = int(bank.class_ids.size)
    chunk_width = int(category_chunk)
    if chunk_width <= 0:
        raise CalibrationContractError("category reduction chunk must be positive")
    row_values = torch.as_tensor(mask_rows)
    exclusion_plan = (
        dense_exclusion_by_category
        if isinstance(
            dense_exclusion_by_category, _DenseExclusionStreamingPlan
        )
        else None
    )
    exclusion_values = (
        None
        if exclusion_plan is not None
        else torch.as_tensor(
            dense_exclusion_by_category,
            device=row_values.device,
            dtype=torch.float64,
        )
    )
    label_values = torch.as_tensor(
        labels,
        device=row_values.device,
        dtype=torch.int64,
    ).reshape(-1)
    count_values = torch.as_tensor(
        counts,
        device=row_values.device,
        dtype=torch.int64,
    ).reshape(-1)
    expected_shape = (int(label_values.numel()), width)
    if (
        tuple(row_values.shape) != expected_shape
        or (
            exclusion_plan is not None
            and exclusion_plan.shape != (width, expected_shape[0])
        )
        or (
            exclusion_values is not None
            and tuple(exclusion_values.shape) != (width, expected_shape[0])
        )
        or tuple(count_values.shape) != (width,)
        or int(count_values.sum().item()) != expected_shape[0]
        or bool((count_values <= 0).any().item())
        or not bool(torch.isfinite(row_values).all().item())
        or (
            exclusion_values is not None
            and not bool(torch.isfinite(exclusion_values).all().item())
        )
    ):
        raise CalibrationContractError(
            "streamed training category matrix source axes are invalid"
        )
    expected_labels = torch.repeat_interleave(
        torch.arange(width, device=row_values.device, dtype=torch.int64),
        count_values,
    )
    if not bool(torch.equal(label_values, expected_labels)):
        raise CalibrationContractError(
            "streamed training category labels differ from ordered strata"
        )

    scale_host, offset_host, center_host, unready = bank.evaluation_affine_arrays(
        checked_functional
    )
    class_ids = np.asarray(bank.class_ids, dtype=np.int64)
    ready = _category_ready_columns(class_ids, unready)
    if ready is not None:
        # Zero placeholder affines for the carried columns (overwritten with
        # NaN on the host below); ready columns are untouched, and every
        # device operation is elementwise or per column.
        scale_host, offset_host, center_host = (
            np.where(ready, array, 0.0)
            for array in (scale_host, offset_host, center_host)
        )
    # Bank arrays are deliberately bytes-backed and non-writeable.  Construct
    # fresh device tensors instead of wrapping those NumPy buffers: PyTorch
    # otherwise warns that a write could mutate immutable evidence storage.
    scale = torch.tensor(
        np.array(scale_host, dtype=np.float64, copy=True),
        device=row_values.device,
        dtype=torch.float64,
    )
    offset = torch.tensor(
        np.array(offset_host, dtype=np.float64, copy=True),
        device=row_values.device,
        dtype=torch.float64,
    )
    center = torch.tensor(
        np.array(center_host, dtype=np.float64, copy=True),
        device=row_values.device,
        dtype=torch.float64,
    )
    outputs = {
        name: torch.empty(
            (width, width), device=row_values.device, dtype=torch.float64
        )
        for name in (
            "mean_functional_input",
            "mean_calibrated_logit",
            "mean_probability",
            "mean_bce",
            "binary_accuracy",
        )
    }
    split_sizes = tuple(int(value) for value in count_values.cpu().tolist())
    uniform_count = (
        split_sizes[0]
        if vectorized_strata and split_sizes and len(set(split_sizes)) == 1
        else None
    )

    def _stratum_means(values: Any) -> Any:
        if uniform_count is not None:
            return values.reshape(
                width, uniform_count, int(values.shape[1])
            ).mean(dim=1)
        return torch.stack(
            tuple(
                segment.mean(dim=0)
                for segment in values.split(split_sizes, dim=0)
            ),
            dim=0,
        )

    for start in range(0, width, chunk_width):
        stop = min(width, start + chunk_width)
        raw = row_values[:, start:stop].to(torch.float64)
        calibrated = raw.sub(center[start:stop]).mul_(scale[start:stop]).add_(
            offset[start:stop]
        )
        outputs["mean_functional_input"][:, start:stop] = _stratum_means(raw)
        if (
            checked_functional
            is CalibrationFunctional.SUBSTITUTED_TARGET_AFFINE_DENSE_EXCLUSION
        ):
            columns = torch.arange(
                start, stop, device=row_values.device, dtype=torch.int64
            )
            fixed = (
                exclusion_plan.select(columns)
                if exclusion_plan is not None
                else exclusion_values[start:stop]
            )
            calibrated.sub_(fixed.t())
        outputs["mean_calibrated_logit"][:, start:stop] = _stratum_means(
            calibrated
        )
        probability = torch.sigmoid(calibrated)
        outputs["mean_probability"][:, start:stop] = _stratum_means(probability)
        targets = label_values[:, None] == torch.arange(
            start, stop, device=row_values.device, dtype=torch.int64
        )[None, :]
        target_float = targets.to(torch.float64)
        bce = (
            torch.clamp_min(calibrated, 0.0)
            - calibrated * target_float
            + torch.log1p(torch.exp(-torch.abs(calibrated)))
        )
        outputs["mean_bce"][:, start:stop] = _stratum_means(bce)
        outputs["binary_accuracy"][:, start:stop] = _stratum_means(
            ((calibrated >= 0.0) == targets).to(torch.float64)
        )

    host = {
        name: value.detach().cpu().numpy().copy() for name, value in outputs.items()
    }
    if any(not np.isfinite(value).all() for value in host.values()):
        raise CalibrationContractError(
            "streamed training category reduction produced non-finite matrices"
        )
    if ready is not None:
        for name in (
            "mean_calibrated_logit",
            "mean_probability",
            "mean_bce",
            "binary_accuracy",
        ):
            host[name][:, ~ready] = np.nan
    labels_host = label_values.detach().cpu().numpy().copy()
    counts_host = count_values.detach().cpu().numpy().copy()
    diagonal = np.eye(width, dtype=np.bool_)
    sensitivity = np.where(diagonal, host["binary_accuracy"], 0.0)
    specificity = np.where(~diagonal, host["binary_accuracy"], 0.0)
    evaluation_hash = content_hash(
        _category_training_evaluation_hash_payload(
            bank=bank,
            functional=checked_functional,
            mask_readout_hash=mask_readout_hash,
            dense_reference_readout_hash=dense_reference_readout_hash,
            class_ids=class_ids,
            labels=labels_host,
            counts=counts_host,
            mean_functional_input=host["mean_functional_input"],
            mean_calibrated_logit=host["mean_calibrated_logit"],
            mean_probability=host["mean_probability"],
            mean_bce=host["mean_bce"],
            binary_accuracy=host["binary_accuracy"],
            unready_class_ids=unready,
        ),
        prefix="irg-category-training-evaluation-",
    )
    return CategoryStratifiedEvaluationMatrices(
        evaluation_hash=evaluation_hash,
        functional=checked_functional,
        class_ids=class_ids,
        labels=labels_host,
        stratum_counts=counts_host,
        mean_functional_input=host["mean_functional_input"],
        mean_calibrated_logit=host["mean_calibrated_logit"],
        mean_probability=host["mean_probability"],
        mean_bce=host["mean_bce"],
        binary_accuracy=host["binary_accuracy"],
        sensitivity_component=sensitivity,
        sensitivity_defined=diagonal,
        specificity_component=specificity,
        specificity_defined=~diagonal,
        unready_class_ids=unready,
    )


# ---------------------------------------------------------------------------
# Terminal VALIDATION category matrices on the device.
#
# A NumPy capture evaluates each frozen functional in float64 over the
# complete [validation rows x classes] plane (about 50M elements): four
# immutable 400 MB row planes per evaluation (inputs, calibrated logits,
# probabilities, BCE), bytes-backed copies and whole-plane checks of each, a
# content hash of every plane, then a per-class boolean-mask reduction.  Only
# the stratified [classes x classes] matrices leave the capture.
#
# This function computes the same five stratified matrices with the same
# formulas in torch float64 on the readout device, visiting the class axis in
# fixed chunks and reducing each true-label stratum before anything reaches
# the host (the construction the training-side matrices already use).  Same
# inputs (the float32 validation readouts widened to float64), same frozen
# affines, same stable dense-exclusion log-sum-exp, same stable BCE, same
# threshold rule; float64 throughout.  Only elementwise transcendental
# implementations and the summation order differ, at the float64 ulp level.
#
# ``evaluation_hash`` binds the matrices to the bank, the functional, the
# validation partition and the exact validation readout hashes; the row
# planes it used to hash are intermediates that are never stored.
# ---------------------------------------------------------------------------

FROZEN_CATEGORY_VALIDATION_DEVICE_EVALUATION_SCHEMA = (
    "irg_frozen_category_validation_evaluation_device_v1"
)
_VALIDATION_DEVICE_CLASS_CHUNK = 128
PRIMED_VALIDATION_READOUTS_SCHEMA = "irg_primed_terminal_validation_readouts_v1"


@dataclass(frozen=True)
class _PrimedValidationReadouts:
    """One post-lock (mask, dense) validation forward kept on the device."""

    lane_rows: Mapping[str, Any]
    labels: Any
    context_ids: tuple[str, ...]
    positions: Mapping[str, int]
    batch_factory: Any
    # Which prime produced these rows (a capture compared against rows of
    # the same prime compares one forward with itself), and where the dense
    # lane came from ("primed_forward" or the "dense_validation_table").
    generation: int = 0
    dense_source: str = "primed_forward"


def _validation_reduction_device(device: Any) -> Any:
    """The readout device, or CPU where float64 is unavailable (MPS)."""

    resolved = torch.device(device)
    return torch.device("cpu") if resolved.type == "mps" else resolved


def _stratum_mean_reducer(counts: tuple[int, ...], row_count: int) -> Callable[[Any], Any]:
    """Per-stratum column means over contiguous, class-ordered strata."""

    width = len(counts)
    if width and all(count == counts[0] for count in counts):
        per_stratum = int(counts[0])

        def _equal(values: Any) -> Any:
            return values.reshape(width, per_stratum, int(values.shape[1])).mean(dim=1)

        return _equal

    def _ragged(values: Any) -> Any:
        return torch.stack(
            tuple(segment.mean(dim=0) for segment in values.split(counts, dim=0)),
            dim=0,
        )

    return _ragged


def _frozen_category_validation_moments_device(
    rows: Any, counts: tuple[int, ...]
) -> tuple[np.ndarray, np.ndarray] | None:
    """``_frozen_category_moments`` for equal strata in one pass; else None.

    Same float64 statistics per stratum: ``mean = sum / n`` and
    ``m2 = sumsq - sum**2 / n``.
    """

    width = len(counts)
    if not width or any(count != counts[0] for count in counts):
        return None
    per_stratum = int(counts[0])
    device = _validation_reduction_device(rows.device)
    values = rows.to(device=device, dtype=torch.float64).reshape(
        width, per_stratum, int(rows.shape[1])
    )
    segment_sum = values.sum(dim=1)
    segment_sumsq = (values * values).sum(dim=1)
    mean = (segment_sum / float(per_stratum)).cpu().numpy()
    m2 = (segment_sumsq - segment_sum.square() / float(per_stratum)).cpu().numpy()
    return mean, m2


def _frozen_category_validation_matrices_device(
    *,
    bank: FrozenCategoryCalibrationBank,
    functional: CalibrationFunctional,
    validation: ValidationPartition,
    mask_rows: Any,
    dense_exclusion: _DenseExclusionStreamingPlan | None,
    labels: tuple[int, ...],
    counts: tuple[int, ...],
    mask_readout_hash: str,
    dense_reference_readout_hash: str | None,
    class_chunk: int = _VALIDATION_DEVICE_CLASS_CHUNK,
) -> CategoryStratifiedEvaluationMatrices:
    """Validation matrices of one frozen functional, reduced on the device."""

    if torch is None:
        raise RuntimeError("device validation category matrices require PyTorch")
    checked = CalibrationFunctional(functional)
    substituted = (
        checked is CalibrationFunctional.SUBSTITUTED_TARGET_AFFINE_DENSE_EXCLUSION
    )
    if substituted != (dense_exclusion is not None):
        raise CalibrationContractError(
            "the dense-exclusion plan belongs to the substituted functional only"
        )
    # A writable copy: the bank's arrays are bytes-backed and read-only.
    class_ids = np.array(bank.class_ids, dtype=np.int64, copy=True)
    width = int(class_ids.size)
    row_count = len(validation.member_ids)
    count_tuple = tuple(int(value) for value in counts)
    device = _validation_reduction_device(mask_rows.device)
    raw_rows = mask_rows.to(device=device)
    label_values = torch.as_tensor(labels, device=device, dtype=torch.int64).reshape(-1)
    # The fail-closed axis checks of the host evaluation and reduction.
    if (
        tuple(raw_rows.shape) != (row_count, width)
        or tuple(label_values.shape) != (row_count,)
        or len(count_tuple) != width
        or any(value <= 0 for value in count_tuple)
        or sum(count_tuple) != row_count
        or not bool(torch.isfinite(raw_rows).all().item())
    ):
        raise CalibrationContractError(
            "validation category matrix source axes are invalid"
        )
    expected_labels = torch.repeat_interleave(
        torch.as_tensor(class_ids, device=device, dtype=torch.int64),
        torch.as_tensor(count_tuple, device=device, dtype=torch.int64),
    )
    if not bool(torch.equal(label_values, expected_labels)):
        raise CalibrationContractError(
            "validation category labels differ from the ordered class strata"
        )
    if dense_exclusion is not None and dense_exclusion.shape != (width, row_count):
        raise CalibrationContractError(
            "dense-reference logits differ from the validation/class axes"
        )
    scale_host, offset_host, center_host, unready = bank.evaluation_affine_arrays(
        checked
    )
    ready = _category_ready_columns(class_ids, unready)
    if ready is not None:
        # Finite placeholders on carried columns (NaN-overwritten below); every
        # device operation is elementwise or per column.
        scale_host, offset_host, center_host = (
            np.where(ready, array, 0.0)
            for array in (scale_host, offset_host, center_host)
        )
    scale, offset, center = (
        torch.tensor(np.array(array, dtype=np.float64, copy=True), device=device)
        for array in (scale_host, offset_host, center_host)
    )
    names = (
        "mean_functional_input",
        "mean_calibrated_logit",
        "mean_probability",
        "mean_bce",
        "binary_accuracy",
    )
    outputs = {
        name: torch.empty((width, width), device=device, dtype=torch.float64)
        for name in names
    }
    stratum_means = _stratum_mean_reducer(count_tuple, row_count)
    class_index = torch.as_tensor(class_ids, device=device, dtype=torch.int64)
    chunk = max(1, int(class_chunk))
    for start in range(0, width, chunk):
        stop = min(width, start + chunk)
        raw = raw_rows[:, start:stop].to(torch.float64)
        calibrated = (raw - center[start:stop]) * scale[start:stop] + offset[start:stop]
        if dense_exclusion is not None:
            calibrated = calibrated - dense_exclusion.select(
                torch.arange(start, stop, device=device, dtype=torch.int64)
            ).t()
        if ready is None:
            if not bool(torch.isfinite(calibrated).all().item()):
                raise CalibrationContractError(
                    "frozen affine application produced non-finite calibrated logits"
                )
        else:
            ready_chunk = torch.as_tensor(ready[start:stop], device=device)
            if not bool(torch.isfinite(calibrated[:, ready_chunk]).all().item()):
                raise CalibrationContractError(
                    "frozen affine application produced non-finite calibrated logits"
                )
            calibrated = torch.where(
                ready_chunk.unsqueeze(0), calibrated, torch.zeros_like(calibrated)
            )
        targets = label_values.unsqueeze(1) == class_index[start:stop].unsqueeze(0)
        target_float = targets.to(torch.float64)
        # max(x, 0) - x*y + log1p(exp(-abs(x))) is the stable Bernoulli BCE.
        bce = (
            torch.clamp_min(calibrated, 0.0)
            - calibrated * target_float
            + torch.log1p(torch.exp(-torch.abs(calibrated)))
        )
        outputs["mean_functional_input"][:, start:stop] = stratum_means(raw)
        outputs["mean_calibrated_logit"][:, start:stop] = stratum_means(calibrated)
        outputs["mean_probability"][:, start:stop] = stratum_means(
            torch.sigmoid(calibrated)
        )
        outputs["mean_bce"][:, start:stop] = stratum_means(bce)
        outputs["binary_accuracy"][:, start:stop] = stratum_means(
            ((calibrated >= 0.0) == targets).to(torch.float64)
        )
    host = {name: value.detach().cpu().numpy().copy() for name, value in outputs.items()}
    if any(not np.isfinite(value).all() for value in host.values()):
        raise CalibrationContractError(
            "validation category reduction produced non-finite matrices"
        )
    if ready is not None:
        for name in names[1:]:
            host[name][:, ~ready] = np.nan
    labels_host = np.asarray(labels, dtype=np.int64)
    counts_host = np.asarray(count_tuple, dtype=np.int64)
    diagonal = np.eye(width, dtype=np.bool_)
    payload: dict[str, Any] = {
        "schema": FROZEN_CATEGORY_VALIDATION_DEVICE_EVALUATION_SCHEMA,
        "role": "terminal_validation_observation_only",
        "bank_hash": bank.content_hash,
        "validation_partition_hash": validation.content_hash,
        "functional": checked.value,
        "mask_validation_readout_hash": str(mask_readout_hash),
        "class_ids": class_ids,
        "labels": labels_host,
        "counts": counts_host,
        **{name: host[name] for name in names},
    }
    if dense_reference_readout_hash is not None:
        payload["dense_reference_validation_readout_hash"] = str(
            dense_reference_readout_hash
        )
    if unready:
        payload["unready_class_ids"] = tuple(unready)
    return CategoryStratifiedEvaluationMatrices(
        evaluation_hash=content_hash(
            payload, prefix="irg-category-validation-evaluation-"
        ),
        functional=checked,
        class_ids=class_ids,
        labels=labels_host,
        stratum_counts=counts_host,
        mean_functional_input=host["mean_functional_input"],
        mean_calibrated_logit=host["mean_calibrated_logit"],
        mean_probability=host["mean_probability"],
        mean_bce=host["mean_bce"],
        binary_accuracy=host["binary_accuracy"],
        sensitivity_component=np.where(diagonal, host["binary_accuracy"], 0.0),
        sensitivity_defined=diagonal,
        specificity_component=np.where(~diagonal, host["binary_accuracy"], 0.0),
        specificity_defined=~diagonal,
        unready_class_ids=unready,
    )


def _final_mask_bank_tolerates_substituted_unready(
    states: Sequence[FrozenAffineCalibrationState],
    *,
    mode: CalibrationBankMode,
    mask_hash: str,
    dense_reference_mask_hash: str,
) -> bool:
    """May this terminal bank be frozen tolerant?

    True exactly for a claim-bearing FINAL-mask bank (its mask is not its own
    dense reference) in which every ``ORDINARY_OVR`` state is ready and at
    least one ``SUBSTITUTED_TARGET_AFFINE_DENSE_EXCLUSION`` state is not.
    The ordinary matrices then stay claim-bearing and complete, while the
    substituted unready classes are carried as NaN columns with explicit ids.
    Any unready ordinary state, a dense bank, or a partial test bank returns
    False, so the caller builds strictly and raises exactly as before.
    """

    if CalibrationBankMode(mode) is not CalibrationBankMode.CLAIM_BEARING_1000:
        return False
    if str(mask_hash) == str(dense_reference_mask_hash):
        return False
    ordinary_ready = all(
        state.ready
        for state in states
        if state.functional is CalibrationFunctional.ORDINARY_OVR
    )
    substituted_unready = any(
        not state.ready
        for state in states
        if state.functional
        is CalibrationFunctional.SUBSTITUTED_TARGET_AFFINE_DENSE_EXCLUSION
    )
    return bool(ordinary_ready and substituted_unready)


FROZEN_CATEGORY_CAPTURE_COMPLETE_STATUS = "complete"
FROZEN_CATEGORY_CAPTURE_SUBSTITUTED_PARTIAL_STATUS = (
    "captured_substituted_partially_unconverged"
)


def frozen_category_bank_capture_status(
    bank: FrozenCategoryCalibrationBank,
) -> dict[str, Any]:
    """Receipt status of a capture evaluated under ``bank``.

    ``complete`` when no class is carried; otherwise
    ``captured_substituted_partially_unconverged`` with the carried ids per
    functional (the ordinary list is always empty: it is never carried).
    """

    if not isinstance(bank, FrozenCategoryCalibrationBank):
        raise TypeError("capture status requires a typed frozen bank")
    if bank.tolerate_unconverged and bank.unready_class_ids(
        CalibrationFunctional.ORDINARY_OVR
    ):
        raise CalibrationContractError(
            "a tolerated category bank must have every ordinary state ready"
        )
    by_functional = {
        functional.value: [
            int(class_id) for class_id in bank.carried_unready_class_ids(functional)
        ]
        for functional in CalibrationFunctional
    }
    carried = sorted({class_id for ids in by_functional.values() for class_id in ids})
    return {
        "status": (
            FROZEN_CATEGORY_CAPTURE_SUBSTITUTED_PARTIAL_STATUS
            if carried
            else FROZEN_CATEGORY_CAPTURE_COMPLETE_STATUS
        ),
        "unconverged_count": int(len(carried)),
        "unconverged_class_ids": carried,
        "unconverged_class_ids_by_functional": by_functional,
        "carried_functional": (
            CalibrationFunctional.SUBSTITUTED_TARGET_AFFINE_DENSE_EXCLUSION.value
            if carried
            else None
        ),
        "nan_policy": (
            "substituted_classifier_columns_nan_at_unconverged_class_ids_"
            "ordinary_complete_and_strict"
            if carried
            else None
        ),
    }


# Provenance bookkeeping of the terminal bank
# (the readout D2H copies and sha256 content hashes, the per-chunk receipt
# hashes) runs on ONE helper thread while the main thread keeps the device
# busy with the fits; every result is joined before it is consumed, in the
# original order.  hashlib and the device copy release the GIL.  The host
# copies of the two 1 GB readouts land in reusable pinned staging buffers
# instead of fresh pageable allocations (page faults, then a second .copy()).
#
# Stream ordering: the helper thread runs on its own
# CUDA stream context, so a readout produced by kernels on the main thread's
# stream is NOT ordered before a copy the helper enqueues.  The main thread
# therefore records a ready event on its current stream when it hands a
# readout over (``_readout_ready_marker``), and the helper makes its side
# copy stream wait on that event before copying (``_CudaReadoutCopier``).
# The tensor is ``record_stream``-ed on the copy stream so the caching
# allocator cannot recycle its block while the copy is in flight, and each
# pinned staging slot is held under its own lock from the copy until the
# hash that reads it completes, so a later bank can never overwrite a slot
# that is still being hashed.
_PROVENANCE_POOL_LOCK = threading.Lock()
_PROVENANCE_POOL: ThreadPoolExecutor | None = None


def _provenance_pool() -> ThreadPoolExecutor:
    global _PROVENANCE_POOL
    with _PROVENANCE_POOL_LOCK:
        if _PROVENANCE_POOL is None:
            _PROVENANCE_POOL = ThreadPoolExecutor(
                max_workers=1, thread_name_prefix="terminal-provenance"
            )
        return _PROVENANCE_POOL


def _reset_provenance_pool_after_fork() -> None:  # pragma: no cover - fork hook
    global _PROVENANCE_POOL, _PROVENANCE_POOL_LOCK
    _PROVENANCE_POOL_LOCK = threading.Lock()
    _PROVENANCE_POOL = None
    

if hasattr(os, "register_at_fork"):
    os.register_at_fork(after_in_child=_reset_provenance_pool_after_fork)
















def _resolved_chunk_receipts(
    chunk_receipts: Sequence[Mapping[str, Any]],
) -> tuple[Mapping[str, Any], ...]:
    """Join the deferred per-chunk receipt hashes, in chunk order."""

    resolved = []
    for item in chunk_receipts:
        row = dict(item)
        value = row["fit_receipt_hash"]
        if isinstance(value, Future):
            row["fit_receipt_hash"] = value.result()
        resolved.append(row)
    return tuple(resolved)


# The terminal-fit execution path, pinned on the
# provider at first use exactly like the convergence test, so the
# fit, its request identity and the dense-fit cache key can never disagree
# within one provider's lifetime.
def _attach_v6_gate_summary(error: BaseException, summary: Any) -> None:
    """Attach a bank's v6 gate summary and threshold receipt to an error.

    The pilot's degradation receipt reads ``missing_cell_threshold`` and
    ``v6_gate_summary`` from the error it catches, so a degraded bank is
    receipted with every missing category and the threshold outcome.
    """

    if not isinstance(summary, Mapping):
        return
    try:
        error.v6_gate_summary = dict(summary)  # type: ignore[attr-defined]
        threshold = summary.get("missing_cell_threshold")
        if isinstance(threshold, Mapping):
            error.missing_cell_threshold = dict(threshold)  # type: ignore[attr-defined]
    except (AttributeError, TypeError):  # pragma: no cover - slotted errors
        pass


def _bank_module_carries_ordinary_missing() -> bool:
    """Can the frozen-bank module carry an unavailable ORDINARY column?

    Carriage of a missing ordinary category needs the bank module to
    admit NaN-carried ordinary columns (today only the substituted functional
    may carry them).  Until it declares
    ``ORDINARY_MISSING_CARRIAGE_SUPPORTED``, any missing ordinary category
    takes the typed threshold abort, receipted, instead of an untyped
    failure in the matrix readers.
    """

    from mechanistic_systems.measurement import frozen_category_calibration

    return bool(
        getattr(frozen_category_calibration, "ORDINARY_MISSING_CARRIAGE_SUPPORTED", False)
    )


_FIT_BUNDLE_HASH_MEMO: "OrderedDict[int, tuple[Any, str]]" = OrderedDict()
_FIT_BUNDLE_HASH_MEMO_ENTRIES = 16
_FIT_BUNDLE_HASH_MEMO_LOCK = threading.Lock()


@dataclass(frozen=True, slots=True)
class FrozenCategoryCalibrationFitBundle:
    """One train-fitted bank plus exact source and setup-scope evidence.

    The bundle is an explicit handoff object, not execution authority.  Its
    bank is fit only from ``training_context_ids``; the two raw-readout hashes
    bind the actual model outputs consumed by the ordinary and substituted
    fits.  Dense-reference logits are not retained: the substituted affine
    states are sufficient after fitting, while validation obtains a fresh
    dense reference on its own exact partition.
    """

    bank: FrozenCategoryCalibrationBank
    request_hash: str
    mask_hash: str
    dense_reference_mask_hash: str
    model_state_hash: str
    provider_identity: str
    dense_reference_training_identity: str
    training_context_ids: tuple[str, ...]
    training_labels: np.ndarray = field(repr=False, compare=False)
    training_counts: np.ndarray = field(repr=False, compare=False)
    training_raw_logit_mean: np.ndarray = field(repr=False, compare=False)
    training_raw_logit_m2: np.ndarray = field(repr=False, compare=False)
    ordinary_training_matrices: CategoryStratifiedEvaluationMatrices
    substituted_training_matrices: CategoryStratifiedEvaluationMatrices
    mask_training_readout_hash: str
    dense_reference_training_readout_hash: str
    layout_content_hash: str
    layout_block_assignment_hash: str
    layout_stratification_rule: str
    ordinary_selected_strength: tuple[str, ...]
    substituted_selected_strength: tuple[str, ...]
    ordinary_fit_receipt_hashes: tuple[str, ...]
    substituted_fit_receipt_hashes: tuple[str, ...]

    schema = "irg_frozen_category_calibration_fit_bundle_v2"
    grants_execution_authority = False
    grants_selection_authority = False
    grants_pruning_commit_authority = False
    grants_promotion_authority = False

    def __post_init__(self) -> None:
        if not isinstance(self.bank, FrozenCategoryCalibrationBank):
            raise TypeError("category fit bundle requires a typed frozen bank")
        for name in (
            "request_hash",
            "mask_hash",
            "dense_reference_mask_hash",
            "model_state_hash",
            "provider_identity",
            "dense_reference_training_identity",
            "mask_training_readout_hash",
            "dense_reference_training_readout_hash",
            "layout_content_hash",
            "layout_block_assignment_hash",
            "layout_stratification_rule",
        ):
            object.__setattr__(
                self,
                name,
                _exact_category_identity(getattr(self, name), name=name),
            )
        contexts = tuple(
            _exact_category_identity(value, name="training context ID")
            for value in self.training_context_ids
        )
        if not contexts or len(set(contexts)) != len(contexts):
            raise CalibrationContractError(
                "training context IDs must be nonempty and globally unique"
            )
        width = int(self.bank.class_ids.size)
        labels = _immutable_category_array(
            self.training_labels,
            dtype="<i8",
            name="training labels",
            shape=(len(contexts),),
        )
        counts = _immutable_category_array(
            self.training_counts,
            dtype="<i8",
            name="training counts",
            shape=(width,),
        )
        if np.any(counts <= 0) or int(np.sum(counts, dtype=np.int64)) != len(
            contexts
        ):
            raise CalibrationContractError(
                "training counts must positively partition the training rows"
            )
        expected_labels = np.repeat(self.bank.class_ids, counts)
        if not np.array_equal(labels, expected_labels):
            raise CalibrationContractError(
                "training labels differ from the ordered class populations"
            )
        mean = _immutable_category_array(
            self.training_raw_logit_mean,
            dtype="<f8",
            name="training raw-logit mean",
            shape=(width, width),
            finite=True,
        )
        m2 = _immutable_category_array(
            self.training_raw_logit_m2,
            dtype="<f8",
            name="training raw-logit M2",
            shape=(width, width),
            finite=True,
        )
        if np.any(m2 < -1e-12):
            raise CalibrationContractError("training raw-logit M2 is negative")
        if (
            not isinstance(
                self.ordinary_training_matrices,
                CategoryStratifiedEvaluationMatrices,
            )
            or not isinstance(
                self.substituted_training_matrices,
                CategoryStratifiedEvaluationMatrices,
            )
        ):
            raise TypeError("category fit bundle requires typed training matrices")
        ordinary_matrices = self.ordinary_training_matrices
        substituted_matrices = self.substituted_training_matrices
        if (
            ordinary_matrices.functional is not CalibrationFunctional.ORDINARY_OVR
            or substituted_matrices.functional
            is not CalibrationFunctional.SUBSTITUTED_TARGET_AFFINE_DENSE_EXCLUSION
            or not np.array_equal(ordinary_matrices.class_ids, self.bank.class_ids)
            or not np.array_equal(substituted_matrices.class_ids, self.bank.class_ids)
            or not np.array_equal(ordinary_matrices.labels, labels)
            or not np.array_equal(substituted_matrices.labels, labels)
            or not np.array_equal(ordinary_matrices.stratum_counts, counts)
            or not np.array_equal(substituted_matrices.stratum_counts, counts)
        ):
            raise CalibrationContractError(
                "training raw and calibrated matrix axes differ"
            )
        # A training matrix may carry NaN columns only
        # where its bank says so -- never for the ordinary functional.
        for matrices in (ordinary_matrices, substituted_matrices):
            if tuple(matrices.unready_class_ids) != self.bank.carried_unready_class_ids(
                matrices.functional
            ):
                raise CalibrationContractError(
                    "training matrices carry unready classes their bank does not"
                )
        identity = self.bank.identity
        if identity.mask_identity != self.mask_hash:
            raise CalibrationContractError("bundle mask differs from its bank")
        if identity.reference_identity != self.dense_reference_training_identity:
            raise CalibrationContractError(
                "bundle dense-reference identity differs from its bank"
            )
        if identity.model_identity != self.model_state_hash:
            raise CalibrationContractError("bundle model differs from its bank")
        if identity.training_member_ids != contexts:
            raise CalibrationContractError(
                "bundle training order differs from the bank membership"
            )
        ordinary_receipts = tuple(
            _exact_category_identity(value, name="ordinary fit receipt hash")
            for value in self.ordinary_fit_receipt_hashes
        )
        substituted_receipts = tuple(
            _exact_category_identity(value, name="substituted fit receipt hash")
            for value in self.substituted_fit_receipt_hashes
        )
        if (
            not ordinary_receipts
            or not substituted_receipts
            or any(not value for value in ordinary_receipts + substituted_receipts)
        ):
            raise CalibrationContractError(
                "category fit bundle requires both fit-receipt families"
            )
        ordinary_selected = tuple(
            _exact_category_identity(value, name="ordinary selected strength")
            for value in self.ordinary_selected_strength
        )
        substituted_selected = tuple(
            _exact_category_identity(value, name="substituted selected strength")
            for value in self.substituted_selected_strength
        )
        if (
            len(ordinary_selected) != width
            or len(substituted_selected) != width
            or any(not value for value in ordinary_selected + substituted_selected)
        ):
            raise CalibrationContractError(
                "selected regularization strengths must cover every class"
            )
        object.__setattr__(self, "training_context_ids", contexts)
        object.__setattr__(self, "training_labels", labels)
        object.__setattr__(self, "training_counts", counts)
        object.__setattr__(self, "training_raw_logit_mean", mean)
        object.__setattr__(self, "training_raw_logit_m2", m2)
        object.__setattr__(self, "ordinary_fit_receipt_hashes", ordinary_receipts)
        object.__setattr__(
            self, "substituted_fit_receipt_hashes", substituted_receipts
        )
        object.__setattr__(self, "ordinary_selected_strength", ordinary_selected)
        object.__setattr__(
            self, "substituted_selected_strength", substituted_selected
        )

    def to_manifest(self) -> dict[str, Any]:
        return {
            "schema": self.schema,
            "authority_ceiling": self.bank.authority_ceiling,
            "request_hash": self.request_hash,
            "bank_hash": self.bank.content_hash,
            "bank_identity_hash": self.bank.identity.content_hash,
            "bank": self.bank.to_payload(),
            "mask_hash": self.mask_hash,
            "dense_reference_mask_hash": self.dense_reference_mask_hash,
            "model_state_hash": self.model_state_hash,
            "provider_identity": self.provider_identity,
            "dense_reference_training_identity": (
                self.dense_reference_training_identity
            ),
            "training_context_ids": self.training_context_ids,
            "training_labels": self.training_labels,
            "training_counts": self.training_counts,
            "training_raw_logit_mean": self.training_raw_logit_mean,
            "training_raw_logit_m2": self.training_raw_logit_m2,
            "ordinary_training_matrices": (
                self.ordinary_training_matrices.to_payload()
            ),
            "substituted_training_matrices": (
                self.substituted_training_matrices.to_payload()
            ),
            "mask_training_readout_hash": self.mask_training_readout_hash,
            "dense_reference_training_readout_hash": (
                self.dense_reference_training_readout_hash
            ),
            "layout_content_hash": self.layout_content_hash,
            "layout_block_assignment_hash": self.layout_block_assignment_hash,
            "layout_stratification_rule": self.layout_stratification_rule,
            "ordinary_selected_strength": self.ordinary_selected_strength,
            "substituted_selected_strength": (
                self.substituted_selected_strength
            ),
            "ordinary_fit_receipt_hashes": self.ordinary_fit_receipt_hashes,
            "substituted_fit_receipt_hashes": (
                self.substituted_fit_receipt_hashes
            ),
            "grants_execution_authority": False,
            "grants_selection_authority": False,
            "grants_pruning_commit_authority": False,
            "grants_promotion_authority": False,
        }

    @property
    def content_hash(self) -> str:
        # Every array of a bundle is
        # bytes-backed immutable and every other field is frozen, so its
        # manifest hash is a property of the object; registration, opening
        # and capture would otherwise re-hash it (~5 s per bank).
        key = id(self)
        with _FIT_BUNDLE_HASH_MEMO_LOCK:
            cached = _FIT_BUNDLE_HASH_MEMO.get(key)
            if cached is not None and cached[0] is self:
                _FIT_BUNDLE_HASH_MEMO.move_to_end(key)
                return cached[1]
        digest = content_hash(
            self.to_manifest(), prefix="irg-frozen-category-fit-bundle-"
        )
        with _FIT_BUNDLE_HASH_MEMO_LOCK:
            _FIT_BUNDLE_HASH_MEMO[key] = (self, digest)
            _FIT_BUNDLE_HASH_MEMO.move_to_end(key)
            while len(_FIT_BUNDLE_HASH_MEMO) > _FIT_BUNDLE_HASH_MEMO_ENTRIES:
                _FIT_BUNDLE_HASH_MEMO.popitem(last=False)
        return digest


@dataclass(frozen=True, slots=True)
class FrozenCategoryValidationOpenToken:
    """Provider-issued one-way seal proving category fitting has closed."""

    provider_identity: str
    model_state_hash: str
    frozen_bundle_hashes: tuple[str, ...]

    schema = "irg_frozen_category_validation_open_token_v1"
    grants_execution_authority = False

    def __post_init__(self) -> None:
        provider_identity = _exact_category_identity(
            self.provider_identity,
            name="validation-open provider identity",
        )
        model_state_hash = _exact_category_identity(
            self.model_state_hash,
            name="validation-open model-state hash",
        )
        hashes = tuple(
            sorted(
                _exact_category_identity(
                    value,
                    name="validation-open frozen bundle hash",
                )
                for value in self.frozen_bundle_hashes
            )
        )
        if (
            not hashes
            or len(set(hashes)) != len(hashes)
        ):
            raise CalibrationContractError(
                "validation-open token identities must be nonempty and unique"
            )
        object.__setattr__(self, "provider_identity", provider_identity)
        object.__setattr__(self, "model_state_hash", model_state_hash)
        object.__setattr__(self, "frozen_bundle_hashes", hashes)

    @property
    def content_hash(self) -> str:
        return content_hash(
            {
                "schema": self.schema,
                "provider_identity": self.provider_identity,
                "model_state_hash": self.model_state_hash,
                "frozen_bundle_hashes": self.frozen_bundle_hashes,
                "grants_execution_authority": False,
            },
            prefix="irg-category-validation-open-",
        )


