        """Readout receipts waiting for their CUDA events (finalized in order)."""

        queue = self.__dict__.get("_deferred_readout_receipt_queue")
        if queue is None:
            queue = self.__dict__["_deferred_readout_receipt_queue"] = DeferredReceipts()
        return queue

