    def _coacquire_calibration_and_oracle_readouts(
        self,
        mask: HardMask,
        *,
        calibration_context_ids: tuple[str, ...],
        oracle_context_ids: tuple[str, ...],
        oracle_parent_mask: HardMask | None = None,
    ) -> Mapping[str, Any]:
        """Fill one physical readout cache from two independent logical roles.

        This method is deliberately below statistical inference.  It maps the
        independently generated calibration and adjudication draw identities
        to physical source images, takes an outcome-independent ordered union,
        and evaluates that union for the candidate. A paired decision's
        parent acquires only its own adjudication sources. Neither role's
        logical sequence is changed and no sufficient statistic is updated
        here; each role later materializes only its own sequence from the
        shared device-resident source cache.
        """

        calibration_ids = tuple(str(value) for value in calibration_context_ids)
        oracle_ids = tuple(str(value) for value in oracle_context_ids)
        if not calibration_ids or not oracle_ids:
            raise ValueError(
                "fused calibration/oracle acquisition requires both roles"
            )
        calibration_sources = self._source_context_ids(
            calibration_ids,
            role="calibration_fit",
        )
        oracle_sources = self._source_context_ids(
            oracle_ids,
            role="proposal_adjudication",
        )
        physical_union = tuple(
            dict.fromkeys((*calibration_sources, *oracle_sources))
        )
        cache_key = (mask.mask_hash, self._readout_projection_hash)
        cache = self._readout_source_cache.setdefault(
            cache_key,
            _ProjectedReadoutSlab(device=self._device),
        )
        missing_before = sum(
            source_id not in cache for source_id in physical_union
        )
        parent_missing_before = (
            None
            if oracle_parent_mask is None
            else sum(
                source_id not in self._readout_source_cache.get(
                    (oracle_parent_mask.mask_hash, self._readout_projection_hash),
                    (),
                )
                for source_id in dict.fromkeys(oracle_sources)
            )
        )
        evaluations_before = int(self._physical_context_state_evaluations)
        started = time.perf_counter()
        # `context_ids` and the override are both the physical union because
        # this is a cache-fill operation, not a statistical materialization.
        # Statistical draw accounting occurs only when the two role-specific
        # sequences are subsequently requested through `_readouts`.
        self._readouts(
            (mask,),
            physical_union,
            role="calibration_fit",
            physical_execution_role="calibration_oracle_fused",
            source_context_ids_override=physical_union,
            count_statistical_draws=False,
            execution_batch_rows_override=self._fused_execution_batch_rows(
                paired=oracle_parent_mask is not None
            ),
        )
