    # NOTE (v4 sampling law): under the sealed without-replacement oracle the
    # confirm stream's "duplicate doubling" allowance below is INERT.  A
    # sealed permutation prefix cannot repeat a source context, so the
    # doubling can never be exercised; it is retained unchanged because the
    # with-replacement law still needs it and because removing it would move
    # the confirm query's request identity for every historical arm.
    def confirm_accept_replication(
        self,
        committed_masks: Mapping[str, np.ndarray],
        candidate_masks: Mapping[str, np.ndarray],
        *,
        query_id: str,
        layer_id: str,
        partition_id: str,
        proposal_index: int,
        confidence_level: float,
    ) -> Mapping[str, Any]:
        """Replicate a provisional accept on a disjoint confirm stream.

        Winner's curse accepts a step exactly when the select-stream noise
        dips favorably at the threshold. One independent class-resolved
        confirm packet, evaluated under the same frozen fits, de-biases that
        selection: the confirm estimate is symmetric around the true
        increment, so a truly-at-threshold step fails confirmation about
        half the time while a clearly safe step almost never does. Confirm
        rows are extraction-training draws from a stream keyed by the full
        proposal identity plus an accept-confirm tag, so they are
        decision-disjoint from every select draw by construction; they never
        alter any fit, score, or mask.
        """

        parent = self._hard_mask(committed_masks)
        candidate_mask = self._hard_mask(candidate_masks)
        removed = int(
            candidate_mask.removed_index_set_from(parent).count
        )
        if removed <= 0:
            raise ValueError("accept confirmation requires removed routes")
        counts = {
            stratum: int(self.provider.oracle_minimum_per_stratum)
            for stratum in self.provider._oracle_statistical_strata
        }
        stream_id = (
            "accept-confirm:"
            f"{query_id}:{layer_id}:{partition_id}:{proposal_index}:"
            f"{parent.mask_hash}:{candidate_mask.mask_hash}"
        )
        populations: dict[str, list[str]] = {}
        # With-replacement logical draws may repeat a physical row inside a
        # small stratum, and the stratified audit needs at least two unique
        # rows per stratum. Extend deficient strata deterministically (the
        # draw prefix property keeps earlier draws identical) until every
        # stratum holds two unique physical rows.
        for attempt in range(5):
            draws = self.provider._iid_draw_prefix(
                role="proposal_adjudication",
                stream_id=stream_id,
                counts=counts,
            )
            physical_ids = self.provider._source_context_ids(
                draws,
                role="proposal_adjudication",
            )
            populations = {}
            for draw_id, context_id in zip(draws, physical_ids):
                stratum = self.provider._context_stratum(
                    draw_id,
                    role="proposal_adjudication",
                )
                rows = populations.setdefault(stratum, [])
                if context_id not in rows:
                    rows.append(context_id)
            deficient = tuple(
                stratum
                for stratum, rows in populations.items()
                if len(rows) < 2
            )
            if not deficient:
                break
            for stratum in deficient:
                counts[stratum] = int(counts[stratum]) * 2
        else:
            raise RuntimeError(
                "accept confirmation could not assemble two unique rows "
                "per stratum"
            )
        sealed_populations = {
            stratum: tuple(rows)
            for stratum, rows in populations.items()
            if rows
        }
        raw_weights = {
            stratum: float(
                self.provider._oracle_statistical_weights[stratum]
            )
            for stratum in sealed_populations
        }
        weight_total = sum(raw_weights.values())
        weights = {
            stratum: value / weight_total
            for stratum, value in raw_weights.items()
        }
        audit = self.provider.evaluate_frozen_mask_bce_pair(
            parent,
            candidate_mask,
            evaluation_context_ids_by_stratum=sealed_populations,
            evaluation_stratum_weights=weights,
            batch_factory=self.provider.oracle_batch_factory,
            confidence_level=float(confidence_level),
            allow_optimization_row_reuse=True,
        )
        delta = audit["candidate_minus_reference_bce"]
        span = float(self._loss_span_certificate.estimate)
        confirm_sensitivity = float(delta["mean"]) / (
            span * float(removed)
        )
        return {
            "schema": "v0_accept_confirm_replication_v1",
            "confirm_stream_id": stream_id,
            "confirm_row_count": int(
                sum(len(rows) for rows in sealed_populations.values())
            ),
            "confirm_mean_sensitivity": confirm_sensitivity,
            "confirm_raw_increment": dict(delta),
            "positive_loss_span_estimate": span,
            "connection_delta": int(removed),
            "confirm_rows_alter_no_state": True,
            "pair_audit_context_design_hash": audit[
                "context_design_hash"
            ],
        }


